    static async BaixarFaturaPDF({ cgcFilial, numeroFatura }) {

        //cgcFilial = "164";
        //numeroFatura = "000001C";

        let token = localStorage.getItem("token");

        try {
            const url2 = IndexURI().baixar_fatura_pdf({ cgcFilial, numeroFatura });

            const response = await fetch(url2, {
                method: "GET",
                headers: {
                    Authorization: `Bearer ${token}`,
                    Accept: "application/pdf",
                },
            });

            const blob = await response.blob();
            const url = window.URL.createObjectURL(blob);

            const link = document.createElement("a");
            link.href = url;
            link.download = `fatura-${numeroFatura}.pdf`;
            document.body.appendChild(link);
            link.click();
            link.remove();

            window.URL.revokeObjectURL(url);

            return { sucesso: true };
        } catch (error) {
            console.error(error);
            return { sucesso: false, erros: error };
        }
    }
