import React, { useState, useEffect } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import "chart.js/auto";
import ChartDataLabels from "chartjs-plugin-datalabels";
import { Chart as ChartJS } from "chart.js";
import { TransportadorServico } from "../../services/TransportadorServico";
import { EmbarcadorrServico } from "../../services/EmbarcadorServico";
import { errorMessage } from "../../components/Mensagem";
import InputMask from "react-input-mask";

ChartJS.register(ChartDataLabels);

// --- COMPONENTE -------------------------------------------------------------
export default function Transportadoras() {
  //Seleções
  const [selecionada, setSelecionada] = useState(null);
  const [selectedLoja, setSelectedLoja] = useState(null);
  const [selectedTipoEntrega, setSelectedTipoEntrega] = useState(null);
  //Objetos tabelas
  const [transportadoras, setTransportadoras] = useState([]);
  const [lojas, setLojas] = useState([]);
  const [tiposEntrega, setTiposEntrega] = useState([]);
  //Load Transp
  const [loadingTransportadoras, setLoadingTransportadoras] = useState(false);
  //Paginação Transportadoras
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  //Datas Pesquisa
  const hoje = new Date();
  const quinzeDiasAtras = new Date();
  quinzeDiasAtras.setDate(hoje.getDate() - 15);
  const formatarDDMMYYYY = (date) => {
    const dia = String(date.getDate()).padStart(2, "0");
    const mes = String(date.getMonth() + 1).padStart(2, "0");
    const ano = date.getFullYear();
    return `${dia}/${mes}/${ano}`;
  };
  const [dataInicio, setDataInicio] = useState(
    formatarDDMMYYYY(quinzeDiasAtras)
  );
  const [dataFim, setDataFim] = useState(formatarDDMMYYYY(hoje));
  //Grafico
  const [faturamentoMensal, setFaturamentoMensal] = useState([]);

  //Carrega só as transportadoras uma vez no load da pagina
  useEffect(() => {
    Carregar_Transportadoras_Faturamento(dataInicio, dataFim);
  }, []);

  //Busca lojas e cabeçalhos sempre que seleciona uma transportadora
  useEffect(() => {
    (async () => {
      if (!selecionada) {
        setLojas([]);
        return;
      }

      try {
        const transportadora = transportadoras.find(
          (t) => t.razao_Social === selecionada
        );

        transportadora.dT_Inicial = formatarParaAPI(dataInicio);  
        transportadora.dT_Final = formatarParaAPI(dataFim);

        if (transportadora) {
          //Lojas
          const response = await EmbarcadorrServico.BuscarLojaFaturamento(
            transportadora
          );
          if (!response?.sucesso) {
            return errorMessage("Atenção: " + response?.erros);
          }
          setLojas(response.data);

          //Cabeçalhos/Tipos de Entrega
          const responseEntrega =
            await EmbarcadorrServico.BuscarCabecalhosFaturamento(
              transportadora
            );
          if (!responseEntrega?.sucesso) {
            return errorMessage("Atenção: " + responseEntrega?.erros);
          }
          setTiposEntrega(responseEntrega.data);

          //Carrega Dados Mensal Grafico
          const responseMensal =
            await EmbarcadorrServico.BuscaFaturamentoMensal(transportadora);
          if (!responseMensal?.sucesso) {
            return errorMessage("Atenção: " + responseMensal?.erros);
          }
          // Formata Dados
          const data = (responseMensal.data ?? [])
            .map((item) => ({
              // "2" -> "02"
              mes: String(item.mes).padStart(2, "0"),
              // "6.164.336,34" ou "6164336,34" -> 6164336.34 (Number)
              valor:
                parseFloat(
                  String(item.vR_Frete)
                    .replace(/\./g, "") // remove separador de milhar
                    .replace(",", ".") // vírgula -> ponto
                ) || 0,
            }))
            // garante que as barras fiquem em ordem de mês
            .sort((a, b) => Number(a.mes) - Number(b.mes));

          setFaturamentoMensal(data);
        }
      } catch (error) {
        console.error(error);
        errorMessage("Erro: " + error);
      }
    })();
  }, [selecionada, transportadoras]); // depende só da seleção

  //busca cabeçalhos quando seleciona loja
  useEffect(() => {
    if (!selectedLoja || !selecionada) return;

    const transportadoraSelecionada = transportadoras.find(
      (t) => t.razao_Social === selecionada
    );
    const transportadorLoja = {
      ...transportadoraSelecionada,
      cd_divisao: selectedLoja.cD_Divisao,
    };

    (async () => {
      try {
        const response = await EmbarcadorrServico.BuscarCabecalhosFaturamento(
          transportadorLoja
        );
        if (response?.sucesso) {
          setTiposEntrega(response.data);
        } else {
          setTiposEntrega([]);
          errorMessage("Erro: " + response?.erros);
        }
      } catch (err) {
        console.error(err);
        errorMessage("Erro: " + err);
      }
    })();
  }, [selectedLoja, selecionada]);

  //Função para Buscar na API Lista das transportadoras
  async function Carregar_Transportadoras_Faturamento(DT_Inicial, DT_Final) {
    try {
      setLoadingTransportadoras(true);

      DT_Inicial = formatarParaAPI(DT_Inicial);
      DT_Final = formatarParaAPI(DT_Final);
      const resposta =
        await EmbarcadorrServico.BuscarTransportadorasFaturamento({
          DT_Inicial,
          DT_Final,
        });

      if (!resposta?.sucesso) {
        return errorMessage("Atenção: " + resposta?.erros);
      }

      setTransportadoras(resposta.data);
    } catch (error) {
      console.error(error);
      errorMessage("Erro: " + error);
    } finally {
      setLoadingTransportadoras(false);
    }
  }

  function formatarParaAPI(data) {
    // espera data no formato DD/MM/YYYY
    const [dia, mes, ano] = data.split("/");
    return `${ano}-${mes}-${dia}`; // YYYY-MM-DD
  }

  const transportadorasOrdenadas = transportadoras
    .map((t) => ({
      cD_Filial: t.cD_Filial,
      nome: t.razao_Social,
      notasEmitidas: parseInt(t.qtd_NF_Emitidas) || 0,
      notasPrevistas: parseInt(t.qtd_NF_Previstas) || 0,
      frete: parseFloat(t.vR_Frete.replace(",", ".")) || 0,
      lojas: t.lojas,
    }))
    .sort((a, b) => b.notasEmitidas - a.notasEmitidas);

  //   calcula paginação
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const transportadorasPaginadas = transportadorasOrdenadas.slice(
    startIndex,
    endIndex
  );

  const totalPages = Math.ceil(transportadorasOrdenadas.length / itemsPerPage);

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages || 1);
    }
  }, [transportadorasOrdenadas, totalPages]);

  //Totais
  const totalNotasEmitidasGeral = transportadorasOrdenadas.reduce(
    (acc, t) => acc + t.notasEmitidas,
    0
  );
  const totalNotasPrevistasGeral = transportadorasOrdenadas.reduce(
    (acc, t) => acc + t.notasPrevistas,
    0
  );
  const totalFreteGeral = transportadorasOrdenadas.reduce(
    (acc, t) => acc + t.frete,
    0
  );

  const totalNotasEmitidasLojas = lojas.reduce(
    (acc, l) => acc + l.qtd_Notas,
    0
  );
  const totalFreteLojas = lojas.reduce((acc, l) => acc + (l.vR_Frete || 0), 0);

  return (
    <div className="p-4 space-y-6">
      {/* FILTROS DE PERÍODO */}
      <div className="flex space-x-4 items-center">
        <label className="text-sm font-medium">Início:</label>
        <InputMask
          mask="99/99/9999"
          value={dataInicio}
          onChange={(e) => setDataInicio(e.target.value)}
        >
          {(inputProps) => (
            <input
              {...inputProps}
              type="text"
              placeholder="DD/MM/YYYY"
              className="border px-2 py-1 rounded"
            />
          )}
        </InputMask>

        <label className="text-sm font-medium">Fim:</label>
        <InputMask
          mask="99/99/9999"
          value={dataFim}
          onChange={(e) => setDataFim(e.target.value)}
        >
          {(inputProps) => (
            <input
              {...inputProps}
              type="text"
              placeholder="DD/MM/YYYY"
              className="border px-2 py-1 rounded"
            />
          )}
        </InputMask>
        <button
          onClick={() =>
            Carregar_Transportadoras_Faturamento(dataInicio, dataFim)
          }
          className="flex items-center px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
        >
          Pesquisar
          {/* Ícone de lupa */}
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-5 w-5 mr-2"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M21 21l-4.35-4.35M11 18a7 7 0 100-14 7 7 0 000 14z"
            />
          </svg>
        </button>
      </div>

      {/* RESTANTE DO COMPONENTE (tabelas e gráficos) */}
      <div className="grid grid-cols-12 gap-4">
        {/* LEGENDA & DETALHES */}
        <div className="bg-white p-4 rounded shadow overflow-auto col-span-6">
          <h2 className="text-center text-lg font-semibold mb-2">
            Legenda &amp; Detalhes
          </h2>
          <table className="w-full text-sm">
            <thead>
              <tr>
                <th className="p-2 text-left">Transportadora</th>
                <th className="p-2 text-left">Notas</th>
                <th className="p-2 text-left">Frete</th>
                <th className="p-2 text-left">%</th>
              </tr>
            </thead>
            <tbody>
              {loadingTransportadoras ? (
                <tr>
                  <td colSpan={4} className="text-center p-4">
                    <div className="flex items-center justify-center">
                      <span className="ml-2 text-gray-600">
                        Carregando Transportadoras...{" "}
                      </span>
                      <div className="w-6 h-6 border-4 border-blue-500 border-dashed rounded-full animate-spin"></div>
                    </div>
                  </td>
                </tr>
              ) : (
                transportadorasPaginadas.map((d) => (
                  <tr
                    key={d.cD_Filial} // agora é único
                    className={`cursor-pointer hover:bg-gray-100 ${
                      selecionada === d.nome ? "bg-green-100 font-bold" : ""
                    }`}
                    onClick={() => {
                      setSelecionada(d.nome);
                      setSelectedLoja(null);
                      setSelectedTipoEntrega(null);
                    }}
                  >
                    <td className="p-2">{d.nome}</td>
                    <td className="p-2">
                      {d.notasEmitidas}/{d.notasPrevistas}
                    </td>
                    <td className="p-2">R$ {d.frete.toLocaleString()}</td>
                    <td className="p-2">
                      {(
                        (d.notasEmitidas / totalNotasEmitidasGeral) *
                        100
                      ).toFixed(1)}
                      %
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>

          {/* Botoes paginação */}
          <div className="flex justify-center mt-4 space-x-2">
            {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
              <button
                key={page}
                onClick={() => setCurrentPage(page)}
                className={`px-3 py-1 rounded ${
                  currentPage === page
                    ? "bg-blue-500 text-white"
                    : "bg-gray-200"
                }`}
              >
                {page}
              </button>
            ))}
          </div>

          <div className="mt-2 border-t pt-2 font-bold text-right">
            Total Notas: {totalNotasEmitidasGeral}/{totalNotasPrevistasGeral} |
            Total Frete: R$ {totalFreteGeral.toFixed(2)}
          </div>
        </div>

        {/* FRETE POR LOJA */}
        <div className="bg-white p-4 rounded shadow overflow-auto col-span-4">
          <h2 className="text-center font-semibold mb-2">Frete por Loja</h2>
          {!selecionada ? (
            <p className="text-center text-gray-500">
              Selecione uma transportadora à esquerda.
            </p>
          ) : (
            <>
              <table className="w-full text-sm">
                <thead>
                  <tr>
                    <th className="p-2 text-left">CD Loja</th>
                    <th className="p-2 text-left">Nome</th>
                    <th className="p-2 text-left">Qtd Notas</th>
                    <th className="p-2 text-left">Valor Frete</th>
                  </tr>
                </thead>
                <tbody>
                  {lojas.map((l) => (
                    <tr
                      key={l.cD_Divisao}
                      className={`hover:bg-gray-100 cursor-pointer ${
                        selectedLoja === l.cD_Divisao
                          ? "bg-yellow-100 font-bold"
                          : ""
                      }`}
                      onClick={() => {
                        setSelectedLoja(l);
                        setSelectedTipoEntrega(null);
                      }}
                    >
                      <td className="p-2">{l.cD_Divisao}</td>
                      <td className="p-2">{l.nome_Divisao}</td>
                      <td className="p-2">{l.qtd_Notas}</td>
                      <td className="p-2">
                        R${" "}
                        {(l.vR_Frete || 0).toLocaleString("pt-BR", {
                          minimumFractionDigits: 2,
                        })}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-2 border-t pt-2 font-bold text-right">
                Total Notas: {totalNotasEmitidasLojas} | Total Frete: R${" "}
                {totalFreteLojas.toFixed(2)}
              </div>
            </>
          )}
        </div>

        {/* FRETE POR TIPO ENTREGA */}
        <div className="bg-white p-4 rounded shadow overflow-auto col-span-2">
          <h2 className="text-center font-semibold mb-2">
            Frete por Tipo Entrega
          </h2>
          {!selecionada ? (
            <p className="text-center text-gray-500">
              Selecione uma transportadora à esquerda.
            </p>
          ) : (
            <>
              <table className="w-full text-sm">
                <thead>
                  <tr>
                    <th className="p-2 text-center">Cab</th>
                    <th className="p-2 text-center">Qtd Notas</th>
                  </tr>
                </thead>
                <tbody>
                  {tiposEntrega
                    .sort((a, b) => b.qtdNotas - a.qtdNotas)
                    .map((t) => (
                      <tr
                        key={t.tP_Entrega}
                        className={`hover:bg-gray-100 cursor-pointer ${
                          selectedTipoEntrega === t.tP_Entrega
                            ? "bg-blue-100 font-bold"
                            : ""
                        }`}
                        onClick={() => setSelectedTipoEntrega(t.tP_Entrega)}
                      >
                        <td className="p-2 text-center">{t.tP_Entrega}</td>
                        <td className="p-2 text-center">{t.qtd_Notas}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
              <div className="mt-2 border-t pt-2 font-bold text-right">
                Total de Notas:{" "}
                {tiposEntrega.reduce((acc, t) => acc + t.qtd_Notas, 0)}
              </div>
            </>
          )}
        </div>
      </div>

      {/* GRÁFICO DE FATURAMENTO */}
      {selecionada && (
        <div className="bg-white p-4 rounded shadow h-[400px]">
          <h2 className="text-center font-semibold mb-4">
            Faturamento Mensal - {selecionada}
          </h2>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={faturamentoMensal}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis
                dataKey="mes"
                label={{ value: "Mês", position: "insideBottom", offset: -5 }}
              />
              <YAxis
                tickFormatter={(v) => Number(v).toLocaleString("pt-BR")}
                label={{ value: "R$", angle: -90, position: "insideLeft" }}
              />
              <Tooltip
                formatter={(value) =>
                  `R$ ${Number(value).toLocaleString("pt-BR", {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2,
                  })}`
                }
              />
              <Bar dataKey="valor" fill="#28a745" name="Faturamento" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}
