import React from "react";
import { useState, useEffect } from "react";
import { Config } from "../config";
import { Utilidades } from "../index";

export default function IndexURI() {
    return {
        // transportador
        login_uri: "/api/token",
        pre_cadastro_transportador: `/api/transportador/cadastrar-spot`,
        consultar_email_recuperacao: "/api/token/consultar-email-recuperacao",
        recuperar_senha: "/api/token/enviar-email",
        redefinir_senha: "/api/token/resetar-senha",
        decodificar_hash: "/api/token/decodificar-hash",

        importar_cte: "/api/conhecimento/validar-frete",
        aprovar_transportador_lista: "/api/transportador/aprovar-spot",
        reprovar_transportador_lista: "/api/transportador/reprovar-spot",
        editar_transportador: "/api/transportador/editar",
        buscar_transportador_pendente_aprovacao:
            "/api/transportador/buscar-transportadores-pendentes",
        buscar_faturas: ({ cnpj }) =>
            `/api/transportador/buscar-fatura?_cgc_cpf=${cnpj}`,
        buscar_conhecimento_fatura: ({ filtros }) =>
            `/api/transportador/buscar-conhecimento-fatura?CNPJ=${filtros.CNPJ}&NR_Fatura=${filtros.NR_Fatura}`,
        buscar_transportador_por_cnpj: ({ cnpj }) =>
            `/api/transportador/buscar-dados-transportador?cnpj=${cnpj}`,
        buscar_classes_veiculo: "/api/transportador/buscar-classes-veiculo",
        atualizar_transportador: "/api/transportador/atualizar-transportador",
        atualizar_coleta: "/api/loja/editar-frete-coleta",
        cadastrar_carreteiro: "/api/loja/cadastrar-carreteiro",
        gerar_OS: "/api/carreteiro/gerar-os",
        buscar_coleta: "/api/loja/buscar-coletas",
        buscar_transportadoras_faturamento:
            "/api/transportador/buscar-transportadoras-faturamento",
        buscar_despesas_regiao_detalhes: "/api/transportador/buscar-despesas-frete-detalhes",
        baixar_fatura_pdf: ({ cgcFilial, numeroFatura }) =>
            `/api/report/fatura/${cgcFilial}/${numeroFatura}`,

        // loja
        gerar_faturamento: "/api/loja/incluir-nf-servico",
        cadastrar_carreteiro: "/api/loja/cadastrar-carreteiro",
        listar_carreteiros: "/api/loja/listar-carreteiros",
        cadastrar_coleta: "/api/loja/coleta",
        buscar_coleta: "/api/loja/buscar-coletas",
        buscar_notas: ({ filtro }) =>
            `/api/loja/buscar-notas?filtro=${encodeURIComponent(filtro)}`,
        buscar_cliente: ({ filtro }) =>
            `/api/loja/buscar-cliente?filtro=${encodeURIComponent(filtro)}`,
        buscar_lojas: ({ filtro }) =>
            `/api/loja/buscar-loja?cnpj=${filtro.CNPJ}&status=${filtro.Status}`,
        cadastrar_loja: "/api/loja/cadastrar-loja",
        atualizar_loja: "/api/loja/atualizar-loja",
        calcular_frete_coleta: "/api/loja/calcular-frete-coleta",
        baixar_coleta_pdf: (nr_coleta, cd_filial, cd_empresa) =>
            `/api/report/coleta/${nr_coleta}/${cd_filial}/${cd_empresa}`,
        // embarcador
        buscar_aprovacoes_pendentes: "/api/embarcador/buscar-aprovacoes-pendentes",
        aprovar_coleta: "/api/embarcador/aprovar-coleta",
        reprovar_coleta: "/api/embarcador/reprovar-coleta",
        aprovar_loja: "/api/embarcador/aprovar-loja",
        reprovar_loja: "/api/embarcador/reprovar-loja",
        buscar_transportadoras_faturamento: "/api/embarcador/buscar-transportadoras-faturamento",
        buscar_loja_faturamento: "/api/embarcador/buscar-loja-faturamento",
        buscar_cabecalhos_faturamento: "/api/embarcador/buscar-cabecalhos-faturamento",
        buscar_faturamento_mensal: "/api/embarcador/buscar-faturamento-mensal",
        buscar_despesas_fretes: "/api/transportador/buscar-despesas-frete",
        buscar_despesas_fretes_regiao: "/api/transportador/buscar-despesas-frete-regiao",
        buscar_despesas_fretes_todas_lojas: "/api/transportador/buscar-despesas-frete-todas-lojas",
        buscar_posicao_entrega: ({ filtros }) => `/api/embarcador/buscar-posicao-entrega?data_inicial=${filtros.dataInicio}&data_final=${filtros.dataFim}`,
        buscar_posicao_entrega_notas: ({ filtros }) => `/api/embarcador/buscar-posicao-entrega-notas?nr_manifesto=${filtros.nr_manifesto}&cd_empresa=${filtros.cd_empresa}&cd_filial=${filtros.cd_filial}`
    };
}