import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom'; // Certifique-se de que o react-router-dom está instalado
import { EmbarcadorrServico } from '../../services/EmbarcadorServico';
import { errorMessage } from '../../components/Mensagem';
import { FaTruck, FaStore, FaClipboardList } from 'react-icons/fa';

export default function AprovacoesPendentes() {
    const [aprovacoesPendentes, setAprovacoesPendentes] = useState(null);
    const [aguardandoCarregamento, setAguardandoCarregamento] = useState(true);

    async function fetchAprovacoes() {
        try {
            const resultado = await EmbarcadorrServico.BuscarAprovacoesPendentes();
            if (resultado.sucesso) {
                setAprovacoesPendentes(resultado.data);
            } else {
                errorMessage('Erro', 'Erro ao buscar pelas aprovações pendentes');
            }
        } catch (error) {
            errorMessage('Erro', 'Erro ao buscar pelas aprovações pendentes');
        } finally {
            setAguardandoCarregamento(false);
        }
    }

    useEffect(() => {
        fetchAprovacoes();
    }, []);

    return (
        <div className="p-6">
            <h1 className="text-2xl font-bold mb-6 text-center">Aprovações Pendentes</h1>
            {aguardandoCarregamento ? (
                <div className="text-center text-gray-600">Carregando aprovações pendentes...</div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Transportadoras */}
                    <Link to="/aprovacao" className="bg-white shadow-md rounded-lg p-6 flex items-center hover:shadow-lg transition-shadow">
                        <div className="bg-blue-100 text-blue-600 p-4 rounded-full">
                            <FaTruck size={32} />
                        </div>
                        <div className="ml-4">
                            <h2 className="text-lg font-semibold text-gray-700">Transportadoras</h2>
                            <p className="text-gray-500">
                                Pendentes: {aprovacoesPendentes?.qtd_Transportadoras || 0}
                            </p>
                        </div>
                    </Link>

                    {/* Lojas */}
                    <Link to="/aprovacao-lojas" className="bg-white shadow-md rounded-lg p-6 flex items-center hover:shadow-lg transition-shadow">
                        <div className="bg-green-100 text-green-600 p-4 rounded-full">
                            <FaStore size={32} />
                        </div>
                        <div className="ml-4">
                            <h2 className="text-lg font-semibold text-gray-700">Lojas</h2>
                            <p className="text-gray-500">
                                Pendentes: {aprovacoesPendentes?.qtd_Lojas || 0}
                            </p>
                        </div>
                    </Link>

                    {/* Coletas */}
                    <Link to="/lista-coletas-embarcador" className="bg-white shadow-md rounded-lg p-6 flex items-center hover:shadow-lg transition-shadow">
                        <div className="bg-yellow-100 text-yellow-600 p-4 rounded-full">
                            <FaClipboardList size={32} />
                        </div>
                        <div className="ml-4">
                            <h2 className="text-lg font-semibold text-gray-700">Coletas</h2>
                            <p className="text-gray-500">
                                Pendentes: {aprovacoesPendentes?.qtd_Coletas || 0}
                            </p>
                        </div>
                    </Link>
                </div>
            )}
        </div>
    );
}