import React, { useEffect, useState, useRef } from "react";
import { FaStore } from "react-icons/fa";
import { FiUser, FiMapPin, FiPhone, FiMail, FiFileText, FiEdit, FiSave, FiX, FiKey } from "react-icons/fi";
import { LojaServico } from "../../services/LojaServico";
import { EnderecoServico } from "../../services/EnderecoServico"; // Importa o serviço ViaCEP
import { errorMessage, successMessage } from "../../components/Mensagem";

function formatDate(dateStr) {
  if (!dateStr || dateStr.startsWith("0001-01-01")) return "";
  const d = new Date(dateStr);
  if (isNaN(d)) return "";
  return d.toLocaleDateString("pt-BR") + " " + d.toLocaleTimeString("pt-BR").slice(0, 5);
}

export default function DadosLoja({ user }) {
  const [dadosLoja, setDadosLoja] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editMode, setEditMode] = useState(false);
  const [form, setForm] = useState({});
  const [cepBuscaLoading, setCepBuscaLoading] = useState(false);
  const [cepBuscaErro, setCepBuscaErro] = useState('');
  const numeroRef = useRef(null);

  const fetchDataLoja = async () => {
    setLoading(true);
    const resposta = await LojaServico.BuscarDadosLoja(user?.cnpj || user?.CNPJ);
    if (resposta?.sucesso && resposta?.data && resposta.data.length > 0) {
      setDadosLoja(resposta.data[0]);
      setForm(resposta.data[0]);
    } else {
      setDadosLoja(null);
      setForm({});
    }
    setLoading(false);
  };

  useEffect(() => {
    if (user?.cnpj || user?.CNPJ) {
      fetchDataLoja();
    }
    // eslint-disable-next-line
  }, [user]);

  const handleEdit = () => setEditMode(true);
  const handleCancel = () => {
    setEditMode(false);
    setForm(dadosLoja);
  };
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    let newValue = value;
    if (name === "cep") {
      newValue = value.replace(/[^\d]/g, '');
    }
    // Atualiza tanto dadosLoja quanto form
    setDadosLoja((prev) => ({
      ...prev,
      [name]: newValue,
    }));
    setForm((prev) => ({
      ...prev,
      [name]: newValue,
    }));
  };

  const handleCepKeyDown = async (e) => {
    if (e.key === 'Enter') {
      setCepBuscaLoading(true);
      setCepBuscaErro('');
      const endereco = await EnderecoServico.buscarEnderecoPorCep(form.cep);
      setCepBuscaLoading(false);
      if (endereco) {
        setForm(prev => ({
          ...prev,
          endereco: endereco.endereco,
          bairro: endereco.bairro,
          cidade: endereco.cidade,
          uf: endereco.uf
        }));
        setTimeout(() => {
          if (numeroRef.current) numeroRef.current.focus();
        }, 100);
      } else {
        setCepBuscaErro('CEP não encontrado ou inválido.');
      }
    }
  };

  // Campos sensíveis que devem ficar sempre desabilitados
  const camposSensiveis = [
    "id_Loja",
    "cnpj",
    "razao_Social",
    "senha",
    "ie"
  ];

  const handleSave = async () => {
    if (
      !form.cep ||
      !form.endereco ||
      !form.numero ||
      !form.bairro ||
      !form.cidade ||
      !form.uf
    ) {
      errorMessage('Preencha todos os campos de endereço antes de salvar.');
      return;
    }

    try {
      const resposta = await LojaServico.EditarLoja(form);
      if (resposta?.sucesso) {
        successMessage('Dados da loja atualizados com sucesso!');
        fetchDataLoja();
        setEditMode(false);
      } else {
        errorMessage(resposta?.mensagem || 'Erro ao salvar dados da loja');
      }
    } catch (error) {
      errorMessage('Erro ao conectar com o servidor: ' + error);
    }
  };

  if (loading) {
    return <div className="text-center py-8 text-green-600 font-semibold">Carregando dados da loja...</div>;
  }

  if (!dadosLoja) {
    return <div className="text-center py-8 text-red-600 font-semibold">Dados da loja não encontrados.</div>;
  }

  return (
    <main className="flex-1 p-6 bg-gray-100 min-h-screen">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <div className="flex justify-between items-center">
            <div className="flex items-center">
              <FaStore className="text-green-600 text-3xl mr-4" />
              <div>
                <h1 className="text-2xl font-bold text-gray-800">Dados da Loja</h1>
                <p className="text-gray-600">Informações cadastrais e contato</p>
              </div>
            </div>
            <div className="flex space-x-2">
              {!editMode ? (
                <button
                  onClick={() => setEditMode(true)}
                  className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 flex items-center"
                >
                  <FiEdit className="mr-2" />
                  Editar
                </button>
              ) : (
                <div className="flex space-x-2">
                  <button
                    onClick={handleSave}
                    className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 flex items-center"
                  >
                    <FiSave className="mr-2" />
                    Salvar
                  </button>
                  <button
                    onClick={handleCancel}
                    className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-700 flex items-center"
                  >
                    <FiX className="mr-2" />
                    Cancelar
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Dados da Loja */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiFileText className="mr-2 text-green-600" />
            Dados Cadastrais
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Id Loja</label>
              <input type="text" name="id_Loja" value={dadosLoja.id_Loja} onChange={handleInputChange} disabled={true} className={`w-full p-3 border rounded-lg border-gray-200 bg-gray-50`} />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">CNPJ</label>
              <input type="text" name="cnpj" value={dadosLoja.cnpj} onChange={handleInputChange} disabled={true} className={`w-full p-3 border rounded-lg border-gray-200 bg-gray-50`} />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Razão Social</label>
              <input type="text" name="razao_Social" value={dadosLoja.razao_Social} onChange={handleInputChange} disabled={true} className={`w-full p-3 border rounded-lg border-gray-200 bg-gray-50`} />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Nome Fantasia</label>
              <input
                type="text"
                name="nome_Fantasia"
                value={form.nome_Fantasia || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Número Loja</label>
              <input
                type="text"
                name="numero_Loja"
                value={dadosLoja.numero_Loja}
                onChange={handleInputChange}
                disabled={true} // Sempre congelado, não editável
                className={`w-full p-3 border rounded-lg border-gray-200 bg-gray-50`}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">IE</label>
              <input type="text" name="ie" value={dadosLoja.ie || ''} onChange={handleInputChange} disabled={true} className={`w-full p-3 border rounded-lg border-gray-200 bg-gray-50`} />
            </div>
          </div>
        </div>

        {/* Endereço */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiMapPin className="mr-2 text-green-600" />
            Endereço
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">CEP</label>
              <input
                type="text"
                name="cep"
                value={form.cep || ''}
                onChange={handleInputChange}
                onKeyDown={handleCepKeyDown}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
                placeholder="Digite o CEP e pressione Enter"
              />
              {cepBuscaLoading && <span className="text-blue-600 text-sm">Buscando endereço...</span>}
              {cepBuscaErro && <span className="text-red-600 text-sm">{cepBuscaErro}</span>}
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Endereço</label>
              <input
                type="text"
                name="endereco"
                value={form.endereco || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Número</label>
              <input
                ref={numeroRef}
                type="text"
                name="numero"
                value={form.numero || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Bairro</label>
              <input
                type="text"
                name="bairro"
                value={form.bairro || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Cidade</label>
              <input
                type="text"
                name="cidade"
                value={form.cidade || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">UF</label>
              <input
                type="text"
                name="uf"
                value={form.uf || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
          </div>
        </div>

        {/* Contato */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiUser className="mr-2 text-green-600" />
            Contato
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1"><FiPhone className="inline mr-1" />Telefone</label>
              <input 
              disabled
              type="text" name="telefone" value={dadosLoja.telefone || ''} onChange={handleInputChange} 
              //disabled={!editMode}
              className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`} />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1"><FiMail className="inline mr-1" />Email</label>
              <input
                type="email"
                name="email"
                value={form.email || ''}
                onChange={handleInputChange}
                disabled={!editMode}
                className={`w-full p-3 border rounded-lg ${editMode ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>
          </div>
        </div>

        {/* Status e histórico */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiFileText className="mr-2 text-green-600" />
            Status e Histórico
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status Aprovação</label>
              <input type="text" name="status_Aprovacao" value={dadosLoja.status_Aprovacao} onChange={handleInputChange} disabled className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data Cadastro</label>
              <input type="text" name="data_Cadastro" value={formatDate(dadosLoja.data_Cadastro)} onChange={handleInputChange} disabled className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data Aprovação</label>
              <input type="text" name="data_Aprovacao" value={formatDate(dadosLoja.data_Aprovacao)} onChange={handleInputChange} disabled className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Usuário Aprovador</label>
              <input type="text" name="usuario_Aprovador" value={dadosLoja.usuario_Aprovador || ''} onChange={handleInputChange} disabled className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50" />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Motivo Rejeição</label>
              <input type="text" name="motivo_Rejeicao" value={dadosLoja.motivo_Rejeicao || ''} onChange={handleInputChange} disabled className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50" />
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
