import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import logo from '../assets/logo.png';
import { errorMessage, confirmMessage, successMessage, infoMessage } from '../components/Mensagem';
import { Usuario } from '../models/Usuario';
import { UsuarioServico } from '../services/UsuarioServico';
import { TransportadorServico } from '../services/TransportadorServico';
import { LojaServico } from '../services/LojaServico';
import { SeVazioUndefinedOuNulo, ValidarCNPJ, ValidarEmail, ValidarPreSenha } from '../utilities/Utilidades';
import EnableLoading from '../components/Loading';
import packageJson from '../../package.json';


export default function Login({ onLogin }) {
  const [confirmarSenhaLoja, setConfirmarSenhaLoja] = useState("");
  const [showConfirmPasswordLoja, setShowConfirmPasswordLoja] = useState(false);
  const [nomeFantasiaLoja, setNomeFantasiaLoja] = useState("");
  const [ieLoja, setIeLoja] = useState("");
  const [cepLoja, setCepLoja] = useState("");
  const [enderecoLoja, setEnderecoLoja] = useState("");
  const [numeroEnderecoLoja, setNumeroEnderecoLoja] = useState("");
  const [bairroLoja, setBairroLoja] = useState("");
  const [cidadeLoja, setCidadeLoja] = useState("");
  const [ufLoja, setUfLoja] = useState("");
  const [telefoneLoja, setTelefoneLoja] = useState("");
  const [emailLoja, setEmailLoja] = useState("");
  const [TipoUsuario, setTipoUsuario] = useState('embarcador');
  const [Login, setLogin] = useState('');
  const [Senha, setSenha] = useState('');
  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [showCadastroLoja, setShowCadastroLoja] = useState(false);

  const [email, setEmail] = useState('');
  const [cnpj, setCnpj] = useState('');
  const [preSenha, setPreSenha] = useState('');
  const [confirmarSenha, setConfirmarSenha] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [empresaNome, setEmpresaNome] = useState('');
  const [empresaEndereco, setEmpresaEndereco] = useState('');
  const [buscando, setBuscando] = useState(false);
  const [buscaErro, setBuscaErro] = useState('');
  const [cadastroConfirmado, setCadastroConfirmado] = useState(false);
  const [cnpjLoja, setCnpjLoja] = useState('');
  const [numeroLoja, setNumeroLoja] = useState('');
  const [senhaLoja, setSenhaLoja] = useState('');
  const [nomeLoja, setNomeLoja] = useState('');

  const navigate = useNavigate();

  // const dbConfig = {
  //   env: packageJson.config.Enviroment || 'HOM'
  // }

  console.log('Esta é a origem ' + window.location.href);

  const validarConfirmacaoSenha = () => {
    if (preSenha !== confirmarSenha) {
      errorMessage('As senhas não coincidem. Verifique e tente novamente.');
      return false;
    }
    return true;
  };

  const isButtonDisabled = () => {
    return buscando || !email || !cnpj || !preSenha || !confirmarSenha || (preSenha !== confirmarSenha);
  };

  const senhasNaoConferem = () => {
    return confirmarSenha && preSenha && preSenha !== confirmarSenha;
  };

  const limparCNPJ = (cnpj) => {
    return cnpj.replace(/[^\d]/g, '');
  };

  const buscarDadosEmpresa = async () => {
    setBuscaErro('');
    setBuscando(true);
    setEmpresaNome('');
    setEmpresaEndereco('');

    const cnpjLimpo = limparCNPJ(cnpj);

    var cnpjValido = ValidarCNPJ(cnpjLimpo);
    var emailValido = ValidarEmail(email);
    var preSenhaValida = ValidarPreSenha(preSenha);
    var senhasIguais = validarConfirmacaoSenha();

    if (!cnpjValido || !emailValido || !preSenhaValida || !senhasIguais) {
      setBuscando(false);

      if (!senhasIguais) {
        return; // Error message already shown in validarConfirmacaoSenha
      }

      if (!preSenhaValida) {
        return errorMessage('Senha inválida, certifique-se de que a senha contém ao menos 8 caracteres, letras e números');
      }

      return errorMessage('CNPJ ou Email inválidos');
    }

    try {
      const precadastro = {
        CNPJ: cnpjLimpo, // Use cleaned CNPJ without special characters
        Email: email,
        Senha: preSenha,
        ambiente: window.location.href
      }

      TransportadorServico.PreCadastroTransportador({ precadastro: precadastro })
        .then((resposta) => {
          if (resposta?.sucesso) {
            successMessage('Transportador cadastrado com sucesso, aguarde a aprovação do cadastro.');

          } else {
            console.log(resposta);
            errorMessage('Erro no pré-cadastro do transportador. ' + resposta?.erros);
          }
        })
        .catch((error) => {
          errorMessage(error);
          console.log(error);
        })
        .finally(() => {
          setBuscando(false);
        });

    } catch (error) {
      setBuscaErro(error.message || 'Erro ao buscar dados da empresa.');
      console.log(error);
      errorMessage(error.message || 'Erro ao buscar dados da empresa.');
    } finally {
      setBuscando(false);
    }
  };

  const handleCadastrar = () => {
    setCadastroConfirmado(true);
  };

  const normalizeLogin = (login) => {
    if (!login) return "";

    const onlyNumbers = login.replace(/\D/g, "");

    if (onlyNumbers.length === 14) {
      return onlyNumbers; // devolve só números
    }

    return login;
  };

  const handleSubmit = (e) => {

    e.preventDefault();
    if (!Login || !Senha) {
      return errorMessage('Preencha todos os campos');
    }

    const usuario = {
      Login: normalizeLogin(Login),
      Senha: Senha,
      TipoUsuario: TipoUsuario
    }

    try {
      UsuarioServico.Login(usuario)
        .then((resposta) => {
          if (!resposta?.sucesso || SeVazioUndefinedOuNulo(resposta?.data?.token)) {
            return infoMessage('Atenção: ' + resposta?.erros);
            //return errorMessage('Atenção: ' + resposta?.erros);
          } else {
            prosseguirLogin(resposta.data);
          }
        })
        .catch((error) => {
          console.log(error);
          errorMessage(error);
        })
        .finally(() => {
        });
    } catch (error) {
      errorMessage('Erro ' + error);
    }
  };

  function prosseguirLogin(usuario) {
    onLogin(usuario);

    if (TipoUsuario === 'embarcador') {
      navigate('/lojas');
    } else if (TipoUsuario === 'transportador') {
      navigate('/transportador');
    } else if (TipoUsuario === 'loja') {
      navigate('loja/carreteiros');
    }
  }

  async function handleCadastroLoja(e) {
    e.preventDefault();

    const cnpjLimpo = cnpjLoja.replace(/[^\d]/g, '');

    if (cnpjLimpo.length !== 14) {
      errorMessage('CNPJ inválido. Digite um CNPJ válido.');
      return;
    }
    if (!emailLoja || !senhaLoja || !numeroLoja) {
      errorMessage('Preencha todos os campos obrigatórios.');
      return;
    }
    if (senhaLoja !== confirmarSenhaLoja) {
      errorMessage('As senhas não conferem.');
      return;
    }

    const dados = {
      cnpj: cnpjLimpo,
      email: emailLoja,
      senha: senhaLoja,
      numero_Loja: numeroLoja,
      ambiente: window.location.href
    };

    try {
      const resposta = await LojaServico.CadastrarLoja(dados);
      if (resposta?.sucesso || resposta === "Loja cadastrado com sucesso.") {
        successMessage('Loja cadastrada com sucesso. Aguarde a aprovação!');
        setShowCadastroLoja(false);
        setCnpjLoja('');
        setEmailLoja('');
        setSenhaLoja('');
        setConfirmarSenhaLoja('');
        setNumeroLoja('');
      } else {
        errorMessage('Erro ao cadastrar loja: ' + (resposta?.erros || resposta));
      }
    } catch (error) {
      errorMessage('Erro ao cadastrar loja: ' + (error?.message || error));
    }
  }

  return (
    <>
      <EnableLoading />
      <div className="flex items-center justify-center min-h-screen bg-gradient-to-r from-green-400 to-blue-500">
        <div className="bg-white p-10 rounded-lg shadow-lg max-w-md w-full">
          <div className="mb-6 text-center">
            <img src={logo} alt="Leo Madeiras" className="mx-auto mb-4 w-32" />
            <h1 className="text-2xl font-bold">Login Leo Madeiras</h1>
          </div>
          <form onSubmit={handleSubmit} className="space-y-4">
            <select
              className="w-full border rounded px-3 py-2"
              value={TipoUsuario}
              onChange={(e) => setTipoUsuario(e.target.value)}
            >
              <option value="embarcador">Embarcador</option>
              <option value="transportador">Transportador</option>
              <option value="loja">Loja</option> {/* NOVA OPÇÃO */}
            </select>

            <input
              type="text"
              placeholder="Usuário"
              className="w-full border rounded px-3 py-2"
              value={Login}
              onChange={(e) => setLogin(e.target.value)}
            />

            <div className="relative">
              <input
                type={showLoginPassword ? "text" : "password"}
                placeholder="Senha"
                className="w-full border rounded px-3 py-2 pr-10"
                value={Senha}
                onChange={(e) => setSenha(e.target.value)}
              />
              <button
                type="button"
                onClick={() => setShowLoginPassword(!showLoginPassword)}
                className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                tabIndex={-1}
              >
                {showLoginPassword ? (
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.878 9.878L6.5 6.5m3.378 3.378a3 3 0 004.243-4.242M6.5 6.5L4 4m15.071 15.071L4.929 4.929" />
                  </svg>
                ) : (
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                  </svg>
                )}
              </button>
            </div>

            <button
              type="submit"
              className="w-full bg-green-500 text-white py-2 rounded hover:bg-green-600 transition"
              onClick={handleSubmit}
            >
              Entrar
            </button>
          </form>
          <div className="mt-4 text-center">
            {
              TipoUsuario === 'transportador' && (
                <button
                  onClick={() => setShowModal(true)}
                  className="text-sm text-blue-700 underline hover:text-blue-900"
                  type="button"
                >
                  Seja um Parceiro Leo Cadastre-se Aqui
                </button>
              )
            }
            {
              <div className="mt-3 text-center">
                <button
                  onClick={() => navigate('/esqueci-minha-senha')}
                  className="text-sm text-blue-700 underline hover:text-blue-900"
                  type="button"
                >
                  Esqueci minha senha
                </button>
              </div>
            }
            {
              TipoUsuario === 'loja' && (
                <button
                  onClick={() => setShowCadastroLoja(true)}
                  className="text-sm text-blue-700 underline hover:text-blue-900"
                  type="button"
                >
                  Cadastrar Loja Leo
                </button>
              )
            }
          </div>
        </div>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-lg max-w-md w-full p-6 relative">
            <button
              onClick={() => {
                setShowModal(false);
                setCadastroConfirmado(false);
                setBuscaErro('');
                setEmpresaNome('');
                setEmpresaEndereco('');
                setEmail('');
                setCnpj('');
                setPreSenha('');
                setConfirmarSenha('');
              }}
              className="absolute top-2 right-2 text-gray-500 hover:text-gray-800 text-xl font-bold"
              aria-label="Fechar"
              type="button"
            >
              &times;
            </button>

            {!cadastroConfirmado ? (
              <>
                <h2 className="text-xl font-bold mb-4 text-center">Cadastro Parceiro Leo</h2>

                <div className="space-y-4">
                  <div>
                    <label className="block mb-1 font-semibold" htmlFor="email">
                      Email
                    </label>
                    <input
                      id="email"
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="w-full border rounded px-3 py-2"
                      placeholder="seu@email.com"
                    />
                  </div>

                  <div>
                    <label className="block mb-1 font-semibold" htmlFor="cnpj">
                      CNPJ
                    </label>
                    <input
                      id="cnpj"
                      type="text"
                      value={cnpj}
                      onChange={(e) => setCnpj(e.target.value)}
                      className="w-full border rounded px-3 py-2"
                      placeholder="00.000.000/0001-00"
                    />
                  </div>

                  <div>
                    <label className="block mb-1 font-semibold" htmlFor="preSenha">
                      Senha
                    </label>
                    <div className="relative">
                      <input
                        id="preSenha"
                        type={showPassword ? "text" : "password"}
                        value={preSenha}
                        onChange={(e) => setPreSenha(e.target.value)}
                        className="w-full border rounded px-3 py-2 pr-10"
                      />
                      <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                      >
                        {showPassword ? "Ocultar" : "Mostrar"}
                      </button>
                    </div>
                  </div>

                  <div>
                    <label className="block mb-1 font-semibold" htmlFor="preSenhaConfirmar">
                      Confirmar senha
                    </label>
                    <div className="relative">
                      <input
                        id="confirmarSenha"
                        type={showConfirmPassword ? "text" : "password"}
                        value={confirmarSenha}
                        onChange={(e) => setConfirmarSenha(e.target.value)}
                        className="w-full border rounded px-3 py-2 pr-10"
                      />
                      <button
                        type="button"
                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                        className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                      >
                        {showConfirmPassword ? "Ocultar" : "Mostrar"}
                      </button>
                    </div>
                    {senhasNaoConferem() && (
                      <p className="text-red-500 text-sm mt-1">As senhas não conferem</p>
                    )}
                  </div>

                  <button
                    onClick={buscarDadosEmpresa}
                    disabled={isButtonDisabled()}
                    className={`w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition ${isButtonDisabled() && 'opacity-50 cursor-not-allowed'
                      }`}
                    type="button"
                  >
                    {buscando ? 'Buscando...' : 'Buscar Dados Empresa'}
                  </button>

                  {buscaErro && (
                    <p className="text-red-600 mt-2 text-center font-semibold">{buscaErro}</p>
                  )}

                  {empresaNome && (
                    <div className="mt-4 p-3 border rounded bg-green-50">
                      <p><strong>Nome:</strong> {empresaNome}</p>
                      <p><strong>Endereço:</strong> {empresaEndereco}</p>
                    </div>
                  )}

                  {empresaNome && (
                    <button
                      onClick={handleCadastrar}
                      className="w-full bg-green-500 text-white py-2 rounded hover:bg-green-600 transition mt-4"
                      type="button"
                    >
                      Cadastrar
                    </button>
                  )}
                </div>
              </>
            ) : (
              <div className="text-center p-4">
                <h2 className="text-xl font-bold mb-4">Cadastro Confirmado!</h2>
                <p className="mb-2">Enviado por email. Aguarde a liberação ou entre em contato com a Léo Madeiras.</p>
                <button
                  onClick={() => setShowModal(false)}
                  className="mt-4 bg-green-500 text-white py-2 px-6 rounded hover:bg-green-600 transition"
                  type="button"
                >
                  Fechar
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Modal for Loja registration */}
      {showCadastroLoja && (
        <div className="fixed inset-0 bg-black bg-opacity-30 flex items-center justify-center z-50">
          {/* <div className="bg-white p-6 rounded shadow-lg w-full" style={{ maxWidth: '720px' }}> */}
          <div className="bg-white p-6 rounded shadow-md" >

            <h2 className="text-xl font-bold mb-4 text-center">Cadastro de Loja Leo</h2>
            <form onSubmit={handleCadastroLoja}>
              <div className="grid grid-cols-2 gap-4">
                {/* <div>
                  <label className="block mb-1 font-semibold">Razão Social</label>
                  <input type="text" value={nomeLoja} onChange={e => setNomeLoja(e.target.value)} className="w-full border rounded px-2 py-1" required />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Nome Fantasia</label>
                  <input type="text" value={nomeFantasiaLoja || ''} onChange={e => setNomeFantasiaLoja(e.target.value)} className="w-full border rounded px-2 py-1" required />
                </div> */}
                <div>
                  <label className="block mb-1 font-semibold">Número Loja</label>
                  <input type="text" value={numeroLoja} onChange={e => setNumeroLoja(e.target.value)} className="w-full border rounded px-2 py-1" required />
                </div>
                {/* <div>
                  <label className="block mb-1 font-semibold">IE</label>
                  <input type="text" value={ieLoja || ''} onChange={e => setIeLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div> */}
                {/* <div>
                  <label className="block mb-1 font-semibold">CEP</label>
                  <input type="text" value={cepLoja || ''} onChange={e => setCepLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Endereço</label>
                  <input type="text" value={enderecoLoja || ''} onChange={e => setEnderecoLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div> */}
                {/* <div>
                  <label className="block mb-1 font-semibold">Número</label>
                  <input type="text" value={numeroEnderecoLoja || ''} onChange={e => setNumeroEnderecoLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Bairro</label>
                  <input type="text" value={bairroLoja || ''} onChange={e => setBairroLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Cidade</label>
                  <input type="text" value={cidadeLoja || ''} onChange={e => setCidadeLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">UF</label>
                  <input type="text" value={ufLoja || ''} onChange={e => setUfLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Telefone</label>
                  <input type="text" value={telefoneLoja || ''} onChange={e => setTelefoneLoja(e.target.value)} className="w-full border rounded px-2 py-1" />
                </div> */}
                <div>
                  <label className="block mb-1 font-semibold">Email</label>
                  <input type="email" value={emailLoja || ''} onChange={e => setEmailLoja(e.target.value)} className="w-full border rounded px-2 py-1" required />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">CNPJ</label>
                  <input type="text" value={cnpjLoja} onChange={e => setCnpjLoja(e.target.value)} className="w-full border rounded px-2 py-1" required />
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Senha</label>
                  <div className="relative">
                    <input
                      type={showPassword ? "text" : "password"}
                      value={senhaLoja}
                      onChange={e => setSenhaLoja(e.target.value)}
                      className="w-full border rounded px-2 py-1 pr-20"
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute inset-y-0 right-0 flex items-center px-3 text-sm text-blue-600 hover:text-blue-800"
                      tabIndex={-1}
                      style={{ height: '100%' }}
                    >
                      {showPassword ? "Ocultar" : "Mostrar"}
                    </button>
                  </div>
                </div>
                <div>
                  <label className="block mb-1 font-semibold">Confirmar Senha</label>
                  <div className="relative">
                    <input
                      type={showConfirmPasswordLoja ? "text" : "password"}
                      value={confirmarSenhaLoja}
                      onChange={e => setConfirmarSenhaLoja(e.target.value)}
                      className="w-full border rounded px-2 py-1 pr-20"
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirmPasswordLoja(!showConfirmPasswordLoja)}
                      className="absolute inset-y-0 right-0 flex items-center px-3 text-sm text-blue-600 hover:text-blue-800"
                      tabIndex={-1}
                      style={{ height: '100%' }}
                    >
                      {showConfirmPasswordLoja ? "Ocultar" : "Mostrar"}
                    </button>
                  </div>
                </div>
              </div>
              <div className="flex justify-between mt-4">
                <button
                  type="button"
                  className="px-4 py-2 bg-gray-300 rounded"
                  onClick={() => setShowCadastroLoja(false)}
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className={`px-4 py-2 bg-blue-600 text-white rounded ${senhaLoja !== confirmarSenhaLoja ? 'opacity-50 cursor-not-allowed' : ''}`}
                  disabled={senhaLoja !== confirmarSenhaLoja}
                >
                  Cadastrar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
}
