import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import logo from '../assets/logo.png';
import { errorMessage, successMessage } from '../components/Mensagem';
import { UsuarioServico } from '../services/UsuarioServico';
import EnableLoading from '../components/Loading';

export default function EsqueciMinhaSenha({ hash }) {
    const [cnpj, setCnpj] = useState('');
    const [nomeUsuario, setNomeUsuario] = useState('');
    const [tipoUsuario, setTipoUsuario] = useState('');
    const [consultando, setConsultando] = useState(false);
    const [emailMascarado, setEmailMascarado] = useState('');
    const [email, setEmail] = useState('');
    const [enviando, setEnviando] = useState(false);
    const [enviado, setEnviado] = useState(false);
    const navigate = useNavigate();

    const limparCNPJ = (valor) => {
        return valor.replace(/[^\d]/g, '');
    };

    const isEmbarcador = tipoUsuario === 'embarcador';

    const handleConsultar = async (e) => {
        e.preventDefault();

        if (!tipoUsuario) {
            return errorMessage('Por favor, selecione o tipo de usuário.');
        }

        if (isEmbarcador) {
            if (!nomeUsuario.trim()) {
                return errorMessage('Por favor, informe o nome do usuário.');
            }
        } else {
            if (!cnpj) {
                return errorMessage('Por favor, informe o CNPJ.');
            }
            const cnpjLimpo = limparCNPJ(cnpj);
            if (cnpjLimpo.length !== 14) {
                return errorMessage('Por favor, informe um CNPJ válido (14 dígitos).');
            }
        }

        setConsultando(true);

        const dados = isEmbarcador
            ? { login: nomeUsuario.trim(), tipoUsuario }
            : { cnpj: limparCNPJ(cnpj), tipoUsuario };

        try {
            const resposta = await UsuarioServico.ConsultarEmailRecuperacao(dados);

            if (resposta?.sucesso) {
                const emailParcial = resposta?.emailMascarado || resposta?.data?.emailMascarado || '';
                const email = resposta?.email || resposta?.data?.email || '';

                setEmailMascarado(emailParcial);
                setEmail(email)
            } else {

                var erros = resposta?.erros || '';
                var errosJson = JSON.parse(erros);

                errorMessage('Erro ao consultar e-mail. ' + errosJson.erros);
            }
        } catch (error) {
            console.log(error);
            errorMessage('Erro ao consultar. Tente novamente mais tarde.');

        } finally {
            setConsultando(false);
        }
    };

    const handleEnviarEmail = async () => {
        setEnviando(true);

        const dados = isEmbarcador
            ? { nome_usuario: nomeUsuario.trim(), tipo_usuario: tipoUsuario, email: email }
            : { nome_usuario: limparCNPJ(cnpj), tipo_usuario: tipoUsuario, email: email };


        try {

            const resposta = await UsuarioServico.RecuperarSenha(dados);

            if (resposta?.sucesso) {
                setEnviado(true);
                successMessage('E-mail de recuperação enviado com sucesso!');
            } else {
                errorMessage('Erro ao enviar e-mail de recuperação. ' + (resposta?.erros || ''));
            }
        } catch (error) {
            console.log(error);
            errorMessage('Erro ao enviar e-mail de recuperação. Tente novamente mais tarde.');
        } finally {
            setEnviando(false);
        }
    };

    return (
        <>
            <EnableLoading />
            <div className="flex items-center justify-center min-h-screen bg-gradient-to-r from-green-400 to-blue-500">
                <div className="bg-white p-10 rounded-lg shadow-lg max-w-md w-full">
                    <div className="mb-6 text-center">
                        <img src={logo} alt="Leo Madeiras" className="mx-auto mb-4 w-32" />
                        <h1 className="text-2xl font-bold">Recuperar Senha</h1>
                        <p className="text-gray-500 text-sm mt-2">
                            Informe seus dados e tipo de usuário para recuperar sua senha.
                        </p>
                    </div>

                    {!enviado ? (
                        <form onSubmit={handleConsultar} className="space-y-4">
                            <div>
                                <label className="block mb-1 font-semibold" htmlFor="tipo-usuario-recuperacao">
                                    Tipo de Usuário
                                </label>
                                <select
                                    id="tipo-usuario-recuperacao"
                                    className="w-full border rounded px-3 py-2"
                                    value={tipoUsuario}
                                    onChange={(e) => { setTipoUsuario(e.target.value); setEmailMascarado(''); }}
                                    disabled={!!emailMascarado}
                                >
                                    <option value="">Selecione...</option>
                                    <option value="loja">Loja</option>
                                    <option value="transportador">Transportador</option>
                                    <option value="embarcador">Embarcador</option>
                                </select>
                            </div>

                            <div>
                                {isEmbarcador ? (
                                    <>
                                        <label className="block mb-1 font-semibold" htmlFor="nome-usuario-recuperacao">
                                            Nome do Usuário
                                        </label>
                                        <input
                                            id="nome-usuario-recuperacao"
                                            type="text"
                                            placeholder="Seu nome de usuário"
                                            className="w-full border rounded px-3 py-2"
                                            value={nomeUsuario}
                                            onChange={(e) => { setNomeUsuario(e.target.value); setEmailMascarado(''); }}
                                            disabled={!!emailMascarado}
                                        />
                                    </>
                                ) : (
                                    <>
                                        <label className="block mb-1 font-semibold" htmlFor="cnpj-recuperacao">
                                            CNPJ
                                        </label>
                                        <input
                                            id="cnpj-recuperacao"
                                            type="text"
                                            placeholder="00.000.000/0001-00"
                                            className="w-full border rounded px-3 py-2"
                                            value={cnpj}
                                            onChange={(e) => { setCnpj(e.target.value); setEmailMascarado(''); }}
                                            disabled={!!emailMascarado}
                                        />
                                    </>
                                )}
                            </div>



                            {emailMascarado && (
                                <div className="p-3 border rounded bg-blue-50 text-center">
                                    <p className="text-sm text-gray-600 mb-1">O e-mail de recuperação será enviado para:</p>
                                    <p className="text-lg font-semibold text-blue-800">{emailMascarado}</p>
                                </div>
                            )}

                            {!emailMascarado && (
                                <button
                                    id="btn-consultar-email"
                                    type="submit"
                                    disabled={consultando}
                                    className={`w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition ${consultando ? 'opacity-50 cursor-not-allowed' : ''}`}
                                >
                                    {consultando ? 'Consultando...' : 'Consultar'}
                                </button>
                            )}

                            {emailMascarado && (
                                <div className="space-y-2">
                                    <button
                                        id="btn-enviar-recuperacao"
                                        type="button"
                                        disabled={enviando}
                                        onClick={handleEnviarEmail}
                                        className={`w-full bg-green-500 text-white py-2 rounded hover:bg-green-600 transition ${enviando ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    >
                                        {enviando ? 'Enviando...' : 'Enviar E-mail de Recuperação'}
                                    </button>
                                    <button
                                        type="button"
                                        onClick={() => setEmailMascarado('')}
                                        className="w-full text-sm text-gray-500 underline hover:text-gray-700"
                                    >
                                        Alterar dados
                                    </button>
                                </div>
                            )}
                        </form>
                    ) : (
                        <div className="text-center p-4">
                            <div className="text-green-500 mb-4">
                                <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                            </div>
                            <p className="text-gray-700 mb-4">
                                Um e-mail com as instruções de recuperação foi enviado para <strong>{emailMascarado}</strong>.
                            </p>
                            <p className="text-gray-500 text-sm">
                                Verifique sua caixa de entrada e a pasta de spam.
                            </p>
                        </div>
                    )}

                    <div className="mt-4 text-center">
                        <button
                            onClick={() => navigate('/')}
                            className="text-sm text-blue-700 underline hover:text-blue-900"
                            type="button"
                        >
                            Voltar para o Login
                        </button>
                    </div>
                </div>
            </div>
        </>
    );
}
