import { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';

import Lojas from './pages/Loja/Lojas';
import DespesaFreteRegiao from './pages/Embarcador/DespesaFreteRegiao';
import AprovacaoLojas from './pages/Embarcador/AprovacaoLojas';
import Transportadoras from './pages/Transportador/Transportadoras';
import PosicaoFrotas from './pages/Embarcador/PosicaoFrotas';
import ListaColetasEmbarcador from './pages/Embarcador/ListaColetasEmbarcador';
import Login from './pages/Login';
import Aprovacao from './pages/Embarcador/Aprovacao';
import EsqueciMinhaSenha from './pages/EsqueciMinhaSenha';
import RedefinirSenha from './pages/RedefinirSenha';
import AprovacoesPendentes from './pages/Embarcador/AprovacoesPendentes';

import SidebarLayout from './components/SidebarLayout';
import SidebarLayoutTransportador from './components/SidebarLayoutTransportador';
import SidebarLayoutLoja from './components/SidebarLayoutLoja';

import TransportadorHome from './pages/Transportador/TransportadorHome';
import DadosTransportador from './pages/Transportador/DadosTransportador';
import ImportacaoCTe from './pages/Transportador/ImportacaoCTe';
import Faturas from './pages/Transportador/Faturas';

import Coletas from './pages/Loja/Coletas';
import ListaColetas from './pages/Loja/ListaColetas';
import CarreteirosCadastro from './pages/Loja/CarreteirosCadastro'; // importe o novo componente

import DadosLoja from './pages/Loja/DadosLoja';

import OrdemDeColetaPrint from './components/OrdemDeColetaPrint';
import EnableLoading from './components/Loading';

export default function App() {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem('user');
    return savedUser ? JSON.parse(savedUser) : null;
  });

  useEffect(() => {
    if (user) localStorage.setItem('user', JSON.stringify(user));
    else localStorage.removeItem('user');

    if (user) localStorage.setItem('token', user.token);
    else localStorage.removeItem('token');

    if (user) localStorage.setItem('login', user.login)
    else localStorage.removeItem('login');

    if (user) localStorage.setItem('tipoUsuario', user.tipoUsuario);
    else localStorage.removeItem('tipoUsuario');
  }, [user]);

  // Helper to get default route by user type
  const getDefaultRoute = () => {
    if (user?.tipoUsuario === 'embarcador') return '/aprovacao';
    if (user?.tipoUsuario === 'transportador') return '/transportador';
    if (user?.tipoUsuario === 'loja') return '/loja/coletas';
    return '/';
  };

  const hash = '';

  return (
    <>
      <Router>
        <Routes>
          <Route path="/" element={<Login onLogin={setUser} />} />
          <Route path={'/' + hash == undefined ? '' : hash + '/esqueci-minha-senha'} element={<EsqueciMinhaSenha hash={hash} />} />
          <Route path="/redefinir-senha/:hash" element={<RedefinirSenha />} />


          {user?.tipoUsuario === 'embarcador' && (
            <>

              <Route path="/dashboard" element={<Navigate to="/lojas" replace />} />
              <Route path="/esqueci-minha-senha" element={<EsqueciMinhaSenha />} />
              <Route
                path="/aprovacao"
                element={
                  <SidebarLayout user={user}>
                    <Aprovacao user={user} />
                  </SidebarLayout>
                }
              />

              <Route
                path="/aprovacoes-pendentes"
                element={
                  <SidebarLayout user={user}>
                    <AprovacoesPendentes user={user} />
                  </SidebarLayout>
                }
              />

              <Route
                path="/aprovacao-lojas"
                element={
                  <SidebarLayout user={user}>
                    <AprovacaoLojas user={user} />
                  </SidebarLayout>
                }
              />

              <Route
                path="/lojas"
                element={
                  <SidebarLayout user={user}>
                    <Lojas user={user} />
                  </SidebarLayout>
                }
              />
              <Route
                path="/DespesaFreteRegiao"
                element={
                  <SidebarLayout user={user}>
                    <DespesaFreteRegiao user={user} />
                  </SidebarLayout>
                }
              />
              <Route
                path="/transportadoras"
                element={
                  <SidebarLayout user={user}>
                    <Transportadoras user={user} />
                  </SidebarLayout>
                }
              />
              <Route
                path="/posicao-frotas"
                element={
                  <SidebarLayout user={user}>
                    <PosicaoFrotas user={user} />
                  </SidebarLayout>
                }
              />
              <Route
                path="/lista-coletas-embarcador"
                element={
                  <SidebarLayout user={{ name: "João", role: "embarcador" }}>
                    <ListaColetasEmbarcador />
                  </SidebarLayout>
                }
              />
            </>
          )}

          {user?.tipoUsuario === 'transportador' && (
            <>
              <Route
                path="/transportador"
                element={
                  <SidebarLayoutTransportador user={user}>
                    <TransportadorHome user={user} />
                  </SidebarLayoutTransportador>
                }
              />
              <Route
                path="/transportador/dados"
                element={
                  <SidebarLayoutTransportador user={user}>
                    <DadosTransportador user={user} />
                  </SidebarLayoutTransportador>
                }
              />
              {/* <Route
                path="/importacao"
                element={
                  <SidebarLayoutTransportador user={user}>
                    <ImportacaoCTe user={user} />
                  </SidebarLayoutTransportador>
                }
              /> */}
              <Route
                path="/faturas"
                element={
                  <SidebarLayoutTransportador user={user}>
                    <Faturas user={user} />
                  </SidebarLayoutTransportador>
                }
              />
            </>
          )}

          {user?.tipoUsuario === 'loja' && (
            <>
              <Route
                path="/loja/coletas"
                element={
                  <SidebarLayoutLoja user={user}>
                    <Coletas user={user} />
                  </SidebarLayoutLoja>
                }
              />
              <Route
                path="/loja/lista-coletas"
                element={
                  <SidebarLayoutLoja user={user}>
                    <ListaColetas user={user} />
                  </SidebarLayoutLoja>
                }
              />
              <Route
                path="/loja/dados-loja"
                element={
                  <SidebarLayoutLoja user={user}>
                    {/* Dados da Loja */}
                    <DadosLoja user={user} />
                  </SidebarLayoutLoja>
                }
              />
              <Route
                path="/loja/carreteiros"
                element={
                  <SidebarLayoutLoja user={user}>
                    <CarreteirosCadastro user={user} />
                  </SidebarLayoutLoja>
                }
              />
            </>
          )}

          {/* 📄 Rota para a impressão da ordem de coleta */}
          <Route path="/coleta/print/:id" element={<OrdemDeColetaPrint />} />

          {/* Default redirect for unknown routes */}
          <Route
            path="*"
            element={<Navigate to={getDefaultRoute()} replace />}
          />
        </Routes>
      </Router>
    </>

  );
}
