import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import logo from '../assets/logo.png';
import { errorMessage, successMessage } from '../components/Mensagem';
import { UsuarioServico } from '../services/UsuarioServico';
import { ValidarPreSenha } from '../utilities/Utilidades';
import EnableLoading from '../components/Loading';

export default function RedefinirSenha() {
    const { hash } = useParams();
    const [novaSenha, setNovaSenha] = useState('');
    const [confirmarSenha, setConfirmarSenha] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [enviando, setEnviando] = useState(false);
    const [sucesso, setSucesso] = useState(false);
    const [validandoHash, setValidandoHash] = useState(true);
    const [hashInvalido, setHashInvalido] = useState(false);
    const [idUsuario, setIdUsuario] = useState(null);
    const [tipoUsuario, setTipoUsuario] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        validaHash();
    }, [hash]);

    const validaHash = async () => {
        try {
            const resposta = await UsuarioServico.DecodificarHash(hash);

            if (resposta?.sucesso && (resposta?.data?.id_usuario || resposta?.id_usuario)) {
                setIdUsuario(resposta?.data?.id_usuario || resposta?.id_usuario);
                setTipoUsuario(resposta?.data?.tipo_usuario || resposta?.tipo_usuario || '');
                setHashInvalido(false);
            } else {
                setHashInvalido(true);
                errorMessage('O link de redefinição é inválido ou já expirou.');
            }
        } catch (error) {
            console.error(error);
            setHashInvalido(true);
            errorMessage('Erro ao validar link. Tente novamente mais tarde.');
        } finally {
            setValidandoHash(false);
        }
    };


    console.log(hash);
    console.log(idUsuario);

    const handleRedefinir = async (e) => {
        e.preventDefault();

        if (!novaSenha || !confirmarSenha) {
            return errorMessage('Por favor, preencha todos os campos.');
        }

        if (novaSenha !== confirmarSenha) {
            return errorMessage('As senhas não coincidem.');
        }

        if (!ValidarPreSenha(novaSenha)) {
            return errorMessage('A senha deve conter ao menos 8 caracteres, letras e números.');
        }

        setEnviando(true);

        try {
            const resposta = await UsuarioServico.RedefinirSenha({
                ID_Usuario: idUsuario,
                Nova_Senha: novaSenha,
                Tipo_Usuario: tipoUsuario
            });

            if (resposta?.sucesso || resposta?.status === 200) {
                setSucesso(true);
                successMessage('Senha redefinida com sucesso!');
            } else {
                errorMessage('Erro ao redefinir senha. ' + (resposta?.erros || 'Link inválido ou expirado.'));
            }
        } catch (error) {
            console.log(error);
            errorMessage('Erro ao redefinir senha. Tente novamente mais tarde.');
        } finally {
            setEnviando(false);
        }
    };

    return (
        <>
            <EnableLoading />
            <div className="flex items-center justify-center min-h-screen bg-gradient-to-r from-green-400 to-blue-500">
                <div className="bg-white p-10 rounded-lg shadow-lg max-w-md w-full">
                    <div className="mb-6 text-center">
                        <img src={logo} alt="Leo Madeiras" className="mx-auto mb-4 w-32" />
                        <h1 className="text-2xl font-bold">Redefinir Senha</h1>
                        <p className="text-gray-500 text-sm mt-2">
                            {validandoHash ? 'Validando link...' : hashInvalido ? 'Link inválido' : 'Digite sua nova senha abaixo.'}
                        </p>
                    </div>

                    {validandoHash ? (
                        <div className="text-center p-10">
                            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-500 mx-auto mb-4"></div>
                            <p className="text-gray-600">Verificando validade do link...</p>
                        </div>
                    ) : hashInvalido ? (
                        <div className="text-center p-4">
                            <div className="text-red-500 mb-4">
                                <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                                </svg>
                            </div>
                            <p className="text-gray-700 mb-4">
                                Este link de redefinição de senha não é mais válido ou já expirou.
                            </p>
                            <button
                                onClick={() => navigate('/esqueci-minha-senha')}
                                className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition"
                            >
                                Solicitar novo link
                            </button>
                        </div>
                    ) : !sucesso ? (
                        <form onSubmit={handleRedefinir} className="space-y-4">
                            <div>
                                <label className="block mb-1 font-semibold" htmlFor="nova-senha">
                                    Nova Senha
                                </label>
                                <div className="relative">
                                    <input
                                        id="nova-senha"
                                        type={showPassword ? "text" : "password"}
                                        placeholder="Digite a nova senha"
                                        className="w-full border rounded px-3 py-2 pr-10"
                                        value={novaSenha}
                                        onChange={(e) => setNovaSenha(e.target.value)}
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                                        tabIndex={-1}
                                    >
                                        {showPassword ? (
                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.878 9.878L6.5 6.5m3.378 3.378a3 3 0 004.243-4.242M6.5 6.5L4 4m15.071 15.071L4.929 4.929" />
                                            </svg>
                                        ) : (
                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268-2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                                            </svg>
                                        )}
                                    </button>
                                </div>
                            </div>

                            <div>
                                <label className="block mb-1 font-semibold" htmlFor="confirmar-senha">
                                    Confirmar Nova Senha
                                </label>
                                <input
                                    id="confirmar-senha"
                                    type={showPassword ? "text" : "password"}
                                    placeholder="Confirme a nova senha"
                                    className="w-full border rounded px-3 py-2"
                                    value={confirmarSenha}
                                    onChange={(e) => setConfirmarSenha(e.target.value)}
                                />
                            </div>

                            <button
                                id="btn-redefinir-senha"
                                type="submit"
                                disabled={enviando}
                                className={`w-full bg-green-500 text-white py-2 rounded hover:bg-green-600 transition ${enviando ? 'opacity-50 cursor-not-allowed' : ''
                                    }`}
                            >
                                {enviando ? 'Processando...' : 'Redefinir Senha'}
                            </button>
                        </form>
                    ) : (
                        <div className="text-center p-4">
                            <div className="text-green-500 mb-4">
                                <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                            </div>
                            <p className="text-gray-700 mb-4">
                                Sua senha foi redefinida com sucesso! Agora você já pode fazer login com a nova senha.
                            </p>
                            <button
                                onClick={() => navigate('/')}
                                className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition"
                            >
                                Ir para o Login
                            </button>
                        </div>
                    )}

                    {!sucesso && (
                        <div className="mt-4 text-center">
                            <button
                                onClick={() => navigate('/')}
                                className="text-sm text-blue-700 underline hover:text-blue-900"
                                type="button"
                            >
                                Voltar para o Login
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </>
    );
}
