// src/pages/DadosTransportador.js
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiTruck, FiUser, FiMapPin, FiPhone, FiMail, FiFileText, FiEdit, FiSave, FiX } from 'react-icons/fi';
import { errorMessage, successMessage } from '../../components/Mensagem';
import { TransportadorServico } from '../../services/TransportadorServico';
import { EnderecoServico } from '../../services/EnderecoServico';
import EnableLoading from '../../components/Loading';

export default function DadosTransportador({ user }) {
  const [isEditing, setIsEditing] = useState(false);
  const [cepEditado, setCepEditado] = useState(false);
  const [cepBuscaLoading, setCepBuscaLoading] = useState(false);
  const [cepBuscaErro, setCepBuscaErro] = useState('');
  const [transportadorData, setTransportadorData] = useState({
    nomeEmpresa: '',
    cnpj: '',
    endereco: '',
    numero: '',
    bairro: '',
    cidade: '',
    estado: '',
    cep: '',
    telefone: '',
    email: '',
    observacoes: ''
  });

  const [loading, setLoading] = useState(true);
  const [erroCaptura, setErroCaptura] = useState('');
  const navigate = useNavigate();
  const numeroRef = useRef(null);

  useEffect(() => {
    loadTransportadorData();
  }, []);

  const loadTransportadorData = async () => {
    try {
      setLoading(true);
      setErroCaptura('');

      const resultado = await TransportadorServico.BuscarTransportadorPorCNPJ(user?.cnpj);

      if (resultado && resultado.data.cgc) {
        setTransportadorData({
          nomeEmpresa: resultado.data.nome || '',
          cnpj: resultado.data.cgc || '',
          endereco: resultado.data.endereco ? `${resultado.data.endereco}` : '',
          numero: resultado.data.nR_Endereco || '',
          bairro: resultado.data.bairro || '',
          cidade: resultado.data.cidade || '',
          estado: resultado.data.uf || '',
          cep: resultado.data.cep || '',
          telefone: resultado.data.fone || '',
          email: resultado.data.email || '',
          responsavel: resultado.data.nome || '',
          observacoes: resultado.data.bairro || ''
        });
      } else {
        setErroCaptura('Transportador não encontrado ou dados incompletos.');
        errorMessage('Transportador não encontrado ou dados incompletos.');
      }
      setLoading(false);
    } catch (error) {
      setErroCaptura('Erro ao carregar dados do transportador: ' + error);
      errorMessage('Erro ao carregar dados do transportador: ' + error);
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    let newValue = value;

    // Validação e limpeza do CEP
    if (name === "cep") {
      // Remove tudo que não for número
      newValue = value.replace(/[^\d]/g, '');
    }

    setTransportadorData(prev => ({
      ...prev,
      [name]: newValue
    }));
  };

  const editarDadosTransportador = async (dados) => {
    try {
      var resposta = await TransportadorServico.EditarTransportador(dados);

      if (resposta?.sucesso) {
        successMessage('Dados atualizados com sucesso! ');
        console.log('Dados salvos no servidor:', resposta);
      } else {
        resposta.sucesso = false;
        resposta.mensagem = error;
        resposta.erros = error.message;
        errorMessage(resposta?.error || 'Erro ao salvar dados do transportador');
        console.error('Erro na edição:', resposta);
      }
    } catch (error) {
      resposta.sucesso = false;
      resposta.mensagem = error;
      resposta.erros = error.message;
      console.error('Erro ao editar dados do transportador:', error);
      errorMessage('Erro ao conectar com o servidor: ' + error);
    }
    finally {
      return resposta;
    }
  };

  const handleSave = async () => {
    if (
      !transportadorData.cep ||
      !transportadorData.endereco ||
      !transportadorData.numero ||
      !transportadorData.bairro ||
      !transportadorData.cidade ||
      !transportadorData.estado
    ) {
      errorMessage('Preencha todos os campos de endereço antes de salvar.');
      return;
    }

    let dataAprovacao = transportadorData.data_Aprovacao;
    if (!dataAprovacao || isNaN(Date.parse(dataAprovacao))) {
      dataAprovacao = null;
    }

    try {
      const dadosParaSalvar = {
        cgc: transportadorData.cnpj,
        nome: transportadorData.nomeEmpresa,
        ie: transportadorData.ie || '',
        cep: transportadorData.cep,
        endereco: transportadorData.endereco,
        nR_Endereco: transportadorData.numero,
        bairro: transportadorData.bairro,
        cidade: transportadorData.cidade,
        uf: transportadorData.estado,
        fone: transportadorData.telefone,
        email: transportadorData.email,
        status_Aprovacao: transportadorData.status_Aprovacao || 'A',
        data_Aprovacao: dataAprovacao,
        data_Cadastro: transportadorData.data_Cadastro || null,
        cD_Filial: transportadorData.cD_Filial || ''
      };

      const resultado = await TransportadorServico.EditarTransportador(dadosParaSalvar);

      if (resultado?.sucesso) {
        successMessage('Dados atualizados com sucesso! ');
        setIsEditing(false);
        loadTransportadorData();
      } else {
        errorMessage(resultado?.mensagem || 'Erro ao salvar dados do transportador');
      }
    } catch (error) {
      errorMessage('Erro ao conectar com o servidor: ' + error);
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    loadTransportadorData(); 
  };

  const handleEditClick = () => {
    setIsEditing(true);
    setCepEditado(true); 
  };

  const handleCepKeyDown = async (e) => {
    if (e.key === 'Enter') {
      setCepBuscaLoading(true);
      setCepBuscaErro('');
      const endereco = await EnderecoServico.buscarEnderecoPorCep(transportadorData.cep);
      setCepBuscaLoading(false);
      if (endereco) {
        setTransportadorData(prev => ({
          ...prev,
          endereco: endereco.endereco,
          bairro: endereco.bairro,
          cidade: endereco.cidade,
          estado: endereco.uf
        }));
        setCepEditado(true); 
        setTimeout(() => {
          if (numeroRef.current) numeroRef.current.focus();
        }, 100);
      } else {
        setCepBuscaErro('CEP não encontrado ou inválido.');
      }
    }
  };

  if (loading) {
    return (
      <main className="flex-1 p-6 bg-gray-100 min-h-screen">
        <EnableLoading />
        <div className="flex justify-center items-center h-64">
          <p className="text-gray-500">Carregando dados do transportador...</p>
        </div>
      </main>
    );
  }

  return (
    <main className="flex-1 p-6 bg-gray-100 min-h-screen">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <div className="flex justify-between items-center">
            <div className="flex items-center">
              <FiTruck className="text-green-600 text-3xl mr-4" />
              <div>
                <h1 className="text-2xl font-bold text-gray-800">Dados da Transportadora</h1>
                <p className="text-gray-600">Informações da empresa e responsável</p>
              </div>
            </div>
            <div className="flex space-x-2">
              {!isEditing ? (
                <button
                  onClick={handleEditClick}
                  className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 flex items-center"
                >
                  <FiEdit className="mr-2" />
                  Editar
                </button>
              ) : (
                <div className="flex space-x-2">
                  <button
                    onClick={handleSave}
                    className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 flex items-center"
                  >
                    <FiSave className="mr-2" />
                    Salvar
                  </button>
                  <button
                    onClick={handleCancel}
                    className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-700 flex items-center"
                  >
                    <FiX className="mr-2" />
                    Cancelar
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Dados da Empresa */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiFileText className="mr-2 text-green-600" />
            Dados da Empresa
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nome da Empresa
              </label>
              <input
                type="text"
                name="nomeEmpresa"
                value={transportadorData.nomeEmpresa}
                onChange={handleInputChange}
                disabled={true} // Sempre bloqueado
                className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                CNPJ
              </label>
              <input
                type="text"
                name="cnpj"
                value={transportadorData.cnpj}
                onChange={handleInputChange}
                disabled={true} // Sempre bloqueado
                className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50"
              />
            </div>


            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                CEP
              </label>
              <input
                type="text"
                name="cep"
                value={transportadorData.cep}
                onChange={handleInputChange}
                onKeyDown={handleCepKeyDown}
                disabled={!isEditing}
                required
                className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
                placeholder="Digite o CEP e pressione Enter"
              />
              {cepBuscaLoading && <span className="text-blue-600 text-sm">Buscando endereço...</span>}
              {cepBuscaErro && <span className="text-red-600 text-sm">{cepBuscaErro}</span>}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Endereço
              </label>
              <input
                required
                type="text"
                name="endereco"
                value={transportadorData.endereco}
                onChange={handleInputChange}
                disabled={!isEditing}
                className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Numero
              </label>
              <input
                required
                ref={numeroRef}
                type="text"
                name="numero"
                value={transportadorData.numero}
                onChange={handleInputChange}
                disabled={!isEditing}
                className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>

            <div>
              <label>
                Bairro
              </label>
              <input
                required
                type="text"
                name="bairro"
                value={transportadorData.bairro}
                onChange={handleInputChange}
                disabled={!isEditing}
                className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              />
            </div>


            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Cidade
              </label>
              <input
                type="text"
                name="cidade"
                value={transportadorData.cidade}
                onChange={handleInputChange}
                required
                disabled={true}
                className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Estado
              </label>
              <input
                required
                type="text"
                name="estado"
                value={transportadorData.estado}
                onChange={handleInputChange}
                disabled={true}
                className="w-full p-3 border rounded-lg border-gray-200 bg-gray-50"
              />
            </div>


          </div>
        </div>

        {/* Dados de Contato */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiUser className="mr-2 text-green-600" />
            Dados de Contato
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                <FiPhone className="inline mr-1" />
                Telefone
              </label>
              <input
                disabled
                type="text"
                name="telefone"
                value={transportadorData.telefone}
                onChange={handleInputChange}
                // disabled={!isEditing}
                className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'
                  }`}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                <FiMail className="inline mr-1" />
                Email
              </label>
              <input
                type="email"
                name="email"
                value={transportadorData.email}
                onChange={handleInputChange}
                disabled={!isEditing}
                className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'
                  }`}
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Responsável
              </label>
              <input
                type="text"
                name="responsavel"
                value={transportadorData.responsavel}
                onChange={handleInputChange}
                disabled={isEditing || true} // Sempre bloqueado
                className={`w-full p-3 border rounded-lg border-gray-200 bg-gray-50`}
              />
            </div>
          </div>
        </div>

        {/* Observações */}
        <div className="bg-white p-6 rounded-lg shadow">
          <h2 className="text-xl font-semibold mb-4 flex items-center">
            <FiFileText className="mr-2 text-green-600" />
            Observações
          </h2>

          <div>
            <textarea
              name="observacoes"
              value={transportadorData.observacoes}
              onChange={handleInputChange}
              disabled={!isEditing}
              rows={4}
              className={`w-full p-3 border rounded-lg ${isEditing ? 'border-gray-300 focus:border-blue-500' : 'border-gray-200 bg-gray-50'}`}
              placeholder="Informações adicionais sobre a transportadora..."
            />
          </div>
        </div>

        {/* Status */}
        <div className="bg-white p-6 rounded-lg shadow mt-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg font-semibold text-gray-800">Status do Cadastro</h3>
              <p className="text-sm text-gray-600">Situação atual da transportadora no sistema</p>
            </div>
            <div className="text-right">
              <span className="inline-block bg-green-100 text-green-800 px-3 py-1 rounded-full text-sm font-medium">
                ✓ Ativo
              </span>
              <p className="text-xs text-gray-500 mt-1">Cadastro aprovado</p>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}