// src/components/SidebarLayout.js
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { FiMenu, FiTruck, FiMapPin, FiLogOut } from 'react-icons/fi';
import { FaClipboardList, FaCheck } from 'react-icons/fa';

import { FaStore } from 'react-icons/fa';
import logo from '../assets/logo.png';

function SidebarLayout({ user, children }) {
    const [open, setOpen] = useState(true);
    const navigate = useNavigate();
    const location = useLocation();

    useEffect(() => {
        if (!user) {
            navigate('/');
        }
    }, [user, navigate]);

    if (!user) return null;

    const handleLogout = () => {
        navigate('/');
    };

    // Para determinar o link ativo
    const isActive = (path) => location.pathname === path;

    return (
        <div className="flex min-h-screen">
            <aside
                className={`bg-green-900 text-white transition-all ${open ? 'w-64' : 'w-16'
                    } p-4 flex flex-col justify-between`}
            >
                <div>
                    {/* Botão de expandir/recolher */}
                    <button
                        onClick={() => setOpen(!open)}
                        className="mb-4 text-2xl p-2 hover:bg-green-800 rounded"
                    >
                        <FiMenu />
                    </button>

                    {/* Logo e saudação */}
                    {open && (
                        <div className="mb-6 flex flex-col items-center">
                            <img src={logo} alt="Leo Madeiras" className="w-20 h-auto mb-2" />
                            <h2 className="text-center font-bold text-xl">Olá, embarcador</h2>
                            <p className="text-center text-sm opacity-75">{user.tipoUsuario}</p>
                        </div>
                    )}

                    {/* Links de navegação */}
                    <nav className="space-y-2">
                        <Link
                            to="/aprovacoes-pendentes"
                            className={`flex items-center p-2 rounded ${isActive('/aprovacoes-pendentes')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FaCheck className="mr-2" /> {open && 'Aprovações Pendentes'}
                        </Link>


                        <Link
                            to="/lojas"
                            className={`flex items-center p-2 rounded ${isActive('/lojas')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FaStore className="mr-2" /> {open && 'Despesas Frete'}
                        </Link>

                        <Link
                            to="/DespesaFreteRegiao"
                            className={`flex items-center p-2 rounded ${isActive('/DespesaFreteRegiao')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FaStore className="mr-2" /> {open && 'Despesas por Região'}
                        </Link>

                        <Link
                            to="/posicao-frotas"
                            className={`flex items-center p-2 rounded ${isActive('/posicao-frotas')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FiMapPin className="mr-2" /> {open && 'Posição Entrega'}
                        </Link>

                        <Link
                            to="/transportadoras"
                            className={`flex items-center p-2 rounded ${isActive('/transportadoras')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FiTruck className="mr-2" /> {open && 'Transportadoras'}
                        </Link>


                        <Link
                            to="/aprovacao-lojas"
                            className={`flex items-center p-2 rounded ${isActive('/aprovacao-lojas')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FaStore className="mr-2" /> {open && 'Aprovar Lojas'}
                        </Link>

                        <Link
                            to="/lista-coletas-embarcador"
                            className={`flex items-center p-2 rounded ${isActive('/lista-coletas-embarcador')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FaClipboardList className="mr-2" /> {open && 'Aprovar Coletas'}
                        </Link>


                        <Link
                            to="/Aprovacao"
                            className={`flex items-center p-2 rounded ${isActive('/Aprovacao')
                                ? 'bg-yellow-500 text-black'
                                : 'hover:bg-green-800'
                                }`}
                        >
                            <FiTruck className="mr-2" /> {open && 'Aprovar Transportador'}
                        </Link>

                        {/* Botão sair */}
                        <button
                            onClick={handleLogout}
                            className="flex items-center p-2 hover:bg-green-800 rounded mt-4"
                        >
                            <FiLogOut className="mr-2" /> {open && 'Sair'}
                        </button>

                    </nav>

                </div>

            </aside>

            {/* Conteúdo principal */}
            <main className="flex-1 p-4 bg-gray-100 overflow-auto">{children}</main>
        </div>
    );
}

export default SidebarLayout;
