import { useState } from "react";
import { useEffect } from "react";
import { EmbarcadorrServico } from '../../services/EmbarcadorServico';
import { errorMessage, successMessage, confirmMessage } from '../../components/Mensagem';
import { FiCheck, FiXCircle } from 'react-icons/fi';
import { FaCheckCircle, FaTimesCircle, FaPen, FaSave } from 'react-icons/fa';

function Modal({ isOpen, onClose, coleta, fetchColetas }) {
    const [labelStyle, setLabelStyle] = useState("block text-sm font-semibold text-gray-700");
    const [inputStyle, setInputStyle] = useState("border rounded px-3 py-2 bg-gray-50");
    const [vr_novo_frete, setVr_novo_frete] = useState("0");

    useEffect(() => {

        if (coleta?.vr_frete !== undefined && coleta.vr_frete !== null) {
            setVr_novo_frete(
                coleta?.vr_frete?.toString?.()?.replaceAll(",", ".") || "0"
            );
        } else {
            setVr_novo_frete("0");
        }

    }, [coleta]);

    const handleNovo_VrFrete = (e) => {
        console.log('adicionando ' + e);
        setVr_novo_frete(e);
    }

    const atualizar_Coleta_Valor_Frete = async () => {

        var confirmacao = await confirmMessage('Coleta Nº' + coleta.id,
            'Deseja atualizar a coleta ' + coleta.id + ' com o valor de frete R$' + vr_novo_frete + '?'
        );

        if (!confirmacao.isConfirmed) return;
        //
        var coleta_payload = {
            //CGC_CPF_Cliente
            "VR_Frete": vr_novo_frete.toString?.()?.replaceAll(",", "."),
            "Observacao": coleta.observacao,
            "CGC_CPF_Solicitante": "",
            "CD_Empresa": coleta.cd_Empresa,
            "CD_Filial": coleta.cd_Filial,
            "CGC_CPF_Destinatario": "",
            "NR_Coleta": coleta.id,
            "CGC_CPF_Cliente": coleta.cliente,
            "ST_Coleta": "",
            "Operador": "",
            "CGC_CPF_Transportadora": "",
            "DT_Solicitacao_Coleta": "0001-01-01T00:00:00",
            "TP_Status_Coleta": "",
            "DT_Atualizacao": "0001-01-01T00:00:00",
            "Razao_Social": "",
            "CNPJ": "",
            "ID_Carreteiro": 0,
            "ST_Coleta": coleta.status === "PENDENTE DE APROVAÇÃO" ? "NÃO INICIADA" : "",
            "CD_Motivo_Coleta": "",
            "UF_Origem": coleta.uF_Origem,
            "Cidade_Origem": coleta.cidade_Origem,
            "Bairro_Origem": coleta.bairro_Origem,
            "Endereco_Coleta_Origem": coleta.endereco_Coleta_Origem,
            "NR_Endereco_Origem": coleta.nR_Endereco_Origem,
            "UF_Destinatario": coleta.uF_Destinatario,
            "Cidade_Destinatario": coleta.cidade_Destinatario,
            "Bairro_Destinatario": coleta.bairro_Destinatario,
            "Endereco_Destinatario": coleta.endereco_Destinatario,
            "NR_Endereco_Destinatario": coleta.nR_Endereco_Destinatario,
            "NR_NF_Servico": "",
            "NR_Fatura": "",
            "CD_Divisao": "",
            "Operador": localStorage.getItem("login") || ""
        }


        EmbarcadorrServico.AtualizarColeta(coleta_payload).then((resultado) => {

            //var mensagem = JSON.parse(resultado.mensagem).mensagem;

            if (resultado && resultado.sucesso) {
                successMessage("Coleta editada com sucesso!");
                fetchColetas();

            } else {

                errorMessage(JSON.parse(resultado?.mensagem)?.mensagem || "Erro ao editar coleta.");
            }
        })

    };


    console.log(coleta);
    if (!isOpen || !coleta) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg shadow-lg w-[700px] p-6">
                <h2 className="text-2xl font-bold mb-6 text-center">Detalhes da Coleta</h2>
                <div className="grid grid-cols-2 gap-4">



                    <div style={{ top: 20, backgroundColor: '#f0f0f0', padding: '10px' }}>
                        <label className={labelStyle}>
                            <strong>
                                Origem
                            </strong>
                        </label>
                        <br></br>

                        <div>
                            <label className={labelStyle}>UF Origem</label>
                            <p className={inputStyle}>{coleta.uF_Origem}</p>
                        </div>

                        <div>
                            <label className={labelStyle}>Cidade Origem</label>
                            <p className={inputStyle}>{coleta.cidade_Origem}</p>
                        </div>

                        <div>
                            <label className={labelStyle}>Bairro Origem</label>
                            <p className={inputStyle}>{coleta.bairro_Origem}</p>
                        </div>

                        <div>
                            <label className={labelStyle}>Endereço Origem</label>
                            <p className={inputStyle}>{coleta.endereco_Coleta_Origem} | Nº {coleta.nR_Endereco_Origem}</p>
                        </div>

                    </div>



                    <div style={{ top: 20, backgroundColor: '#f0f0f0', padding: '10px' }}>
                        <label className={labelStyle}>
                            <strong>
                                Destino
                            </strong>
                        </label>
                        <br></br>

                        <div>
                            <label className={labelStyle}>UF Destino</label>
                            <p className={inputStyle}>{coleta.uF_Destinatario}</p>
                        </div>

                        <div>
                            <label className={labelStyle}>Cidade Destinatário</label>
                            <p className={inputStyle}>{coleta.cidade_Destinatario}</p>
                        </div>

                        <div>
                            <label className={labelStyle}>Bairro Destinatário</label>
                            <p className={inputStyle}>{coleta.bairro_Destinatario}</p>
                        </div>


                        <div>
                            <label className={labelStyle}>Endereço Destinatário</label>
                            <p className={inputStyle}>{coleta.endereco_Destinatario} | Nº {coleta.nR_Endereco_Destinatario}</p>
                        </div>
                    </div>


                    <div>
                        <label className={labelStyle}><strong>Nº Coleta </strong></label>
                        <p className={inputStyle}>{coleta.id}</p>
                    </div>


                    <div>
                        <label className={labelStyle}>Valor do Frete</label>

                        {/*<p className={inputStyle}>*/}
                        {/*    {coleta.vr_frete ? `R$ ${parseFloat(coleta.vr_frete).toFixed(2)}` : 'R$ 0'}*/}
                        {/*</p>*/}
                        <p>
                            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                <div>R$ &nbsp;</div>
                                <div>
                                    <input className={inputStyle} type="text"
                                        onChange={(e) => { handleNovo_VrFrete(e.target.value) }}

                                        value={vr_novo_frete} >
                                    </input>
                                </div>
                            </div>
                        </p>

                    </div>

                    <div className="col-span-2">
                        <label className={labelStyle}>Observação</label>
                        <p className={inputStyle}>{coleta.observacao || "N/A"}</p>
                    </div>
                </div>

                <div className="flex justify-between mt-6">

                    <button
                        onClick={atualizar_Coleta_Valor_Frete}
                        className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
                    >
                        <div style={{ display: 'inline-flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            Atualizar  &nbsp;                       <FaSave size={16} />
                        </div>
                    </button>

                    <button
                        onClick={onClose}
                        className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-700"
                    >
                        <div style={{ display: 'inline-flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            Fechar &nbsp; <FaTimesCircle size={16} />
                        </div>

                    </button>

                </div>

                {/*
                <div className="flex justify-end mt-6">
                    <button
                        onClick={onClose}
                        className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
                    >
                        Atualizar
                    </button>
                </div>
                */}

            </div>
        </div>
    );
}


export default function ListaColetasEmbarcador() {

    const [filtroMotivo, setFiltroMotivo] = useState("");
    const [filtroStatus, setFiltroStatus] = useState("NÃO INICIADA");
    const [coletas, setColetas] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [modalOpen, setModalOpen] = useState(false);
    const [selectedColeta, setSelectedColeta] = useState(null);

    const today = new Date();
    const oneMonthAgo = new Date();
    oneMonthAgo.setMonth(today.getMonth() - 1);
    const formatDateBR = (date) => {
        const d = date;
        const day = String(d.getDate()).padStart(2, '0');
        const month = String(d.getMonth() + 1).padStart(2, '0');
        const year = d.getFullYear();
        return `${day}/${month}/${year}`;
    };

    const [filtroInicio, setFiltroInicio] = useState(formatDateBR(oneMonthAgo));
    const [filtroFim, setFiltroFim] = useState(formatDateBR(today));

    useEffect(() => {
        setFiltroInicio(formatDateBR(oneMonthAgo));
        setFiltroFim(formatDateBR(today));
        fetchColetas();
    }, []);



    const isValidDate = (str) => {
        if (!str) return false;
        const regex = /^\d{2}\/\d{2}\/\d{4}$/;
        if (!regex.test(str)) return false;
        const [day, month, year] = str.split('/');
        return year.length === 4 && !isNaN(Date.parse(`${year}-${month}-${day}`));
    };
    const formatDate = (iso) => {
        const d = new Date(iso);
        return d.toLocaleDateString("pt-BR");
    };

    const motivosMap = { "001": "Devolução", "002": "Reentrega", "003": "Entrega", "004": "Coleta" };

    const fetchColetas = async () => {
        setLoading(true);
        setError("");
        try {
            const resposta = await EmbarcadorrServico.BuscarColetasPendentes({
                data_Inicial: filtroInicio,
                data_Final: filtroFim,
                motivo_Coleta: filtroMotivo,
                status_Coleta: filtroStatus
            });
            console.log("API resposta:", resposta.data);
            if (resposta.data && Array.isArray(resposta.data)) {
                const mapped = resposta.data.map((coleta, idx) => ({
                    id: coleta.nR_Coleta,
                    id_row: `${coleta.nR_Coleta}_${idx + 1}`,
                    data: coleta.dT_Solicitacao_Coleta,
                    motivo: motivosMap[coleta.cD_Motivo_Coleta] || coleta.cD_Motivo_Coleta,
                    loja: coleta.cD_Filial,
                    cliente: coleta.cgC_CPF_Cliente,
                    cd_Empresa: coleta.cD_Empresa,
                    cd_Filial: coleta.cD_Filial,
                    cGC_CPF_Cliente: coleta.cGC_CPF_Cliente,
                    nomeCarreteiro: coleta.razao_Social,
                    status:
                        coleta.sT_Coleta === "NÃO INICIADA"
                            ? "PENDENTE DE APROVAÇÃO"
                            : coleta.sT_Coleta === "ENCERRADA"
                                ? "APROVADA"
                                : coleta.sT_Coleta === "CANCELADA"
                                    ? "NÃO APROVADA/ CANCELADA"
                                    : coleta.sT_Coleta || "-",
                    observacao: coleta.observacao,
                    origem: coleta.origem,
                    destino: coleta.destino,
                    vr_frete: coleta.vR_Frete,

                    uF_Origem: coleta.uF_Origem,
                    cidade_Origem: coleta.cidade_Origem,
                    bairro_Origem: coleta.bairro_Origem,
                    endereco_Coleta_Origem: coleta.endereco_Coleta_Origem,
                    nR_Endereco_Origem: coleta.nR_Endereco_Origem,

                    uF_Destinatario: coleta.uF_Destinatario,
                    cidade_Destinatario: coleta.cidade_Destinatario,
                    bairro_Destinatario: coleta.bairro_Destinatario,
                    endereco_Destinatario: coleta.endereco_Destinatario,
                    nR_Endereco_Destinatario: coleta.nR_Endereco_Destinatario
                }));
                setColetas(mapped);
            } else {
                setColetas([]);
            }
        } catch (err) {
            setError("Erro ao buscar coletas: " + err.message);
            setColetas([]);
        }
        setLoading(false);
    };

    useEffect(() => {
        fetchColetas();
    }, []);

    const mapColetaToApi = (coleta) => ({
        cgC_CPF_Solicitante: coleta.cgC_CPF_Solicitante || '',
        cD_Empresa: coleta.cD_Empresa || '',
        cD_Filial: coleta.loja || coleta.cD_Filial || '',
        nR_Coleta: coleta.id || coleta.nR_Coleta || '',
        cgC_CPF_Cliente: coleta.cliente || coleta.cgC_CPF_Cliente || '',
        sT_Coleta: coleta.sT_Coleta || coleta.status || '',
        cgC_CPF_Transportadora: coleta.cgC_CPF_Transportadora || '',
        dT_Solicitacao_Coleta: coleta.data || coleta.dT_Solicitacao_Coleta || '',
        tP_Status_Coleta: coleta.tP_Status_Coleta || '',
        dT_Atualizacao: coleta.dT_Atualizacao && !isNaN(Date.parse(coleta.dT_Atualizacao))
            ? new Date(coleta.dT_Atualizacao).toISOString()
            : new Date().toISOString(),
        razao_Social: coleta.nomeCarreteiro || coleta.razao_Social || '',
        cnpj: coleta.cnpj || '',
        iD_Carreteiro: coleta.iD_Carreteiro || 0
    });

    const aprovarColeta = async (id_row) => {
        const confirmed = await confirmMessage('Confirma a aprovação da coleta?');
        if (!confirmed.isConfirmed) return;

        const coleta = coletas.find(c => c.id_row === id_row);
        if (!coleta) return;
        const coletaApi = mapColetaToApi(coleta);
        try {
            const resultado = await EmbarcadorrServico.AprovarColeta(coletaApi);
            if (resultado && resultado.sucesso) {
                setColetas(prev =>
                    prev.map(c =>
                        c.id_row === id_row ? { ...c, status: "Aprovado" } : c
                    )
                );
                successMessage(resultado.mensagem || "Coleta aprovada com sucesso!");
            } else {
                errorMessage(resultado?.mensagem || "Erro ao aprovar coleta.");
            }
        } catch (err) {
            errorMessage(err.message || "Erro ao aprovar coleta.");
        }
    };

    const reprovarColeta = async (id_row) => {
        const confirmed = await confirmMessage('Confirma a reprovação da coleta?');
        if (!confirmed.isConfirmed) return;

        const coleta = coletas.find(c => c.id_row === id_row);
        if (!coleta) return;
        const coletaApi = mapColetaToApi(coleta);
        try {
            const resultado = await EmbarcadorrServico.ReprovarColeta(coletaApi);
            if (resultado && resultado.sucesso) {
                setColetas(prev =>
                    prev.map(c =>
                        c.id_row === id_row ? { ...c, status: "Reprovado" } : c
                    )
                );
                successMessage(resultado.mensagem || "Coleta reprovada com sucesso!");
            } else {
                errorMessage(resultado?.mensagem || "Erro ao reprovar coleta.");
            }
        } catch (err) {
            errorMessage(err.message || "Erro ao reprovar coleta.");
        }
    };

    const openModal = (coleta) => {
        setSelectedColeta(coleta);
        setModalOpen(true);
    };

    const closeModal = () => {
        setSelectedColeta(null);
        setModalOpen(false);
    };

    return (
        <div className="p-4">
            <h2 className="text-xl font-bold mb-4">Coletas Pendentes</h2>

            {/* Filtros */}
            <div className="flex gap-4 mb-4 items-end">
                <div>
                    <label className="block text-sm">Início</label>
                    <input
                        type="text"
                        value={filtroInicio}
                        onChange={(e) => setFiltroInicio(e.target.value)}
                        className="border px-2 py-1 rounded"
                        placeholder="dd/MM/yyyy"
                        pattern="\d{2}/\d{2}/\d{4}"
                    />
                </div>
                <div>
                    <label className="block text-sm">Fim</label>
                    <input
                        type="text"
                        value={filtroFim}
                        onChange={(e) => setFiltroFim(e.target.value)}
                        className="border px-2 py-1 rounded"
                        placeholder="dd/MM/yyyy"
                        pattern="\d{2}/\d{2}/\d{4}"
                    />
                </div>
                {/* <div>
          <label className="block text-sm">Motivo</label>
          <select
            value={filtroMotivo}
            onChange={(e) => setFiltroMotivo(e.target.value)}
            className="border px-2 py-1 rounded"
          >
            <option value="">Todos</option>
            <option value="Devolução">Devolução</option>
            <option value="Reentrega">Reentrega</option>
            <option value="Entrega">Entrega</option>
            <option value="Coleta">Coleta</option>
          </select>
        </div> */}
                <div>
                    <label className="block text-sm">Status</label>
                    <select
                        value={filtroStatus}
                        onChange={(e) => setFiltroStatus(e.target.value)}
                        className="border px-2 py-1 rounded"
                    >
                        {/* <option value="TODOS">Todos</option> */}
                        <option value="NÃO INICIADA">Pendente</option>
                        {/* <option value="ENCERRADA">Aprovado</option> */}
                        {/* <option value="CANCELADA">Reprovado</option> */}
                    </select>
                </div>
                <button
                    className="bg-green-600 text-white px-4 py-2 rounded ml-4 hover:bg-green-700"
                    onClick={fetchColetas}
                    disabled={loading || !isValidDate(filtroInicio) || !isValidDate(filtroFim)}
                >
                    {loading ? "Pesquisando..." : "Pesquisar"}
                </button>
                {(!isValidDate(filtroInicio) || !isValidDate(filtroFim)) && (
                    <span className="text-red-600 text-sm ml-2">Preencha as datas corretamente (dd/MM/yyyy, ano com 4 dígitos)</span>
                )}
                <div className="ml-6 flex items-center">
                    <span className="text-sm font-semibold text-green-700 bg-green-100 px-3 py-1 rounded">
                        Pendentes: {coletas.filter(c => c.status === "PENDENTE DE APROVAÇÃO").length}
                    </span>
                </div>
            </div>

            {/* Tabela ou mensagens de loading/erro */}
            {loading ? (
                <div className="text-center py-8 text-green-600 font-semibold">Carregando coletas...</div>
            ) : error ? (
                <div className="text-center py-8 text-red-600 font-semibold">{error}</div>
            ) : coletas.length === 0 ? (
                <div className="text-center py-8 text-gray-600 font-semibold">Não há registros de coletas.</div>
            ) : (
                <table className="min-w-full bg-white border">
                    <thead>
                        <tr className="bg-gray-100">
                            <th className="border px-4 py-2">Nº Coleta</th>
                            <th className="border px-4 py-2">Data</th>
                            <th className="border px-4 py-2">Motivo</th>
                            <th className="border px-4 py-2">Loja</th>
                            <th className="border px-4 py-2">Remetente</th>
                            <th className="border px-4 py-2">Carreteiro</th>
                            <th className="border px-4 py-2">Status</th>
                            <th className="border px-4 py-2">Ação</th>

                        </tr>
                    </thead>
                    <tbody>
                        {coletas.map((coleta) => (
                            <tr key={coleta.id_row}>
                                <td className="border px-4 py-2">{String(coleta.id).padStart(6, "0")}</td>
                                <td className="border px-4 py-2">{formatDate(coleta.data)}</td>
                                <td className="border px-4 py-2">{coleta.motivo}</td>
                                <td className="border px-4 py-2">{coleta.loja}</td>
                                <td className="border px-4 py-2">{coleta.cliente}</td>
                                <td className="border px-4 py-2">{coleta.nomeCarreteiro}</td>
                                <td className="border px-4 py-2">
                                    <span
                                        className={`text-sm font-semibold ${coleta.status === "PENDENTE DE APROVAÇÃO"
                                            ? "text-red-600"
                                            : "text-gray-600"
                                            }`}
                                    >
                                        {coleta.status}
                                    </span>
                                </td>
                                <td className="border px-4 py-2 text-center space-x-2">
                                    {coleta.status === "PENDENTE DE APROVAÇÃO" && (
                                        <>
                                            <button
                                                onClick={() => aprovarColeta(coleta.id_row)}
                                                title="Aprovar"
                                                className="text-green-600 hover:text-green-800"
                                            >
                                                <FaCheckCircle size={16} />
                                            </button>
                                            <button
                                                onClick={() => reprovarColeta(coleta.id_row)}
                                                title="Reprovar"
                                                className="text-red-600 hover:text-red-800"
                                            >
                                                <FaTimesCircle size={16} />
                                            </button>


                                            <button
                                                onClick={() => openModal(coleta)}
                                                title="Detalhes"
                                                className="text-blue-600 hover:text-blue-800"
                                            >
                                                <FaPen size={16} />
                                            </button>

                                        </>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
            {/* Modal */}
            {/* <Modal isOpen={modalOpen} onClose={closeModal}  /> */}
            <Modal isOpen={modalOpen} onClose={closeModal} coleta={selectedColeta} fetchColetas={fetchColetas} />
        </div>
    );
}
