import React, { useState, useEffect } from 'react';
import {
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
} from 'recharts';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import { TransportadorServico } from '../../services/TransportadorServico';
import { EmbarcadorrServico } from '../../services/EmbarcadorServico';

export default function Lojas() {
    const [dataInicio, setDataInicio] = useState('');
    const [dataFim, setDataFim] = useState('');
    const [cabecalhoFiltro, setCabecalhoFiltro] = useState('');
    const [lojaSelecionadaMargem, setLojaSelecionadaMargem] = useState(null);
    const [dadosMargemPorLoja, setDadosMargemPorLoja] = useState([]);
    const [dadosGraficoPorMes, setDadosGraficoPorMes] = useState([]);
    const [loading, setLoading] = useState(false);
    const [regiaoExpandida, setRegiaoExpandida] = useState(null);
    const [linhaExpandida, setLinhaExpandida] = useState(null);
    const [detalhesPainel, setDetalhesPainel] = useState({});
    const [loadingPainel, setLoadingPainel] = useState(false);

    const buscarDespesasFretes = async () => {
        if (!dataInicio || !dataFim) return;
        setLoading(true);
        try {
            const res = await EmbarcadorrServico.BuscarDespesasFretesRegiao({
                dataInicio,
                dataFim,
                cabecalhos: cabecalhoFiltro
            });

            if (!res?.sucesso) {
                console.error('Erro ao buscar despesas de fretes:', res.mensagem);
                return;
            }

            setDadosMargemPorLoja(
                Array.isArray(res.data)
                    ? res.data.map(item => ({
                        codigoRegiao: item.cD_Divisao_Regiao,
                        nomeRegiao: item.nome_Regiao,
                        cabecalho: String(item.cD_Cabecalho),
                        pesoTotal: item.vR_Peso_Total,
                        receitaTotal: item.vR_Receita,
                        totalNotas: item.qT_Total_NF,
                        valorPago: item.vR_Frete_Transportador,
                        valorPagoCarreteiro: item.vR_Frete_Carreteiro_Coleta,
                        valorTotalPago: item.total_VR_Frete,
                        valorCobrado: item.vR_Frete_Loja,
                        diferenca: item.vR_Diferenca,
                        percentual: item.vR_Diferenca_Porc
                    }))
                    : []
            );
        } finally {
            setLoading(false);
        }
    };

    const buscarFretePorMes = async () => {
        if (!dataInicio || !dataFim) return;
        setLoading(true);

        try {
            const res = await EmbarcadorrServico.BuscarDespesasFretesTodasLojas({
                dataInicio,
                dataFim,
                cabecalhos: cabecalhoFiltro
            });
            setDadosGraficoPorMes(
                Array.isArray(res.data)
                    ? res.data.map(item => ({
                        mesAno: `${item.mes.toString().padStart(2, '0')}/${item.ano}`,
                        freteLoja: item.vR_Frete_Loja,
                        freteTransportador: item.vR_Frete_Transportador,
                        diferenca: item.vR_Diferenca_Frete_Loja_Transportador,
                        percentual: item.vR_Diferenca_Porc
                    }))
                    : []
            );
        } catch (err) {
            setDadosGraficoPorMes([]);
        }
        finally {
            setLoading(false);
        }
    };

    const buscarTudo = async () => {
        setLinhaExpandida(null);
        setDetalhesPainel({});
        setLoadingPainel(false);
        await buscarDespesasFretes();
        // await buscarFretePorMes();
    };

    // Remova o useEffect ou deixe apenas para carregar inicial
    useEffect(() => {
        // Se quiser carregar automático ao abrir, descomente:
        // buscarDespesasFretes();
    }, []);

    const dadosFiltrados = dadosMargemPorLoja;

    const exportarExcel = () => {
        const worksheet = XLSX.utils.json_to_sheet(dadosFiltrados.map(item => ({
            'Código Loja': item.codigoLoja,
            'Nome Loja': item.nomeLoja,
            'Cabeçalho': item.cabecalho,
            'Peso Total': item.pesoTotal,
            'Receita': item.receitaTotal,
            'Total de Notas': item.totalNotas,
            'Frete Transportador': item.valorTotalPago,
            'Frete Loja': item.valorCobrado,
            'Diferença': item.diferenca,
            '%': item.percentual
        })));

        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Margem por Loja');
        const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
        saveAs(new Blob([excelBuffer], { type: 'application/octet-stream' }), 'margem_por_loja.xlsx');
    };

    // Agrupa e soma o valor do frete da loja por loja
    const dadosGraficoFreteLoja = Object.values(
        dadosMargemPorLoja.reduce((acc, item) => {
            if (!acc[item.codigoRegiao]) {
                acc[item.codigoRegiao] = {
                    codigoRegiao: item.codigoRegiao,
                    nomeRegiao: item.nomeRegiao,
                    valorCobradoTotal: 0
                };
            }
            acc[item.codigoRegiao].valorCobradoTotal += Number(item.valorCobrado) || 0;
            return acc;
        }, {})
    );

    return (
        <div className="p-4 space-y-4">
            {/* Filtros */}
            <div className="flex flex-wrap gap-4 mb-4">
                <div>
                    <label className="block text-sm">Início</label>
                    <input
                        type="date"
                        value={dataInicio}
                        onChange={(e) => setDataInicio(e.target.value)}
                        className="border px-2 py-1 rounded"
                    />
                </div>
                <div>
                    <label className="block text-sm">Fim</label>
                    <input
                        type="date"
                        value={dataFim}
                        onChange={(e) => setDataFim(e.target.value)}
                        className="border px-2 py-1 rounded"
                    />
                </div>
                <div>
                    <label className="block text-sm">Cabeçalho (vários separados por vírgula)</label>
                    <input
                        type="text"
                        value={cabecalhoFiltro}
                        onChange={(e) => setCabecalhoFiltro(e.target.value)}
                        placeholder="Ex: 01, 22, 105"
                        className="border px-2 py-1 rounded w-48"
                    />
                </div>
                <div className="flex items-end">
                    <button
                        onClick={buscarTudo}
                        className="bg-blue-600 text-white px-4 py-1 rounded hover:bg-blue-700 mr-2"
                    >
                        Pesquisar
                    </button>
                    <button
                        onClick={exportarExcel}
                        className="bg-green-600 text-white px-4 py-1 rounded hover:bg-green-700"
                    >
                        Exportar Excel
                    </button>
                </div>
            </div>

            {/* Tabela */}
            <div className="bg-white p-4 rounded shadow">
                <h2 className="text-xl font-semibold mb-4">Margem por Região (Período Selecionado)</h2>
                {loading ? (
                    <div className="text-center py-8 text-green-600 font-semibold">Carregando...</div>
                ) : (
                    <div className="overflow-auto max-h-96">
                        <table className="w-full text-left border-collapse text-sm">
                            <thead>
                                <tr>
                                    <th className="p-2">Código Região</th>
                                    <th className="p-2">Nome Região</th>
                                    <th className="p-2">Cabeçalho</th>
                                    <th className="p-2">Peso Total</th>
                                    <th className="p-2">Receita</th>
                                    <th className="p-2">Total de Notas</th>
                                    <th className="p-2">Frete Total</th>
                                    <th className="p-2">Frete Transportador</th>
                                    <th className="p-2">Frete Carreteiro</th>
                                    <th className="p-2">Frete Loja</th>
                                    <th className="p-2">Diferença</th>
                                    <th className="p-2">%</th>
                                </tr>
                            </thead>
                            <tbody>
                                {dadosMargemPorLoja.map((item) => {
                                    const key = item.codigoRegiao + '-' + item.cabecalho;
                                    return (
                                        <React.Fragment key={key}>
                                            <tr
                                                className={`cursor-pointer hover:bg-green-100 ${linhaExpandida === key ? 'bg-green-200 font-bold' : ''}`}
                                                onClick={async () => {
                                                    const key = item.codigoRegiao + '-' + item.cabecalho;
                                                    if (linhaExpandida === key) {
                                                        setLinhaExpandida(null);
                                                        return;
                                                    }
                                                    setLinhaExpandida(key);
                                                    setLoadingPainel(true);
                                                    setDetalhesPainel({}); // Limpa antes de buscar

                                                    // Pegue o token do localStorage ou contexto de autenticação
                                                    const token = localStorage.getItem('token'); // ajuste conforme seu projeto

                                                    const res = await EmbarcadorrServico.BuscarDespesasFreteDetalhes({
                                                        dataInicio,
                                                        dataFim,
                                                        cabecalhos: item.cabecalho,
                                                        regiao: item.codigoRegiao,
                                                        token,
                                                    });

                                                    if (res.sucesso && Array.isArray(res.data) && res.data.length > 0) {
                                                        setDetalhesPainel({ [key]: res.data[0] });
                                                    } else {
                                                        setDetalhesPainel({ [key]: null });
                                                    }
                                                    setLoadingPainel(false);
                                                }}
                                            >
                                                <td className="p-2">{item.codigoRegiao}</td>
                                                <td className="p-2">{item.nomeRegiao}</td>
                                                <td className="p-2">{item.cabecalho}</td>
                                                <td className="p-2">{item.pesoTotal} kg</td>
                                                <td className="p-2">R$ {Number(item.receitaTotal).toFixed(2)}</td>
                                                <td className="p-2">{item.totalNotas}</td>
                                                <td className="p-2">R$ {Number(item.valorTotalPago).toFixed(2)}</td>

                                                <td className="p-2">R$ {Number(item.valorPago).toFixed(2)}</td>
                                                <td className="p-2">R$ {Number(item.valorPagoCarreteiro).toFixed(2)}</td>


                                                <td className="p-2">R$ {Number(item.valorCobrado).toFixed(2)}</td>
                                                <td className={`p-2 ${item.diferenca >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                                                    {item.diferenca >= 0 ? '▲' : '▼'} R$ {Number(item.diferenca).toFixed(2)}
                                                </td>
                                                <td className={`p-2 ${item.percentual >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                                                    {item.percentual}%
                                                </td>
                                            </tr>
                                            {linhaExpandida === key && (
                                                <tr>
                                                    <td colSpan={12} className="bg-green-50 p-4">
                                                        <div>
                                                            <div className="font-semibold mb-2">
                                                                Performance Financeira — {item.nomeRegiao} / Cabeçalho {item.cabecalho}
                                                            </div>
                                                            {loadingPainel ? (
                                                                <div className="text-green-600 font-bold">Carregando detalhes...</div>
                                                            ) : (
                                                                <div className="grid grid-cols-4 gap-4">
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Entregas:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.entregas_Nf_VR) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Reentregas:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.reentregas_Nf_VR) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Devoluções:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.devolucoes_Nf_VR) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Transferências / REAB:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.transferencias_Nf_VR) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Pedágio:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.pedagio) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">KM Excedente:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.kM_Excedente) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Ajudante Extra:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.ajudante_Extra) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Coletas Carreteiros:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.vR_Coletas_Carreteiros) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">Coletas Transportadoras:</div>
                                                                        <div className="font-bold">
                                                                            R$ {Number((detalhesPainel[key]?.vR_Coletas_Transportadoras) || 0).toFixed(2)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">CT-es Emitidos (Qtd):</div>
                                                                        <div className="font-bold">
                                                                            {Number((detalhesPainel[key]?.qTd_CTe_Emitidos) || 0)}
                                                                        </div>
                                                                    </div>
                                                                    <div className="bg-white rounded shadow p-3">
                                                                        <div className="text-xs text-gray-500">CT-es Pendentes (Qtd):</div>
                                                                        <div className="font-bold">
                                                                            {Number((detalhesPainel[key]?.qTd_CTe_Pendentes) || 0)}
                                                                        </div>
                                                                    </div>
                                                                </div>
                                                            )}
                                                        </div>
                                                    </td>
                                                </tr>
                                            )}
                                        </React.Fragment>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Gráfico por regiao */}
            <div className="bg-white p-4 rounded shadow h-[400px] flex flex-col">
                <h2 className="font-bold mb-2">Valor Frete Por Região (Gráfico de Barras)</h2>
                <div style={{ width: '100%', height: '100%', overflowX: 'auto' }}>
                    <ResponsiveContainer width={Math.max(600, dadosGraficoFreteLoja.length * 80)} height={350}>
                        <BarChart
                            data={dadosGraficoFreteLoja}
                            margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                        >
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis
                                dataKey="nomeRegiao"
                                interval={0}
                                angle={0}
                                tick={{ fontSize: 14 }}
                                tickLine={false}
                            />
                            <YAxis />
                            <Tooltip formatter={(value) => `R$ ${Number(value).toFixed(2)}`} />
                            <Bar dataKey="valorCobradoTotal" fill="#007bff" name="Frete Loja Total" />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            {/* Gráfico por mês */}
            <div className="bg-white p-4 rounded shadow h-[400px] flex flex-col">
                <h2 className="font-bold mb-2">Valor Frete Por Mês (Gráfico de Barras)</h2>
                <ResponsiveContainer width="100%" height={350}>
                    <BarChart
                        data={dadosGraficoPorMes}
                        margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                    >
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="mesAno" />
                        <YAxis />
                        <Tooltip formatter={(value) => `R$ ${Number(value).toFixed(2)}`} />
                        <Bar dataKey="freteLoja" fill="#007bff" name="Frete Loja" />
                        <Bar dataKey="freteTransportador" fill="#28a745" name="Frete Transportador" />
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>
    );
}
