// src/pages/Faturas.js
import React, { useState, useEffect, useRef } from 'react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { TransportadorServico } from '../../services/TransportadorServico';

export default function Faturas({ user }) {
    const tableRef = useRef();
    const [expandedFatura, setExpandedFatura] = useState(null);
    const [faturas, setFaturas] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    const buscarFaturasAPI = async () => {
        try {
            setLoading(true);
            setError('');

            // Get CNPJ from user data
            const cnpj = user?.cnpj || user?.CNPJ;

            if (!cnpj) {
                setError('CNPJ do usuário não encontrado');
                setLoading(false);
                return;
            }


            const resposta = await TransportadorServico.BuscarFaturas({ cnpj });

            if (resposta?.sucesso) {
                let results = [];

                if (resposta.data?.results) {
                    results = resposta.data.results;
                } else if (resposta.results) {
                    results = resposta.results;
                } else if (Array.isArray(resposta.data)) {
                    results = resposta.data;
                }

                const faturasFormatadas = results.map(fatura => ({
                    id: fatura._NR_Fatura,
                    dtEmissao: formatarData(fatura._DT_Emissao),
                    vrFrete: fatura._VR_Frete || 0,
                    status: fatura._Status,
                    ctes: [],
                    cD_Filial: fatura._CD_Filial || fatura.cD_Filial || '' // Adiciona filial
                }));

                setFaturas(faturasFormatadas);
            } else {
                setError(resposta?.mensagem || resposta?.erros || 'Erro ao buscar faturas');
                console.error('Erro na resposta:', resposta);
            }

        } catch (error) {
            console.error('Erro ao buscar faturas:', error);
            setError('Erro ao carregar faturas: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const formatarData = (dataISO) => {
        if (!dataISO) return '';

        try {
            const data = new Date(dataISO);
            return data.toLocaleDateString('pt-BR');
        } catch (error) {
            console.error('Erro ao formatar data:', error);
            return dataISO;
        }
    };

    useEffect(() => {
        if (user) {
            buscarFaturasAPI();
        }
    }, [user]);

    const toggleExpand = async (faturaId) => {
        if (expandedFatura === faturaId) {
            setExpandedFatura(null);
            return;
        }
        setExpandedFatura(faturaId);

        const fatura = faturas.find(f => f.id === faturaId);
        if (!fatura) return;

        const filtros = {
            CNPJ: user?.cnpj || user?.CNPJ,
            CD_Filial: fatura.cD_Filial || fatura.loja || '',
            NR_Fatura: fatura.id
        };

        const resposta = await TransportadorServico.BuscarConhecimento_Fatura({ filtros });
        if (resposta?.sucesso && Array.isArray(resposta.data)) {
            const ctes = resposta.data.map(cte => ({
                //id: cte.chave_CTe || cte.nR_CTRC_Controle || '',
                id: cte.nR_CTRC_Impresso,
                dtEmissao: cte.dT_Emissao ? formatarData(cte.dT_Emissao) : '',
                vrFrete: cte.vR_Frete_Valor || 0,
                situacao: cte.situacao_CTe || '',
                serie: cte.nR_CTRC_Serie || '',
                filial: cte.cD_Filial || '',
            }));
            setFaturas(prev =>
                prev.map(f =>
                    f.id === faturaId ? { ...f, ctes } : f
                )
            );
        }
    };

    // Loading component
    const LoadingComponent = () => (
        <div className="flex justify-center items-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
            <span className="ml-2 text-gray-600">Carregando faturas...</span>
        </div>
    );

    if (loading) {
        return (
            <main className="flex-1 p-6 bg-gray-100 min-h-screen">
                <h1 className="text-2xl font-bold mb-6 text-center">Faturas</h1>
                <div className="bg-white p-6 rounded shadow mb-6">
                    <LoadingComponent />
                </div>
            </main>
        );
    }

    if (error) {
        return (
            <main className="flex-1 p-6 bg-gray-100 min-h-screen">
                <h1 className="text-2xl font-bold mb-6 text-center">Faturas</h1>
                <div className="bg-white p-6 rounded shadow mb-6 text-center">
                    <p className="text-red-600 mb-4">{error}</p>
                    <button
                        onClick={buscarFaturasAPI}
                        className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
                    >
                        Tentar Novamente
                    </button>
                </div>
            </main>
        );
    }

    // const exportPDF = async () => {
    //   const input = tableRef.current;
    //   if (!input) return;
    //   // Add white background before rendering
    //   const canvas = await html2canvas(input, {
    //     backgroundColor: '#fff',
    //     scale: 2 // better font rendering
    //   });
    //   const imgData = canvas.toDataURL('image/png');
    //   const pdf = new jsPDF({ orientation: 'portrait' });
    //   const pageWidth = pdf.internal.pageSize.getWidth();
    //   const pageHeight = pdf.internal.pageSize.getHeight();
    //   const margin = 20; // 2cm in jsPDF units (approx 20)
    //   const imgWidth = pageWidth - margin * 2;
    //   const imgHeight = (canvas.height * imgWidth) / canvas.width;
    //   // Add title
    //   pdf.setFontSize(18);
    //   pdf.text('Faturas', pageWidth / 2, margin, { align: 'center' });
    //   // Add image below title with margins
    //   pdf.addImage(imgData, 'PNG', margin, margin + 10, imgWidth, imgHeight);
    //   pdf.save('faturas.pdf');
    // };

    const baixarFaturaPDF = async (e, fatura) => {
        // evita abrir/fechar o expand da linha
        e.stopPropagation();

        const cgcFilial = user?.login;
        const numeroFatura = fatura?.id;

        if (!cgcFilial || !numeroFatura) {
            console.error("Parâmetros inválidos para baixar PDF:", { cgcFilial, numeroFatura });
            alert("Não foi possível identificar filial ou número da fatura.");
            return;
        }

        try {
            const resp = await TransportadorServico.BaixarFaturaPDF({
                cgcFilial,
                numeroFatura
            });

            if (!resp?.sucesso) {
                throw new Error(resp?.erros || "Falha ao baixar PDF");
            }
        } catch (err) {
            console.error("Erro ao baixar PDF:", err);
            alert("Erro ao baixar o PDF da fatura.");
        }
    };

    return (
        <main className="flex-1 p-6 bg-gray-100 min-h-screen">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold text-center flex-1">Faturas</h1>
                <div className="flex gap-2">
                    <button
                        onClick={buscarFaturasAPI}
                        className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 text-sm"
                    >
                        Atualizar
                    </button>
                </div>
            </div>

            {faturas.length === 0 ? (
                <div className="bg-white p-6 rounded shadow mb-6 text-center">
                    <p className="text-gray-500">Nenhuma fatura encontrada.</p>
                </div>
            ) : (
                <div className="bg-white p-6 rounded shadow mb-6 overflow-auto" ref={tableRef}>
                    <table className="w-full text-left border-collapse text-sm">
                        <thead>
                            <tr className="border-b border-gray-300">
                                <th className="p-3">DT Emissão</th>
                                <th className="p-3">NR Fatura</th>
                                <th className="p-3">VR Frete</th>
                                <th className="p-3">Status</th>
                                <th className="p-3 text-center">Ações</th>
                            </tr>
                        </thead>
                        <tbody>
                            {faturas.map((fatura) => (
                                <React.Fragment key={fatura.id}>
                                    <tr
                                        onClick={() => toggleExpand(fatura.id)}
                                        className="cursor-pointer hover:bg-green-50 border-b border-gray-100"
                                    >
                                        <td className="p-3">{fatura.dtEmissao}</td>
                                        <td className="p-3 font-mono">{fatura.id}</td>
                                        <td className="p-3">
                                            R$ {fatura.vrFrete.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                        </td>
                                        <td
                                            className={`p-3 font-bold ${fatura.status === 'Pendente' ? 'text-red-600' : 'text-green-600'
                                                }`}
                                        >
                                            {fatura.status}
                                        </td>

                                        {/* NOVO: coluna de ações */}
                                        <td className="p-3 text-center">
                                            <button
                                                onClick={(e) => baixarFaturaPDF(e, fatura)}
                                                className="inline-flex items-center justify-center rounded px-2 py-1 bg-red-50 hover:bg-red-100 border border-red-200 text-red-700 text-xs"
                                                title="Baixar fatura em PDF"
                                            >
                                                {/* Ícone PDF simples (inline SVG) */}
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                                                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6zM13 3.5L18.5 9H13V3.5zM8.75 14.5H8v2H7v-5h1.75a1.75 1.75 0 0 1 0 3.5zm0-2.5H8v1.5h.75a.75.75 0 0 0 0-1.5zM12 16.5h-1v-5h2a1.5 1.5 0 1 1 0 3H12v2zm1-3a.5.5 0 0 0 0-1h-1v1h1zm4 .5h-1.25v2H14.5v-5h2.5a1.25 1.25 0 0 1 0 2.5zM17 12.75a.25.25 0 0 0 0-.5h-1.25v.5H17z" />
                                                </svg>
                                                PDF
                                            </button>
                                        </td>
                                    </tr>

                                    {expandedFatura === fatura.id && (
                                        <tr className="bg-gray-50">
                                            {/* ATENÇÃO: colSpan atualizado de 4 para 5 */}
                                            <td colSpan={5} className="p-3">
                                                {fatura.ctes && fatura.ctes.length > 0 ? (
                                                    <div style={{ maxHeight: 300, overflowY: 'auto' }}>
                                                        <table className="w-full text-left text-xs">
                                                            <thead>
                                                                <tr className="border-b border-gray-300">
                                                                    <th className="p-2">DT Emissão</th>
                                                                    <th className="p-2">NR CTE</th>
                                                                    <th className="p-2">VR Frete</th>
                                                                    {/* <th className="p-2">Situação</th> */}
                                                                    <th className="p-2">Série</th>
                                                                    <th className="p-2">Filial</th>
                                                                </tr>
                                                            </thead>
                                                            <tbody>
                                                                {fatura.ctes.map((cte, idx) => (
                                                                    <tr key={cte.id + idx} className="hover:bg-green-100">
                                                                        <td className="p-2">{cte.dtEmissao}</td>
                                                                        <td className="p-2 font-mono">{cte.id}</td>
                                                                        <td className="p-2">R$ {Number(cte.vrFrete).toFixed(2)}</td>
                                                                        {/* <td className="p-2">{cte.situacao}</td> */}
                                                                        <td className="p-2">{cte.serie}</td>
                                                                        <td className="p-2">{cte.filial}</td>
                                                                    </tr>
                                                                ))}
                                                            </tbody>
                                                        </table>
                                                    </div>
                                                ) : (
                                                    <div className="text-center text-gray-500 py-4">
                                                        <p>Detalhes dos CTes não disponíveis</p>
                                                    </div>
                                                )}
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            <div className="bg-white p-4 rounded shadow text-center">
                <p className="text-sm text-gray-600">
                    Total de faturas: <span className="font-bold">{faturas.length}</span>
                </p>
            </div>
        </main>
    );
}
