import React, { useState, useEffect } from 'react';
import { FiTruck } from 'react-icons/fi';
import { PieChart, Pie, Cell, Tooltip, Legend } from 'recharts';
import { EmbarcadorrServico } from '../../services/EmbarcadorServico';
import debounce from 'lodash.debounce'; // Adicione lodash.debounce ao seu projeto

const COLORS = ['#e74c3c', '#3498db', '#2ecc71'];

function formatDateToBR(dateStr) {
  if (!dateStr) return '';
  const [year, month, day] = dateStr.split('-');
  return `${day}/${month}/${year}`;
}

function formatDateToISO(dateStr) {
  if (!dateStr) return '';
  const [day, month, year] = dateStr.split('/');
  return `${year}-${month}-${day}`;
}

export default function PosicaoFrotas() {
  const [periodo, setPeriodo] = useState({ inicio: '', fim: '' });
  const [rotas, setRotas] = useState([]);
  const [notas, setNotas] = useState([]);
  const [selectedViagem, setSelectedViagem] = useState(null);
  const [loadingRotas, setLoadingRotas] = useState(false);
  const [isPeriodoValido, setIsPeriodoValido] = useState(false);

  // Valida o período sempre que ele for atualizado
  useEffect(() => {
    const isValid =
      periodo.inicio &&
      periodo.fim &&
      new Date(formatDateToISO(periodo.inicio)) <= new Date(formatDateToISO(periodo.fim));
    setIsPeriodoValido(isValid);
  }, [periodo]);

  // Função para buscar rotas
  const buscarRotas = async () => {
    if (!isPeriodoValido) {
      alert('Por favor, insira um período válido.');
      return;
    }

    setLoadingRotas(true);
    setNotas([]);
    setSelectedViagem(null);

    try {
      const res = await EmbarcadorrServico.BuscarPosicaoEntrega({
        dataInicio: periodo.inicio,
        dataFim: periodo.fim,
      });

      if (res.sucesso && Array.isArray(res.data)) {
        setRotas(res.data);
      } else {
        setRotas([]);
      }
    } catch (error) {
      console.error('Erro ao buscar rotas:', error);
      setRotas([]);
    } finally {
      setLoadingRotas(false);
    }
  };

  // Atualiza o período com debounce para evitar re-renderizações excessivas
  const handlePeriodoChange = debounce((campo, valor) => {
    const formattedValue = formatDateToBR(valor);
    setPeriodo((prev) => ({ ...prev, [campo]: formattedValue }));
  }, 300);

  // Função para lidar com a seleção de uma viagem
  const handleSelecionaViagem = (rota) => {
    setSelectedViagem(rota.numero_viagem);
    setNotas(Array.isArray(rota.notas_fiscais) ? rota.notas_fiscais : []);
  };

  const statusColor = {
    'Não Iniciado': 'text-red-600',
    'Em Andamento': 'text-blue-600',
    'Encerrado': 'text-green-800',
    'Ocorrencia': 'text-red-700',
  };

  const TRUCK_COLORS = {
    low: '#e74c3c', // 0–33%
    mid: '#f1c40f', // 34–99%
    high: '#2ecc71', // 100%
  };

  const getTruckColor = (r) => {
    if (r.perc_entregue === '100') return TRUCK_COLORS.high;
    if (r.perc_entregue >= '33,33') return TRUCK_COLORS.mid;
    return TRUCK_COLORS.low;
    };

    // Quantidade total de notas entregues (status "Entregue") em todas as rotas
    const totalNotasEntregues = rotas.reduce((acc, rota) => {
        if (Array.isArray(rota.notas_fiscais)) {
            return acc + rota.notas_fiscais.filter(n => n.status_nota_fiscal === 'Entregue').length;
        }
        return acc;
    }, 0);

    // Quantidade total de notas "A Entregar" em todas as rotas
    const totalNotasAEntregar = rotas.reduce((acc, rota) => {
        if (Array.isArray(rota.notas_fiscais)) {
            return acc + rota.notas_fiscais.filter(n => n.status_nota_fiscal === 'A Entregar').length;
        }
        return acc;
    }, 0);

    // Quantidade total de notas com ocorrência em todas as rotas
    const totalNotasOcorrencia = rotas.reduce((acc, rota) => {
        if (Array.isArray(rota.notas_fiscais)) {
            return acc + rota.notas_fiscais.filter(n => n.ocorrencia && n.ocorrencia == 'Ocorrência').length;
        }
        return acc;
    }, 0);

  // Dados para o gráfico de pizza
    const pieTotals = [
        { name: 'Encerrado', value: totalNotasEntregues },
        { name: 'A Entregar', value: totalNotasAEntregar },
        { name: 'Ocorrência', value: totalNotasOcorrencia },
    ];

  return (
    <div className="p-4 space-y-6">
      {/* Filtro e botão de pesquisa */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-4">
          <label>Período:</label>
          <input
            type="date"
            className="border rounded px-2 py-1"
            value={formatDateToISO(periodo.inicio)}
            onChange={(e) => handlePeriodoChange('inicio', e.target.value)}
          />
          <span>até</span>
          <input
            type="date"
            className="border rounded px-2 py-1"
            value={formatDateToISO(periodo.fim)}
            onChange={(e) => handlePeriodoChange('fim', e.target.value)}
          />
          <button
            onClick={buscarRotas}
            className={`ml-4 px-4 py-1 rounded ${
              isPeriodoValido ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-gray-400 text-gray-700 cursor-not-allowed'
            }`}
            disabled={!isPeriodoValido}
          >
            Pesquisar
          </button>
        </div>
      </div>

      {/* Card Rotas */}
      <div className="bg-white p-4 rounded shadow">
        <h2 className="font-semibold mb-4">Rotas</h2>
        {loadingRotas ? (
          <div className="text-center py-8 text-green-600 font-semibold">Carregando...</div>
        ) : (
          <div style={{ maxHeight: 400, overflowY: 'auto' }}>
            <table className="w-full text-sm text-left border-collapse">
              <thead className="sticky top-0 bg-white z-20">
                <tr>
                  <th className="p-2">Status</th>
                  <th className="p-2">Rota</th>
                  <th className="p-2">Transportadora</th>
                  <th className="p-2">Viagem</th>
                  <th className="p-2">Data Viagem</th>
                  <th className="p-2">Placa</th>
                  <th className="p-2">Motorista</th>
                  <th className="p-2">Veículo</th>
                  <th className="p-2">Valor Frete</th>
                  <th className="p-2">Entrega</th>
                  <th className="p-2">A Entregar</th>
                  <th className="p-2">Entregue</th>
                  <th className="p-2">%</th>
                </tr>
              </thead>
              <tbody>
                {rotas.map((r) => (
                  <tr
                    key={r.numero_viagem}
                    className={`hover:bg-gray-100 cursor-pointer ${
                      selectedViagem === r.numero_viagem ? 'bg-blue-100 font-bold' : ''
                    }`}
                    onClick={() => handleSelecionaViagem(r)}
                  >
                    <td className="p-2">{r.status_viagem || '-'}</td>
                    <td className="p-2">{r.codigo_rota || ''}</td>
                    <td className="p-2">{r.transportador_nome}</td>
                    <td className="p-2">{r.numero_viagem}</td>
                    <td className="p-2">{r.data_viagem ? r.data_viagem.substring(0, 10) : '-'}</td>
                    <td className="p-2">{r.codigo_placa_veiculo}</td>
                    <td className="p-2">{r.nome_motorista}</td>
                    <td className="p-2">{r.nome_veiculo}</td>
                    <td className="p-2">R$ {Number(r.valor_frete).toFixed(2)}</td>
                    <td className="p-2">{r.data_entrega ? r.data_entrega.substring(0, 10) : '-'}</td>
                    <td className="p-2">{r.a_entregar}</td>
                    <td className="p-2">{r.entregue}</td>
                    <td className="p-2">
                      <FiTruck size={20} color={getTruckColor(r)} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Segunda linha: Notas e Gráfico */}
      <div className="grid grid-cols-[3fr_1.5fr] gap-4">
        {/* Card Notas da Viagem */}
        <div className="bg-white p-4 rounded shadow">
          <h2 className="font-semibold mb-4">
            Notas da Viagem {selectedViagem ?? '…'}
          </h2>
          {selectedViagem && notas.length ? (
            <div style={{ maxHeight: 300, overflowY: 'auto' }}>
              <table className="w-full text-sm text-left border-collapse">
                <thead>
                  <tr className="border-b">
                    <th className="p-2">NF</th>
                    <th className="p-2">Remetente</th>
                    <th className="p-2">Peso</th>
                    <th className="p-2">Valor da Nota</th>
                    <th className="p-2">Loja</th>
                    <th className="p-2">Status</th>
                    <th className="p-2">Ocorrência</th>
                    <th className="p-2">Descrição ocorrência</th>
                  </tr>
                </thead>
                <tbody>
                  {notas.map((n, idx) => (
                    <tr key={n.nota_fiscal + idx} className="hover:bg-gray-100">
                      <td className="p-2">{n.nota_fiscal}</td>
                      <td className="p-2">{n.cnpj_remetente}</td>
                      <td className="p-2">{n.peso_nota_fiscal}</td>
                      <td className="p-2">R$ {Number(n.valor_nota_fiscal).toFixed(2)}</td>
                      <td className="p-2">{n.loja}</td>
                      <td className="p-2">{n.status_nota_fiscal}</td>
                      <td className="p-2">{n.ocorrencia}</td>
                      <td className="p-2">{n.ocorrencia_descricao}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

          ) : (
            <p className="text-gray-500">Selecione uma viagem acima para ver as notas.</p>
          )}
        </div>

        {/* Gráfico */}
        <div className="bg-white p-4 rounded shadow flex flex-col items-center justify-end">
          <h2 className="font-semibold mb-4">Visão Geral de Entregas</h2>
          <PieChart width={290} height={250}>
            <Pie
              data={pieTotals}
              dataKey="value"
              nameKey="name"
              cx="50%"
              cy="50%"
              outerRadius={90}
              label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
            >
              {pieTotals.map((_, idx) => (
                <Cell key={idx} fill={COLORS[idx]} />
              ))}
            </Pie>
            <Tooltip />
            <Legend verticalAlign="bottom" />
          </PieChart>
        </div>
      </div>
    </div>
  );
}
