import React from "react";
import logo from '../assets/logo.png';

export default function OrdemDeColetaPrint({ dados }) {
  const {
    numero,
    dataSolicitacao,
    horaSolicitacao,
    empresa,
    remetente,
    destinatario,
    motorista,
    veiculo,
    placa,
    cnh,
    observacao,
  } = dados;

  return (
    <div className="p-4 max-w-4xl mx-auto text-sm font-sans bg-white text-black">
      <div className="flex items-center justify-between mb-4">
        <img src={logo} alt="Logo" className="h-12" />
        <div className="text-center flex-1">
          <h1 className="text-lg font-bold">Ordem de Coleta</h1>
        </div>
        <div className="text-right">
          <p><strong>Nº</strong> {numero}</p>
          <p><strong>Data Solicitação:</strong> {dataSolicitacao}</p>
          <p><strong>Hora:</strong> {horaSolicitacao}</p>
        </div>
      </div>

      <div className="border p-2 mb-2">
        <p><strong>Empresa:</strong> {empresa?.nome || 'Loja XXXX'}</p>
      </div>

      <div className="border p-2 mb-2">
        <p><strong>Local da Coleta (Remetente):</strong></p>
        <p><strong>Endereço:</strong> {remetente?.endereco}</p>
        <p>
          <strong>Bairro:</strong> {remetente?.bairro} - <strong>Cidade:</strong> {remetente?.cidade} - <strong>UF:</strong> {remetente?.estado}
        </p>
      </div>

      <div className="border p-2 mb-2">
        <p><strong>Local da Entrega (Destinatário):</strong></p>
        <p><strong>Endereço:</strong> {destinatario?.endereco}</p>
        <p>
          <strong>Bairro:</strong> {destinatario?.bairro} - <strong>Cidade:</strong> {destinatario?.municipio} - <strong>UF:</strong> {destinatario?.estado}
        </p>
      </div>

      <div className="border p-2 mb-2">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
          <p><strong>Veículo:</strong> {veiculo}</p>
          <p><strong>Placa:</strong> {placa}</p>
          <p><strong>Motorista:</strong> {motorista}</p>
          <p><strong>C.N.H.:</strong> {cnh}</p>
        </div>
      </div>

      <div className="border p-2 mt-4 text-xs" style={{ minHeight: '120px' }}>
        <div className="flex justify-between">
          <div>
            <p>Efetuada: ________ N.F.: __________</p>
            <p>Veículo: __________ Horário: _______</p>
            <p>Volumes: ____ Peso: ______</p>
          </div>
          <div className="text-right">
            <p>Data: ___/___/_____</p>
            <p>Horas: ____</p>
            <p>Visto Cliente: _____________________</p>
          </div>
        </div>
        <p className="mt-4">Visto Transportador: _____________________</p>
      </div>
    </div>
  );
}
