// src/pages/TransportadorHome.js
import { UtilityPole } from 'lucide-react';
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ConverterArquivosXMLBase64 } from '../../utilities/Utilidades';
import { errorMessage, successMessage, infoMessage } from '../../components/Mensagem';
import { TransportadorServico } from '../../services/TransportadorServico';
import IndexURI from '../../api/index';

export default function TransportadorHome({ user }) {
  const [xmlFiles, setXmlFiles] = useState([]);
  const [ctesImportados, setCtesImportados] = useState([]);
  const [ctesBase64, setCtesBase64] = useState([]);
  const [valoresEsperados, setValoresEsperados] = useState([]);
  const [selectedCTE, setSelectedCTE] = useState(null); // linha selecionada
  const [classesVeiculo, setClassesVeiculo] = useState([]);
  const [selectedClasse, setSelectedClasse] = useState("");

  const navigate = useNavigate();
  const uris = IndexURI();
  const url_classes_veiculo = uris.buscar_classes_veiculo;

  // Carrega lista de classes de veículo ao montar o componente
  useEffect(() => {
    const fetchClasses = async () => {
      try {
        const response = await fetch(uris.buscar_classes_veiculo, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${localStorage.getItem('token')}`,
          },
        });

        if (!response.ok) throw new Error('Erro ao carregar classes de veículo');

        const data = await response.json();
        setClassesVeiculo(data._ListaClassesVeiculo || []);
      } catch (error) {
        console.error('Erro ao carregar classes de veículo:', error);
      }
    };

    fetchClasses(); // chamada única ao montar o componente
  }, []);

  const handleFileChange = (e) => setXmlFiles(Array.from(e.target.files));

  const handleUpload = async () => {
    let todosCtes = [];
    let respostaEnvio;

    try {
      if (xmlFiles.length === 0) {
        return errorMessage('Selecione um ou mais arquivos XML para importar.');
      }

      // Processa os arquivos XML e extrai os dados
      for (const file of xmlFiles) {
        const fileContent = await file.text();
        const parser = new DOMParser();
        const xml = parser.parseFromString(fileContent, 'application/xml');

        const ctes = Array.from(xml.getElementsByTagName('CTe'));
        const importados = ctes.map((cte) => {
          const nCT = cte.getElementsByTagName('nCT')[0]?.textContent || '';
          const vTPrest = parseFloat(cte.getElementsByTagName('vTPrest')[0]?.textContent || 0);
          const xMunIni = cte.getElementsByTagName('xMunIni')[0]?.textContent || '';
          const UFIni = cte.getElementsByTagName('UFIni')[0]?.textContent || '';
          const xMunFim = cte.getElementsByTagName('xMunFim')[0]?.textContent || '';
          const UFFim = cte.getElementsByTagName('UFFim')[0]?.textContent || '';
          return { nCT, vTPrest, xMunIni, xMunFim, UFIni, UFFim };
        });
        todosCtes = todosCtes.concat(importados);
      }

      // Converte os arquivos XML para Base64
      const resultado = await ConverterArquivosXMLBase64(xmlFiles);
      if (resultado.files64.Ctes.length === 0) {
        return errorMessage('Nenhum arquivo XML válido encontrado.');
      }
      if (!resultado.sucesso) {
        return errorMessage('Erro durante a leitura dos arquivos: ' + resultado.mensagem);
      }

      // Monta payload incluindo a classe de veículo selecionada
      const requestPayload = {
        CD_Classe_Veiculo: selectedClasse || "",
        Ctes: resultado.files64.Ctes.map((xml) => ({
          XmlBase64: xml.XmlBase64,
          NR_Tabela_Frete: ""
        }))
      };

      // Envia os arquivos XML convertidos
      respostaEnvio = await TransportadorServico.ImportarConhecimentos({ files: requestPayload });

      if (!respostaEnvio.sucesso) {
        return errorMessage('Erro na importação do(s) cte(s) ' + respostaEnvio.erros);
      } else {
        infoMessage(respostaEnvio.data.message);

        if (respostaEnvio.data.results.length > 0) {
          setValoresEsperados(respostaEnvio.data.results);
        }
      }

      setCtesBase64(resultado.files64.Ctes);
      setCtesImportados(todosCtes);
      setXmlFiles([]);
      setSelectedCTE(null);

    } catch (error) {
      console.error('Erro no upload:', error);
      errorMessage('Erro durante o processamento dos arquivos');
    }
  };

  const getStatus = (nCT, vTPrest) => {
    const esperado = valoresEsperados.find((v) => v.numeroCTE === nCT);
    return esperado && esperado.freteCalculado === vTPrest;
  };

  const isDivergentExpected = (nCT, vTPrestEsperado) => {
    const importado = ctesImportados.find((c) => c.nCT === nCT);
    return importado && importado.vTPrest !== vTPrestEsperado;
  };

  return (
    <main className="flex-1 p-6 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold mb-6 text-center">Importação de CTe</h1>

      <div className="bg-white p-6 rounded shadow mb-6 flex justify-center items-center gap-4 flex-wrap">
        {/* ComboBox de classes de veículo */}
        <select
          value={selectedClasse}
          onChange={(e) => setSelectedClasse(e.target.value)}
          className="border p-2 rounded w-72 text-center"
        >
          <option value="">Selecione uma classe de veículo</option>
          {classesVeiculo.map((classe) => (
            <option key={classe._CD_Classe} value={classe._CD_Classe}>
              {classe._Descricao}
            </option>
          ))}
        </select>

        <input
          type="file"
          accept=".xml"
          multiple
          onChange={handleFileChange}
          //onClick={handleFileChange}
          className="border p-2 rounded"
        />

        <button
          onClick={handleUpload}
          className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          Importar XMLs
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-6">
        {/* Informações do CTe Importado */}
        <div className="bg-white p-4 rounded shadow overflow-auto text-center">
          <h2 className="font-semibold mb-2">Informações do CTe Importado</h2>
          {ctesImportados.length === 0 ? (
            <p className="text-gray-500">Nenhum CTe importado.</p>
          ) : (
            <table className="w-full text-center text-sm border-collapse">
              <thead>
                <tr>
                  <th className="p-2 border">Nº CTe</th>
                  <th className="p-2 border">Origem</th>
                  <th className="p-2 border">Destino</th>
                  <th className="p-2 border">Valor Frete</th>
                </tr>
              </thead>
              <tbody>
                {ctesImportados.map((c) => (
                  <tr
                    key={c.nCT}
                    onClick={() => setSelectedCTE(c.nCT)}
                    className={`cursor-pointer ${selectedCTE === c.nCT ? 'bg-gray-100' : getStatus(c.nCT, c.vTPrest) ? '' : 'bg-red-100'}`}
                  >
                    <td className="p-2 border">{c.nCT}</td>
                    <td className="p-2 border">{c.xMunIni}/{c.UFIni}</td>
                    <td className="p-2 border">{c.xMunFim}/{c.UFFim}</td>
                    <td className="p-2 border">R$ {c.vTPrest.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Valores Esperados */}
        <div className="bg-white p-4 rounded shadow overflow-auto text-center">
          <h2 className="font-semibold mb-2">Valores Esperados</h2>
          {valoresEsperados.length === 0 ? (
            <p className="text-gray-500">Aguardando importação...</p>
          ) : (
            <table className="w-full text-center text-sm border-collapse">
              <thead>
                <tr>
                  <th className="p-2 border">Nº CTe</th>
                  <th className="p-2 border">Origem</th>
                  <th className="p-2 border">Destino</th>
                  <th className="p-2 border">Valor Frete</th>
                </tr>
              </thead>
              <tbody>
                {valoresEsperados.map((c) => (
                  <tr
                    key={c.numeroCTE}
                    className={selectedCTE === c.numeroCTE ? 'bg-gray-100' : ''}
                  >
                    <td className="p-2 border">{c.numeroCTE}</td>
                    <td className="p-2 border">{c.origem}</td>
                    <td className="p-2 border">{c.destino}</td>
                    <td className={`p-2 border font-bold ${isDivergentExpected(c.numeroCTE, c.freteCalculado) ? 'text-red-600' : 'text-green-600'}`}>
                      R$ {c.freteCalculado.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Status */}
      <div className="bg-white p-4 rounded shadow text-center">
        {ctesImportados.length === 0 ? (
          <span className="text-gray-500">Aguardando importação...</span>
        ) : ctesImportados.every((c) => getStatus(c.nCT, c.vTPrest)) ? (
          <span className="text-green-600 font-bold">
            Aprovado — Liberado para Faturamento
          </span>
        ) : (
          <span className="text-red-600 font-bold">
            Reprovado — Em dúvida entre em contato com a Leo Madeiras
          </span>
        )}
      </div>
    </main>
  );
}
