// src/components/SidebarLayoutTransportador.js
import { Link, useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { FiMenu, FiFileText, FiLogOut } from 'react-icons/fi';
import { FaStore } from 'react-icons/fa';
import logo from '../assets/logo.png';

function SidebarLayoutTransportador({ user, children }) {
  const [open, setOpen] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) {
      navigate('/');
    }
  }, [user, navigate]);

  if (!user) return null;

  const handleLogout = () => {
    // Limpar localStorage ou token, se for o caso
    navigate('/');
  };

  return (
    <div className="flex min-h-screen">
      <aside
        className={`bg-green-900 text-white transition-all
           ${open ?
             'w-64' :
             'w-16'
          } p-4 flex flex-col justify-between`}
      >
        <div>
          <button
            onClick={() => setOpen(!open)}
            className="mb-4 text-2xl p-2 hover:bg-green-800 rounded"
          >
            <FiMenu />
          </button>

          {open && (
            <div className="mb-6 flex flex-col items-center">
              <img src={logo} alt="Leo Madeiras" className="w-20 h-auto mb-2" />
              <h2 className="text-center font-bold text-xl">Olá, {user.name}</h2>
              <p className="text-center text-sm opacity-75">Transportador</p>
            </div>
          )}

          <nav className="space-y-2">
            <Link
              to="/transportador/dados"
              className="flex items-center p-2 hover:bg-green-800 rounded"
            >
              <FaStore className="mr-2" /> {open && 'Dados da Empresa'}
            </Link>
            <Link
              to="/transportador"
              className="flex items-center p-2 hover:bg-green-800 rounded"
            >
              <FiFileText className="mr-2" /> {open && 'Importação de CTe'}
            </Link>
            <Link
              to="/faturas"
              className="flex items-center p-2 hover:bg-green-800 rounded"
            >
              <FiFileText className="mr-2" /> {open && 'Faturas'}
            </Link>

            <button
              onClick={handleLogout}
              className="flex items-center p-2 hover:bg-green-800 rounded mt-4"
            >
              <FiLogOut className="mr-2" /> {open && 'Sair'}
            </button>

          </nav>
        </div>

      </aside>

      <main className="flex-1 p-4 bg-gray-100 overflow-auto">{children}</main>
    </div>
  );
}

export default SidebarLayoutTransportador;
