export default function Coletas({ user }) {
    const [cepOrigem, setCepOrigem] = useState("");
    const [cepDestino, setCepDestino] = useState("");
    const [coletaId, setColetaId] = useState(null);
    const [enderecoOrigem, setEnderecoOrigem] = useState({ rua: "", numero: "", bairro: "", cidade: "", uf: "" });
    const [enderecoDestino, setEnderecoDestino] = useState({ rua: "", numero: "", bairro: "", cidade: "", uf: "" });
    const [showNotaModal, setShowNotaModal] = useState(false);
    const [notas, setNotas] = useState([]);
    const [filtroNota, setFiltroNota] = useState("");
    const [notasSelecionadas, setNotasSelecionadas] = useState([]);

    const [showOrdemModal, setShowOrdemModal] = useState(false);
    const [dadosOrdem, setDadosOrdem] = useState(null);

    const [remetenteCNPJ, setRemetenteCNPJ] = useState(() => {
    let login = localStorage.getItem('login');
    if (login) {
        return login;
    } else {
        return ""
    }    
    });


    const [remetenteRazao, setRemetenteRazao] = useState("");
    const [destinatarioCNPJ, setDestinatarioCNPJ] = useState("");
    const [destinatarioRazao, setDestinatarioRazao] = useState("");
    const [remetentePossuiTabelaFrete, setRemetentePossuiTabelaFrete] = useState(false);
    const [observacao, setObservacao] = useState("");
    const [motivo, setMotivo] = useState("");
    const [carreteiroSelecionado, setCarreteiroSelecionado] = useState(null);
    const [valorFrete, setValorFrete] = useState("");
    const [hora, setHora] = useState(() => {
        const agora = new Date();
        const h = String(agora.getHours()).padStart(2, "0");
        const m = String(agora.getMinutes()).padStart(2, "0");
        return `${h}:${m}`;
    });
    const [listaCarreteiros, setListaCarreteiros] = useState([]);

    const [mostrarModal, setMostrarModal] = useState(false);
    const [listaClientes, setListaClientes] = useState([]);
    const [tipoClienteSelecionado, setTipoClienteSelecionado] = useState(""); // "remetente" ou "destinatario"
    const [clienteSelecionado, setClienteSelecionado] = useState(null);
    const [carregandoCliente, setCarregandoCliente] = useState(false);
    const freteInputRef = useRef(null);
    const [loading, setLoading] = useState(false);

    const [veiculoSelecionado, setVeiculoSelecionado] = useState("");
    const [classesVeiculo, setClassesVeiculo] = useState([]);


    useEffect(() => {
        const carregarCarreteiros = async () => {
            try {
                const res = await LojaServico.ListarCarreteiros(user.token);
                console.log("Carreteiros API:", res.data.carreteiros);
                if (res.sucesso && res.data && Array.isArray(res.data.carreteiros)) {
                    setListaCarreteiros(res.data.carreteiros);
                } else {
                    setListaCarreteiros([]);
                }
            } catch (err) {
                console.error("Erro ao buscar carreteiros:", err);
                setListaCarreteiros([]);
            }
        };
        carregarCarreteiros();

        const fetchClasses = async () => {
            try {
                // const response = await fetch(IndexURI().buscar_classes_veiculo, {
                //   method: 'GET',
                //   headers: {
                //     'Content-Type': 'application/json',
                //     'Authorization': `Bearer ${localStorage.getItem('token')}`,
                //   },
                // });

                const response = await LojaServico.ListarClassesVeiculo();

                if (!response.sucesso) throw new Error('Erro ao carregar classes de veículo');

                setClassesVeiculo(response.data._ListaClassesVeiculo || []);

            } catch (error) {
                console.error('Erro ao carregar classes de veículo:', error);
            }
        };

        fetchClasses();
    }, []);

    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === "Escape" && showOrdemModal) {
                setShowOrdemModal(false);
            }
        };

        window.addEventListener("keydown", handleKeyDown);

        return () => {
            window.removeEventListener("keydown", handleKeyDown);
        };
    }, [showOrdemModal]);

    const motivosMap = {
        "001": "Devolução",
        "002": "Reentrega",
        "003": "Entrega",
        "004": "Coleta"
    };

    // Normaliza CNPJ/CPF removendo pontuação
    const normalizeCNPJ = (cnpj) => (cnpj ? cnpj.replace(/\D/g, "") : "");

    // Substitua o handleConfirmar existente por este:
    const handleConfirmar = async () => {
        if (!carreteiroSelecionado) {
            alert("Selecione um carreteiro antes de confirmar.");
            return;
        }

        if (notasSelecionadas.length === 0) {
            alert("É necessário vincular ao menos uma Nota Fiscal antes de confirmar a ordem.");
            return;
        }

        setLoading(true);
        try {
            const cdEmpresa = carreteiroSelecionado.CD_Empresa || carreteiroSelecionado.cD_Empresa || "";
            const cdFilial = carreteiroSelecionado.CD_Filial || carreteiroSelecionado.cD_Filial || "";
            const cnpjCarreteiro = carreteiroSelecionado.cnpj || "";

            const rawValor = (valorFrete || "").toString();
            var numericStr = rawValor.replace(/[^\d.,]/g, "");

            if (numericStr.includes(",")) {
                numericStr = numericStr.replace(",", ".");
            }

            const vrFreteNumber = isNaN(parseFloat(numericStr)) ? 0 : parseFloat(numericStr);

            const now = new Date();
            const dataSolic = now.toLocaleDateString("pt-BR");
            const hrSolic = hora || now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

            const cnpj_loja = user?.cnpj || user?.CNPJ;

            const motivoDescricao = motivo ? motivosMap[motivo] : motivosMap["004"];

            const coletaPayload = {
                Coleta: {
                    CD_Empresa: cdEmpresa,
                    CD_Filial: cdFilial,
                    NR_Coleta: null,
                    ST_Coleta: "NÃO INICIADA",
                    DT_Solicitacao_Coleta: dataSolic,
                    HR_Solicitacao_Coleta: hrSolic,
                    DT_Emissao: dataSolic,
                    DT_Coleta: dataSolic,
                    HR_Coleta: hrSolic,
                    CGC_CPF_Cliente: normalizeCNPJ(remetenteCNPJ),
                    CGC_CPF_Solicitante: normalizeCNPJ(cnpj_loja),
                    CGC_CPF_Transportadora: normalizeCNPJ(cnpjCarreteiro) || "",
                    Endereco_Coleta: enderecoOrigem.rua || "",
                    NR_Endereco: enderecoOrigem.numero || "",
                    Bairro: enderecoOrigem.bairro || "",
                    Cidade: enderecoOrigem.cidade || "",
                    UF: enderecoOrigem.uf || "",
                    CEP_Cidade_Coleta: cepOrigem || "",
                    VR_Frete: vrFreteNumber,
                    CD_Motivo_Coleta: motivo || "004",
                    TP_Restricao: 'A',
                    SQ_Coleta: '1',
                    Operador: cnpj_loja,
                    FL_Coleta_Simples: true,
                    CGC_CPF_Destinatario: normalizeCNPJ(destinatarioCNPJ),
                    Endereco_Destinatario: enderecoDestino.rua,
                    NR_Endereco_Destinatario: enderecoDestino.numero,
                    Bairro_Destinatario: enderecoDestino.bairro,
                    Cidade_Destinatario: enderecoDestino.cidade,
                    UF_Destinatario: enderecoDestino.uf,
                    CEP_REF_Destino: cepDestino,
                    Razao_Social_Destinatario: destinatarioRazao,
                    Observacao: observacao || ""
                },
                NFs: notasSelecionadas.map(n => ({
                    CD_Empresa: cdEmpresa,
                    CD_Filial: cdFilial,
                    NR_NF: n.nf || n.NF || "",
                    NR_NF_Serie: n.serie || n.NF_Serie || "",
                    NR_Chave: n.chave,
                    NR_Coleta: null,
                    CGC_CPF_Remetente: normalizeCNPJ(remetenteCNPJ),
                    CGC_CPF_Cliente: normalizeCNPJ(remetenteCNPJ),
                    TP_Coleta: "",
                    Nf_Inserida_Manualmente: n.nf_inserida_manualmente
                }))
            };

            const res = await LojaServico.IncluirColeta(coletaPayload);

            if (res && res.sucesso) {
                const nrColetaRetornado = res.data?.nR_Coleta || coletaPayload.Coleta.NR_Coleta || null;

                const dados = {
                    numero: nrColetaRetornado,
                    dataSolicitacao: dataSolic,
                    horaSolicitacao: hrSolic,
                    horario: hrSolic,
                    empresa: {
                        nome: user?.name || "",
                        endereco: enderecoOrigem.rua || "",
                        numero: enderecoOrigem.numero || "",
                        municipio: enderecoOrigem.cidade || "",
                        cep: cepOrigem || "",
                        fone: "",
                        fax: "",
                        cnpj: "",
                        uf: enderecoOrigem.uf || ""
                    },
                    remetente: {
                        cnpj: remetenteCNPJ,
                        nome: remetenteRazao,
                        endereco: enderecoOrigem.rua,
                        numero: enderecoOrigem.numero,
                        cidade: enderecoOrigem.cidade,
                        bairro: enderecoOrigem.bairro,
                        estado: enderecoOrigem.uf
                    },
                    destinatario: {
                        cnpj: destinatarioCNPJ,
                        nome: destinatarioRazao,
                        endereco: enderecoDestino.rua,
                        numero: enderecoDestino.numero,
                        municipio: enderecoDestino.cidade,
                        bairro: enderecoDestino.bairro,
                        estado: enderecoDestino.uf
                    },
                    motorista: carreteiroSelecionado?.nomeRazao || carreteiroSelecionado?.NomeRazao || carreteiroSelecionado?.Razao_Social || "",
                    valor: valorFrete,
                    produto: "",
                    observacao: "",
                    motivo: motivoDescricao,
                    notasVinculadas: notasSelecionadas
                };

                setDadosOrdem(dados);
                setShowOrdemModal(true);

                // reset campos
                setCepOrigem("");
                setCepDestino("");
                setEnderecoOrigem({ rua: "", numero: "", bairro: "", cidade: "", uf: "" });
                setEnderecoDestino({ rua: "", numero: "", bairro: "", cidade: "", uf: "" });
                setRemetenteCNPJ("");
                setRemetenteRazao("");
                setDestinatarioCNPJ("");
                setDestinatarioRazao("");
                setMotivo("");
                setValorFrete("");
                setCarreteiroSelecionado(null);
                setNotasSelecionadas([]);

                alert(`Coleta cadastrada com sucesso! NR Coleta: ${nrColetaRetornado}`);
            } else {
                const msg = res?.data?.message || res?.data || "Erro desconhecido";
                alert("Falha ao incluir a coleta: " + msg);
            }
        } catch (err) {
            console.error("Erro ao enviar coleta:", err);
            alert("Ocorreu um erro ao enviar a coleta. Ver console para detalhes.");
        } finally {
            setLoading(false);
        }
    };

    // const openModal = () => {
    //     //setSelectedColeta(coleta);
    //     setModalOpen(true);
    // };

    // const closeModal = () => {
    //     setSelectedColeta(null);
    //     setModalOpen(false);
    // };

    const buscarEndereco = async (cep, tipo) => {
        try {
            const res = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
            const data = await res.json();
            if (data.erro) return;
            const endereco = {
                rua: data.logradouro,
                numero: "",
                bairro: data.bairro,
                cidade: data.localidade,
                uf: data.uf,
            };
            if (tipo === "origem") setEnderecoOrigem(endereco);
            if (tipo === "destino") setEnderecoDestino(endereco);
        } catch (err) {
            console.error("Erro ao buscar CEP:", err);
        }
    };

    useEffect(() => {
        if (cepOrigem.length === 8) buscarEndereco(cepOrigem, "origem");
    }, [cepOrigem]);

    useEffect(() => {
        if (cepDestino.length === 8) buscarEndereco(cepDestino, "destino");
    }, [cepDestino]);

    const handlePesquisarNotas = async () => {
        if (!filtroNota) return;

        setLoading(true);
        try {
            const res = await LojaServico.BuscarNotas(filtroNota);

            if (res.sucesso && Array.isArray(res.data.dados)) {
                if (res.data.dados.length === 0) {
                    const desejaVincular = window.confirm("Nota não localizada. Deseja vincular este número à Ordem de Serviço?");
                    if (desejaVincular) {
                        setNotasSelecionadas(prev => [...prev, { dtEmissao: "-", nf: filtroNota, pedido: "-", remetente: "Manual", peso: "-", valor: "-", nf_inserida_manualmente: true }]);
                        setNotas([]);
                        setFiltroNota("");
                        setShowNotaModal(false);
                    }
                } else {
                    setNotas(res.data.dados);
                }
            } else {
                console.error("Erro ao buscar notas:", res.erros);
                setNotas([]);
            }
        } catch (err) {
            console.error("Erro na requisição de notas:", err);
            setNotas([]);
        } finally {
            setLoading(false);
        }
    };

    const selecionarNota = (nota) => {
        const jaSelecionada = notasSelecionadas.some(n => n.chave === nota.chave);
        if (!jaSelecionada) {
            setNotasSelecionadas(prev => [...prev, nota]);
            setNotas([]);
            setFiltroNota("");
        } else {
            alert("Esta nota já está vinculada.");
        }
    };

    const removerNota = (nf) => {
        setNotasSelecionadas(prev => prev.filter(nota => nota.nf !== nf));
    };

    const limparDocumento = (valor) => valor.replace(/\D/g, "");

    const formatarDocumento = (valor) => {
        const numeros = valor.replace(/\D/g, ""); // remove tudo que não for número

        if (numeros.length === 11) {
            // CPF
            return numeros.replace(
                /^(\d{3})(\d{3})(\d{3})(\d{2})$/,
                "$1.$2.$3-$4"
            );
        } else if (numeros.length === 14) {
            // CNPJ
            return numeros.replace(
                /^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/,
                "$1.$2.$3/$4-$5"
            );
        }

        // Outro tamanho, retorna sem máscara
        return valor;
    };

    const handleRemetenteBlur = async () => {
        if (remetenteCNPJ) {
            await buscarCliente(remetenteCNPJ, "remetente");
        }
    };

    const handleDestinatarioBlur = async () => {
        if (destinatarioCNPJ) {
            await buscarCliente(destinatarioCNPJ, "destinatario");
        }
    };

    const handleRemetenteKeyDown = async (e) => {
        if (e.key === "Enter") {
            await buscarCliente(remetenteCNPJ, "remetente");
        }
    };

    const handleDestinatarioKeyDown = async (e) => {
        if (e.key === "Enter") {
            await buscarCliente(destinatarioCNPJ, "destinatario");
        }
    };

    const handleCalcularFrete = async () => {
        setLoading(true); // inicia o loading
        try {
            const request = {
                cnpjRemetente: limparDocumento(remetenteCNPJ),
                cepOrigem,
                cepDestino,
                cidadeOrigem: enderecoOrigem?.cidade ?? "",
                cidadeDestino: enderecoDestino?.cidade ?? "",
                ufOrigem: enderecoOrigem?.uf ?? "",
                ufDestino: enderecoDestino?.uf ?? "",
                peso: notasSelecionadas.reduce(
                    (sum, nf) => sum + parseFloat(String(nf.peso).replace(",", ".")) || 0,
                    0
                ),
                valorMercadoria: notasSelecionadas.reduce(
                    (sum, nf) => sum + parseFloat(String(nf.valor).replace(",", ".")) || 0,
                    0
                ),
                cdFilialCarreteiro: carreteiroSelecionado?.cD_Filial ?? "",
                cdClasseVeiculo: veiculoSelecionado
            };

            const resposta = await LojaServico.CalcularFreteColeta(request);

            if (resposta?.data?.vr_Frete !== undefined && resposta.data.vr_Frete > 0) {
                setValorFrete(resposta.data.vr_Frete);
                setTimeout(() => {
                    freteInputRef.current?.focus();
                }, 0);
            } else {
                alert("Não foi possível calcular o frete para a coleta.");
            }
        } catch (err) {
            console.error(err);
            alert("Erro ao calcular frete para a coleta.");
        } finally {
            setLoading(false); // finaliza o loading
        }
    };

    const aplicarClienteSelecionado = (cliente, tipoForcado) => {
        if (!cliente) return;

        const { razao, cgcCpf, rua, bairro, cidade, uf, cep } = cliente;

        const tipoF = tipoForcado ?? tipoClienteSelecionado;

        if (tipoF === "remetente") {
            setRemetenteRazao(razao);
            setRemetenteCNPJ(formatarDocumento(cgcCpf));
            setRemetentePossuiTabelaFrete(cliente.possuiTabelaFrete || false);
            setEnderecoOrigem({ rua, numero: "", bairro, cidade, uf });
            setCepOrigem(cep);
        } else if (tipoF === "destinatario") {
            setDestinatarioRazao(razao);
            setDestinatarioCNPJ(formatarDocumento(cgcCpf));
            setEnderecoDestino({ rua, numero: "", bairro, cidade, uf });
            setCepDestino(cep);
        }

        setMostrarModal(false);
        setClienteSelecionado(null);
    };

    const buscarCliente = async (filtro, tipo) => {
        if (!filtro || !filtro.trim()) return;

        const filtroLimpo = /^\d+$/.test(filtro.replace(/\D/g, "")) ? filtro.replace(/\D/g, "") : filtro;

        setCarregandoCliente(true);

        try {
            const res = await LojaServico.BuscarCliente(filtroLimpo);
            const listaBruta = Array.isArray(res) ? res : [];

            const lista = listaBruta.map((x) => ({
                cgcCpf: x.cgC_CPF ?? "",
                razao: x.razao_Social ?? "",
                rua: x.endereco ?? "",
                bairro: x.bairro ?? "",
                cidade: x.cidade ?? "",
                uf: x.uf ?? "",
                cep: x.cep ?? "",
                possuiTabelaFrete: x.possuiTabelaFrete ?? false
            }));

            if (lista.length === 0) {
                if (tipo === "remetente") setRemetenteRazao("Não encontrado");
                else setDestinatarioRazao("Não encontrado");
                setCarregandoCliente(false);
                return;
            }

            if (lista.length === 1) {
                aplicarClienteSelecionado(lista[0], tipo);
                setCarregandoCliente(false);
                return;
            }

            // Múltiplos resultados: abrir modal
            setListaClientes(lista);
            setTipoClienteSelecionado(tipo);
            setClienteSelecionado(null);
            setMostrarModal(true);
        } catch (err) {
            console.error("Erro ao buscar clientes:", err);
            if (tipo === "remetente") setRemetenteRazao("Erro na consulta");
            else setDestinatarioRazao("Erro na consulta");
        } finally {
            setCarregandoCliente(false);
        }
    };

    const listRef = useRef(null);

    useEffect(() => {
        if (listRef.current) {
            listRef.current.scrollTop = listRef.current._lastScrollTop || 0;
        }
    }, [clienteSelecionado]);

    const handleScroll = () => {
        if (listRef.current) {
            listRef.current._lastScrollTop = listRef.current.scrollTop;
        }
    };

    // --- ModalClientes aqui ---
    function ModalClientes({ open, onClose, clientes, clienteSelecionado, setClienteSelecionado, aplicarClienteSelecionado }) {
        const selectedRef = useRef(null);

        useEffect(() => {
            if (selectedRef.current) {
                selectedRef.current.scrollIntoView({
                    behavior: "smooth",
                    block: "nearest",
                });
            }
        }, [clienteSelecionado]);

        if (!open) return null; // não renderiza se estiver fechado

        return (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                <div className="bg-white p-6 rounded-xl w-full max-w-lg shadow-xl space-y-4">
                    <h2 className="text-xl font-semibold">Selecionar</h2>

                    {clientes.length === 0 ? (
                        <p className="text-center py-4">Nenhum cliente encontrado.</p>
                    ) : (
                        <div className="space-y-2 max-h-80 overflow-y-auto">
                            {clientes.map((cli) => (
                                <div
                                    key={cli.cgcCpf}
                                    ref={clienteSelecionado?.cgcCpf === cli.cgcCpf ? selectedRef : null}
                                    className={`p-3 rounded-lg border cursor-pointer ${clienteSelecionado?.cgcCpf === cli.cgcCpf
                                        ? "bg-blue-100 border-blue-500"
                                        : "hover:bg-gray-100"
                                        }`}
                                    onClick={() => setClienteSelecionado(cli)}
                                >
                                    <p className="font-semibold">{cli.razao}</p>
                                    <p className="text-sm text-gray-600">{cli.cgcCpf}</p>
                                    <p className="text-sm text-gray-500">
                                        {cli.rua}, {cli.bairro} - {cli.cidade}/{cli.uf} | CEP: {cli.cep}
                                    </p>
                                </div>
                            ))}
                        </div>
                    )}

                    <div className="flex justify-end gap-2 mt-4">
                        <button
                            className="px-3 py-1 border rounded hover:bg-gray-100"
                            onClick={onClose}
                        >
                            Cancelar
                        </button>
                        <button
                            className="px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700"
                            onClick={aplicarClienteSelecionado}
                            disabled={!clienteSelecionado}
                        >
                            Selecionar
                        </button>

                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="p-6 space-y-6">
            <h1 className="text-2xl font-bold">Ordem de Serviço</h1>

            <div className="bg-white p-4 rounded-xl shadow space-y-6">
                {/* Primeira linha */}
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <div>
                        <label className="block font-medium mb-1">Data Solicitação</label>
                        <input
                            type="date"
                            defaultValue={new Date().toISOString().split("T")[0]}
                            className="w-full border px-3 py-2 rounded"
                            readOnly
                        />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Hora</label>
                        <input
                            type="time"
                            value={hora}
                            onChange={(e) => setHora(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                        />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Motivo</label>
                        <select
                            value={motivo}
                            onChange={(e) => setMotivo(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                        >
                            <option value="">Selecione</option>
                            <option value="001">Devolução</option>
                            <option value="002">Reentrega</option>
                            <option value="003">Entrega</option>
                            <option value="004">Coleta</option>
                        </select>
                    </div>
                    <div className="md:col-span-2">
                        <label className="block font-medium mb-1">Carreteiro</label>
                        <select
                            value={carreteiroSelecionado ? carreteiroSelecionado.cnpj : ""}
                            onChange={(e) => {
                                const selecionado = listaCarreteiros.find(c => c.cnpj === e.target.value);
                                setCarreteiroSelecionado(selecionado || null);
                            }}
                            className="w-full border px-3 py-2 rounded"
                        >
                            <option value="">Selecione</option>
                            {listaCarreteiros.map((c, idx) => (
                                <option key={idx} value={c.cnpj}>
                                    {c.nomeRazao} ({c.cD_Filial})
                                </option>
                            ))}
                        </select>
                    </div>
                </div>

                {/* Segunda linha */}
                <div className="grid grid-cols-5 gap-4">
                    <div className="md:col-span-2">
                        <label className="block font-medium mb-1">Classe Veículo</label>
                        <select
                            value={veiculoSelecionado}
                            onChange={(e) => setVeiculoSelecionado(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                        >
                            <option value="">Selecione</option>
                            {classesVeiculo.map((c, idx) => (
                                <option key={idx} value={c._CD_Classe}>
                                    {c._Descricao}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="md:col-span-1">
                        <label className="block font-medium mb-1">Valor Frete</label>
                        <input
                            type="text"
                            ref={freteInputRef}
                            value={valorFrete}
                            onChange={(e) => setValorFrete(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                            placeholder="R$"
                            readOnly={remetentePossuiTabelaFrete}
                        />
                    </div>
                    <div className="md:col-span-2"></div> {/* espaço vazio abaixo de carreteiro */}
                </div>

                {/* Terceira linha: Remetente */}
                <div className="space-y-1">
                    <label className="block font-medium mb-1">Remetente</label>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <input
                            type="text"
                            value={remetenteCNPJ}
                            onChange={(e) => setRemetenteCNPJ(e.target.value)}
                            onKeyDown={handleRemetenteKeyDown}
                            onBlur={handleRemetenteBlur}
                            className="w-full border px-3 py-2 rounded"
                            placeholder="Digite o CNPJ ou nome"
                        />
                        <input
                            type="text"
                            value={remetenteRazao}
                            readOnly
                            className="w-full border px-3 py-2 rounded bg-gray-100"
                            placeholder="Razão Social"
                        />
                    </div>
                </div>

                <button
                    className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700 text-sm"
                    onClick={() => setShowNotaModal(true)}
                    style={{ width: "120px", height: "32px" }}
                >
                    Nota Fiscais
                </button>
            </div>

            {/* Local da Coleta */}
            <div className="bg-white p-4 rounded-xl shadow space-y-4">
                <h2 className="text-lg font-semibold">Local da Coleta</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                        <label className="block font-medium mb-1">CEP</label>
                        <input
                            type="text"
                            value={cepOrigem}
                            onChange={(e) => setCepOrigem(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                        />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Rua</label>
                        <input type="text" value={enderecoOrigem.rua} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Nº</label>
                        <input
                            type="text"
                            value={enderecoOrigem.numero}
                            onChange={(e) => setEnderecoOrigem(prev => ({ ...prev, numero: e.target.value }))}
                            className="w-full border px-3 py-2 rounded"
                            placeholder="Número"
                        />
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-2">
                    <div>
                        <label className="block font-medium mb-1">Bairro</label>
                        <input type="text" value={enderecoOrigem.bairro} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Cidade</label>
                        <input type="text" value={enderecoOrigem.cidade} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">UF</label>
                        <input type="text" value={enderecoOrigem.uf} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                </div>
            </div>

            {/* Destinatário */}
            <div className="bg-white p-4 rounded-xl shadow space-y-4">
                <h2 className="text-lg font-semibold">Destinatário</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="md:col-span-3 grid grid-cols-2 gap-4">
                        <input
                            type="text"
                            value={destinatarioCNPJ}
                            onChange={(e) => setDestinatarioCNPJ(e.target.value)}
                            onKeyDown={handleDestinatarioKeyDown}
                            onBlur={() => buscarCliente(destinatarioCNPJ, "destinatario")}
                            className="w-full border px-3 py-2 rounded"
                            placeholder="Digite o CNPJ ou nome"
                        />
                        <input
                            type="text"
                            value={destinatarioRazao}
                            readOnly
                            className="w-full border px-3 py-2 rounded bg-gray-100"
                            placeholder="Razão Social"
                        />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">CEP</label>
                        <input
                            type="text"
                            value={cepDestino}
                            onChange={(e) => setCepDestino(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                        />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Rua</label>
                        <input type="text" value={enderecoDestino.rua} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Nº</label>
                        <input
                            type="text"
                            value={enderecoDestino.numero}
                            onChange={(e) => setEnderecoDestino(prev => ({ ...prev, numero: e.target.value }))}
                            className="w-full border px-3 py-2 rounded"
                            placeholder="Número"
                        />
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-2">
                    <div>
                        <label className="block font-medium mb-1">Bairro</label>
                        <input type="text" value={enderecoDestino.bairro} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">Cidade</label>
                        <input type="text" value={enderecoDestino.cidade} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                    <div>
                        <label className="block font-medium mb-1">UF</label>
                        <input type="text" value={enderecoDestino.uf} className="w-full border px-3 py-2 rounded" readOnly />
                    </div>
                </div>
            </div>

            {/*Observação*/
                <div className="bg-white p-4 rounded-xl shadow space-y-4">
                    <h2 className="text-lg font-semibold">Observação</h2>
                    <div className="md:col-span-3 grid grid-cols-1 gap-4">
                        <input
                            type="text"
                            value={observacao}
                            onChange={(e) => setObservacao(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                            placeholder="Digite uma observação"
                        />
                    </div>
                </div>

            }

            {/* Botão Confirmar */}
            <div className="text-right mt-6 space-x-4">
                {remetentePossuiTabelaFrete && (
                    <button
                        onClick={handleCalcularFrete}
                        className="bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700 mr-3"
                    >
                        Calcular Frete
                    </button>
                )}
                <button
                    onClick={handleConfirmar}
                    className="bg-green-600 text-white px-6 py-2 rounded hover:bg-green-700"
                >
                    Confirmar
                </button>
            </div>

            {/* Modal de notas */}
            {showNotaModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <div className="bg-white p-6 rounded-xl w-full max-w-3xl shadow-xl space-y-4">
                        <h2 className="text-xl font-semibold">Pesquisar Nota Fiscal</h2>
                        <input
                            type="text"
                            placeholder="NR Pedido ou NR NF"
                            value={filtroNota}
                            onChange={(e) => setFiltroNota(e.target.value)}
                            className="w-full border px-3 py-2 rounded"
                        />
                        <button
                            onClick={handlePesquisarNotas}
                            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
                        >
                            Pesquisar
                        </button>
                        {notas.length > 0 && (
                            <div className="w-full mt-4 overflow-x-auto">
                                <table className="w-full mt-4 border text-sm">
                                    <thead>
                                        <tr className="bg-gray-100">
                                            <th className="p-2 border">DT Emissão</th>
                                            <th className="p-2 border">NR NF</th>
                                            <th className="p-2 border">NR Pedido</th>
                                            <th className="p-2 border">Remetente</th>
                                            <th className="p-2 border">Peso</th>
                                            <th className="p-2 border">Valor NF</th>
                                            <th className="p-2 border">Ação</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {notas.map((nota, idx) => (
                                            <tr key={idx} className="text-center">
                                                <td className="p-2 border">{nota.dtEmissao}</td>
                                                <td className="p-2 border">{nota.nf}</td>
                                                <td className="p-2 border">{nota.pedido}</td>
                                                <td className="p-2 border">{nota.remetente}</td>
                                                <td className="p-2 border">{nota.peso}</td>
                                                <td className="p-2 border">{nota.valor}</td>
                                                <td className="p-2 border">
                                                    <button
                                                        onClick={() => selecionarNota(nota)}
                                                        className="bg-green-600 text-white px-2 py-1 rounded hover:bg-green-700 text-xs"
                                                    >
                                                        Selecionar
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}

                        {notasSelecionadas.length > 0 && (
                            <div className="mt-6">
                                <h3 className="text-lg font-semibold mb-2">Notas Selecionadas:</h3>
                                <table className="w-full border text-sm">
                                    <thead>
                                        <tr className="bg-gray-200">
                                            <th className="p-2 border">
                                                <input
                                                    type="checkbox"
                                                    checked={notasSelecionadas.every(nota => nota.checked)}
                                                    onChange={(e) => {
                                                        const checked = e.target.checked;
                                                        setNotasSelecionadas(prev => prev.map(nota => ({ ...nota, checked })));
                                                    }}
                                                />
                                            </th>
                                            <th className="p-2 border">NR NF</th>
                                            <th className="p-2 border">Remetente</th>
                                            <th className="p-2 border">Pedido</th>
                                            <th className="p-2 border">Peso</th>
                                            <th className="p-2 border">Valor</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {notasSelecionadas.map((nota, idx) => (
                                            <tr key={idx} className="text-center">
                                                <td className="p-2 border">
                                                    <input
                                                        type="checkbox"
                                                        checked={!!nota.checked}
                                                        onChange={(e) => {
                                                            const updated = [...notasSelecionadas];
                                                            updated[idx].checked = e.target.checked;
                                                            setNotasSelecionadas(updated);
                                                        }}
                                                    />
                                                </td>
                                                <td className="p-2 border">{nota.nf}</td>
                                                <td className="p-2 border">{nota.remetente}</td>
                                                <td className="p-2 border">{nota.pedido}</td>
                                                <td className="p-2 border">{nota.peso}</td>
                                                <td className="p-2 border">{nota.valor}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>

                                <div className="text-right mt-2">
                                    <button
                                        onClick={() => setNotasSelecionadas(prev => prev.filter(nota => !nota.checked))}
                                        className="mt-2 bg-red-600 text-white px-4 py-1 rounded hover:bg-red-700 text-sm"
                                    >
                                        Remover Selecionadas
                                    </button>
                                </div>
                            </div>
                        )}

                        <div className="text-right">
                            <button
                                onClick={() => {
                                    setShowNotaModal(false);
                                    setNotas([]);
                                    setFiltroNota("");
                                }}
                                className="mt-4 text-sm text-gray-500 hover:underline"
                            >
                                Fechar
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal da Ordem de Serviço para impressão */}
            {showOrdemModal && dadosOrdem && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <div className="bg-white p-6 rounded-xl w-full max-w-4xl shadow-xl space-y-4 relative">
                        <button
                            onClick={() => setShowOrdemModal(false)}
                            className="absolute top-2 right-2 text-xl font-bold"
                        >
                            &times;
                        </button>
                        <OrdemDeColetaPrint dados={dadosOrdem} />
                        <div className="text-right mt-4">
                            <button
                                onClick={() => window.print()}
                                className="bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700"
                            >
                                Imprimir
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {mostrarModal && (
                <ModalClientes
                    open={mostrarModal}
                    onClose={() => setMostrarModal(false)}
                    clientes={listaClientes}
                    clienteSelecionado={clienteSelecionado}
                    setClienteSelecionado={setClienteSelecionado}
                    aplicarClienteSelecionado={() => aplicarClienteSelecionado(clienteSelecionado)}
                    carregandoCliente={carregandoCliente}
                />
            )}

            {loading && (
                <div className="fixed inset-0 bg-black/30 flex items-center justify-center z-50">
                    <div className="bg-white p-4 rounded shadow flex flex-col items-center">
                        <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-600 mb-2"></div>
                        <span>Carregando...</span>
                    </div>
                </div>
            )}


            {/* <Modal isOpen={true} onClose={closeModal} /> */}

        </div>
    );
}