import { useState, useEffect } from 'react';
import { LojaServico } from '../../services/LojaServico';

const UFs = [
  'AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT',
  'MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO',
  'RR','SC','SP','SE','TO'
];

export default function CarreteirosCadastro() {
  const [cpfCnpj, setCpfCnpj] = useState('');
  const [nome, setNome] = useState('');
  const [cep, setCep] = useState('');
  const [endereco, setEndereco] = useState({
    rua: '',
    numero: '',
    bairro: '',
    cidade: '',
    uf: '',
  });
  const [telefone, setTelefone] = useState('');
  const [ie, setIE] = useState('');
  const [email, setEmail] = useState('');

  useEffect(() => {
    const fetchEndereco = async () => {
      if (cep.length === 8) {
        try {
          const res = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
          const data = await res.json();
          if (!data.erro) {
            setEndereco(prev => ({
              ...prev,
              rua: data.logradouro || '',
              bairro: data.bairro || '',
              cidade: data.localidade || '',
              uf: data.uf || '',
            }));
          }
        } catch (error) {
          console.error('Erro ao buscar CEP:', error);
        }
      }
    };
    fetchEndereco();
  }, [cep]);

  const handleCadastrar = async () => {
  const novoCarreteiro = {
    CNPJ: cpfCnpj.replace(/\D/g, ''), // só números
    Razao_Social: nome,
    IE: ie,
    CEP: cep.replace(/\D/g, ''),
    Endereco: endereco.rua,
    Numero: endereco.numero,
    Bairro: endereco.bairro,
    Cidade: endereco.cidade,
    UF: endereco.uf,
    Telefone: telefone.replace(/\D/g, ''),
    Email: email
  };

  try {
    const resposta = await LojaServico.InserirCarreteiro(novoCarreteiro);
    
    if (resposta && resposta.data?.message === "sucesso") {
      alert('Cadastro realizado com sucesso!');
      // limpa os campos
      setCpfCnpj('');
      setNome('');
      setIE('');
      setCep('');
      setEndereco({ rua: '', numero: '', bairro: '', cidade: '', uf: '' });
      setTelefone('');
      setEmail('');
    } else {
      alert('Erro ao cadastrar carreteiro: ' + (resposta?.erros || 'Erro desconhecido'));
    }
  } catch (error) {
    console.error(error);
    alert('Erro ao cadastrar carreteiro: ' + error.message);
  }
};

  return (
    <div className="p-8 w-[96vw] max-w-full mx-auto bg-white rounded shadow-lg">
      <h1 className="text-3xl font-bold mb-8">Cadastro Carreteiro</h1>

      <div className="flex space-x-6 mb-6">
        <div className="flex-1">
          <label className="block font-medium mb-2">CPF / CNPJ</label>
          <input
            type="text"
            value={cpfCnpj}
            onChange={e => setCpfCnpj(e.target.value.replace(/\D/g, ''))}
            className="w-full border px-4 py-3 rounded"
            placeholder="Digite CPF ou CNPJ"
          />
        </div>

        <div className="flex-1">
          <label className="block font-medium mb-2">Nome / Razão Social</label>
          <input
            type="text"
            value={nome}
            onChange={e => setNome(e.target.value)}
            className="w-full border px-4 py-3 rounded"
            placeholder="Nome do carreteiro"
          />
        </div>
      </div>

      <div className="flex space-x-6 mb-6">
        <div className="w-28">
          <label className="block font-medium mb-2">CEP</label>
          <input
            type="text"
            value={cep}
            onChange={e => setCep(e.target.value.replace(/\D/g, ''))}
            maxLength={8}
            className="w-full border px-4 py-3 rounded"
            placeholder="CEP"
          />
        </div>

        <div className="flex-1">
          <label className="block font-medium mb-2">Rua</label>
          <input
            type="text"
            value={endereco.rua}
            onChange={e => setEndereco({ ...endereco, rua: e.target.value })}
            className="w-full border px-4 py-3 rounded"
            placeholder="Rua"
          />
        </div>

        <div className="w-28">
          <label className="block font-medium mb-2">Número</label>
          <input
            type="text"
            value={endereco.numero}
            onChange={e => setEndereco({ ...endereco, numero: e.target.value })}
            className="w-full border px-4 py-3 rounded"
            placeholder="Nº"
          />
        </div>
      </div>

      <div className="flex space-x-6 mb-6">
        <div className="flex-1">
          <label className="block font-medium mb-2">Bairro</label>
          <input
            type="text"
            value={endereco.bairro}
            onChange={e => setEndereco({ ...endereco, bairro: e.target.value })}
            className="w-full border px-4 py-3 rounded"
            placeholder="Bairro"
          />
        </div>

        <div className="flex-1">
          <label className="block font-medium mb-2">Cidade</label>
          <input
            type="text"
            value={endereco.cidade}
            onChange={e => setEndereco({ ...endereco, cidade: e.target.value })}
            className="w-full border px-4 py-3 rounded"
            placeholder="Cidade"
          />
        </div>

        <div className="w-28">
          <label className="block font-medium mb-2">UF</label>
          <select
            value={endereco.uf}
            onChange={e => setEndereco({ ...endereco, uf: e.target.value })}
            className="w-full border px-4 py-3 rounded bg-white"
          >
            <option value="">Selecione</option>
            {UFs.map(uf => (
              <option key={uf} value={uf}>
                {uf}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="flex space-x-6 mb-8">
        <div className="flex-1">
          <label className="block font-medium mb-2">Telefone</label>
          <input
            type="text"
            value={telefone}
            onChange={e => setTelefone(e.target.value.replace(/\D/g, ''))}
            className="w-full border px-4 py-3 rounded"
            placeholder="Telefone"
          />
        </div>

        <div className="flex-1">
          <label className="block font-medium mb-2">IE</label>
          <input
            type="text"
            value={ie}
            onChange={e => setIE(e.target.value)}
            className="w-full border px-4 py-3 rounded"
            placeholder="IE"
          />
        </div>

        <div className="flex-1">
          <label className="block font-medium mb-2">E-mail</label>
          <input
            type="email"
            value={email}
            onChange={e => setEmail(e.target.value)}
            className="w-full border px-4 py-3 rounded"
            placeholder="E-mail"
          />
        </div>
      </div>

      <button
        onClick={handleCadastrar}
        className="bg-green-600 text-white px-8 py-3 rounded hover:bg-green-700"
      >
        Cadastrar
      </button>
    </div>
  );
}
