    static async BuscarAprovacoesPendentes() {
        let resposta;
        const token = localStorage.getItem("token");

        try {
            resposta = await buscarDadosPrivado(
                IndexURI().buscar_aprovacoes_pendentes,
                "GET",
                null,
                token
            );
        } catch (error) {
            console.log(error);
            resposta.erros = error;
            resposta.sucesso = false;
        } finally {
            return resposta;
        }
    }

