    static async BuscarDespesasFreteDetalhes({ dataInicio, dataFim, cabecalhos, regiao, token }) {
        try {
            const response = await buscarDadosPrivado(
                IndexURI().buscar_despesas_regiao_detalhes,
                'POST',
                { dataInicio, dataFim, cabecalhos, regiao },
                token
            );
            return { sucesso: true, data: response.data };
        } catch (error) {
            return { sucesso: false, mensagem: error?.response?.data?.mensagem || 'Erro ao buscar detalhes', error };
        }
    }
