import React, { useEffect, useState } from 'react';
import { LojaServico } from '../../services/LojaServico';
import { EmbarcadorrServico } from '../../services/EmbarcadorServico';
import { errorMessage, successMessage, confirmMessage } from '../../components/Mensagem';
import { FaCheckCircle, FaTimesCircle } from 'react-icons/fa';

export default function AprovacaoLojas() {
  const [lojas, setLojas] = useState([]);
  const [loading, setLoading] = useState(false);
  const [erro, setErro] = useState('');
  const [selectedCNPJs, setSelectedCNPJs] = useState([]);

  useEffect(() => {
    async function fetchLojas() {
      setLoading(true);
      setErro('');
      try {
        const resposta = await EmbarcadorrServico.BuscarLojasPendentes();
        setLojas(resposta?.data || []);
      } catch (err) {
        setErro('Erro ao buscar lojas para aprovação.');
      } finally {
        setLoading(false);
      }
    }
    fetchLojas();
  }, []);

  const aprovarLoja = async (cnpj) => {
    const confirm = await confirmMessage('Confirma a aprovação desta loja?');
    if (!confirm.isConfirmed) return;

    try {
      const resposta = await EmbarcadorrServico.AprovarLoja([cnpj]);
      if (resposta?.sucesso || resposta?.mensagem === "Loja aprovada com sucesso.") {
        successMessage(resposta?.mensagem || "Loja aprovada com sucesso!");
        setLojas(lojas.filter(loja => loja.cnpj !== cnpj));
        setSelectedCNPJs(selectedCNPJs.filter(item => item !== cnpj));
      } else {
        errorMessage(resposta?.mensagem || "Erro ao aprovar loja.");
      }
    } catch (err) {
      errorMessage(err?.message || "Erro ao aprovar loja.");
    }
  };

  const rejeitarLoja = async (cnpj) => {
    const confirm = await confirmMessage('Confirma a rejeição desta loja?');
    if (!confirm.isConfirmed) return;

    try {
      const resposta = await EmbarcadorrServico.ReprovarLojas([cnpj]);
      if (resposta?.sucesso || resposta?.mensagem === "Loja rejeitada com sucesso.") {
        successMessage(resposta?.mensagem || "Loja rejeitada com sucesso!");
        setLojas(lojas.filter(loja => loja.cnpj !== cnpj));
        setSelectedCNPJs(selectedCNPJs.filter(item => item !== cnpj));
      } else {
        errorMessage(resposta?.mensagem || "Erro ao rejeitar loja.");
      }
    } catch (err) {
      errorMessage(err?.message || "Erro ao rejeitar loja.");
    }
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedCNPJs(lojas.map(loja => loja.cnpj));
    } else {
      setSelectedCNPJs([]);
    }
  };

  const handleSelectOne = (cnpj) => {
    setSelectedCNPJs(prev =>
      prev.includes(cnpj)
        ? prev.filter(item => item !== cnpj)
        : [...prev, cnpj]
    );
  };

  const aprovarSelecionados = async () => {
    if (selectedCNPJs.length === 0) {
      errorMessage("Selecione ao menos uma loja para aprovar.");
      return;
    }
    const confirm = await confirmMessage(`Confirma a aprovação das ${selectedCNPJs.length} lojas selecionadas?`);
    if (!confirm.isConfirmed) return;

    try {
      const resposta = await EmbarcadorrServico.AprovarLoja(selectedCNPJs);
      if (resposta?.sucesso || resposta?.mensagem === "Loja aprovada com sucesso.") {
        successMessage(resposta?.mensagem || "Lojas aprovadas com sucesso!");
        setLojas(lojas.filter(loja => !selectedCNPJs.includes(loja.cnpj)));
        setSelectedCNPJs([]);
      } else {
        errorMessage(resposta?.mensagem || "Erro ao aprovar lojas.");
      }
    } catch (err) {
      errorMessage(err?.message || "Erro ao aprovar lojas.");
    }
  };

  return (
    <div className="p-6">
      <div className="flex items-center mb-6">
        <h1 className="text-2xl font-bold mr-4">Aprovação de Lojas</h1>
        {lojas.length > 0 && (
          <div className="mb-2 flex items-center">
            <span className="text-sm font-semibold text-green-700 bg-green-100 px-3 py-1 rounded">
              Pendentes: {lojas.length}
            </span>
          </div>
        )}
      </div>
      {selectedCNPJs.length > 0 && (
        <button
          className="mb-4 px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700"
          onClick={aprovarSelecionados}
        >
          Aprovar Selecionados
        </button>
      )}
      {loading ? (
        <div className="text-green-700">Carregando...</div>
      ) : erro ? (
        <div className="text-red-600">{erro}</div>
      ) : lojas.length === 0 ? (
        <div className="text-gray-600">Nenhuma loja pendente de aprovação.</div>
      ) : (
        <table className="min-w-full bg-white border rounded shadow">
          <thead className="bg-gray-100">
            <tr>
              <th className="border px-4 py-2">
                <input
                  type="checkbox"
                  checked={selectedCNPJs.length === lojas.length && lojas.length > 0}
                  onChange={handleSelectAll}
                  title="Selecionar todos"
                />
              </th>
              <th className="border px-4 py-2">CNPJ</th>
              <th className="border px-4 py-2">Razão Social</th>
              <th className="border px-4 py-2">Nome Fantasia</th>
              <th className="border px-4 py-2">Número Loja</th>
              <th className="border px-4 py-2">Status</th>
              <th className="border px-4 py-2">Data Cadastro</th>
              <th className="border px-4 py-2">Ações</th>
            </tr>
          </thead>
          <tbody>
            {lojas.map((loja) => (
              <tr key={loja.cnpj}>
                <td className="border px-4 py-2 text-center">
                  <input
                    type="checkbox"
                    checked={selectedCNPJs.includes(loja.cnpj)}
                    onChange={() => handleSelectOne(loja.cnpj)}
                  />
                </td>
                <td className="border px-4 py-2">{loja.cnpj}</td>
                <td className="border px-4 py-2">{loja.razao_Social}</td>
                <td className="border px-4 py-2">{loja.nome_Fantasia}</td>
                <td className="border px-4 py-2">{loja.numero_Loja}</td>
                <td className="border px-4 py-2">
                  <span className={
                    loja.status_Aprovacao === "P" || loja.status_Aprovacao === "Pendente"
                      ? "text-red-600 font-semibold"
                      : "text-gray-600"
                  }>
                    {loja.status_Aprovacao === "P" ? "Pendente" : loja.status_Aprovacao}
                  </span>
                </td>
                <td className="border px-4 py-2">{new Date(loja.data_Cadastro).toLocaleDateString('pt-BR')}</td>
                <td className="border px-4 py-2 flex gap-2 justify-center items-center">
                  <button
                    style={{ height: '50px' }}
                    title="Aprovar"
                    className="text-green-600 hover:text-green-800"
                    onClick={() => aprovarLoja(loja.cnpj)}
                  >
                    <FaCheckCircle size={16} />
                  </button>
                  <button
                    style={{height: '50px'}}
                    title="Rejeitar"
                    className="text-red-600 hover:text-red-800"
                    onClick={() => rejeitarLoja(loja.cnpj)}
                  >
                    <FaTimesCircle size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
