import React, { useEffect, useState } from 'react';
import { FaCheckCircle, FaTimesCircle } from 'react-icons/fa';
import { TransportadorServico } from '../../services/TransportadorServico';
import { errorMessage, successMessage, confirmMessage } from '../../components/Mensagem';

export default function Aprovacao() {
  const [transportadoras, setTransportadoras] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');
  const [selectedCNPJs, setSelectedCNPJs] = useState([]);

  // Fetch pending transporters
  const carregarTransportadoras = async () => {
    setLoading(true);
    setMessage('');
    try {
      const resposta = await TransportadorServico.BuscarTransportadorPendenteAprovacao();
      const data = Array.isArray(resposta) ? resposta : resposta?.data || [];
      const transportadorasFormatadas = data.map(t => ({
        cnpj: t.cnpj,
        razao_Social: t.razao_Social,
        ie: t.ie,
        cep: t.cep,
        endereco: t.endereco,
        numero: t.numero,
        bairro: t.bairro,
        cidade: t.cidade,
        uf: t.uf,
        telefone: t.telefone,
        email: t.email,
        data_Cadastro: new Date(t.data_Cadastro).toLocaleDateString('pt-BR'),
        status_Aprovacao: t.status_Aprovacao === 'P' ? 'Pendente' : t.status_Aprovacao === 'A' ? 'Aprovado' : 'Reprovado',
        cD_Filial: t.cD_Filial,
      }));
      setTransportadoras(transportadorasFormatadas);
    } catch (error) {
      setTransportadoras([]);
      setMessage('Erro ao carregar transportadoras.');
      errorMessage('Erro ao carregar transportadoras.');
    }
    setLoading(false);
  };

  useEffect(() => {
    carregarTransportadoras();
  }, []);

  const handleAprovar = async (cnpj) => {
    const confirmed = await confirmMessage('Confirma aprovação deste transportador?');
    if (!confirmed.isConfirmed) return;

    setLoading(true);
    setMessage('');
    try {
      const resposta = await TransportadorServico.AprovarTransportadorLista([String(cnpj)]);
      if (resposta?.sucesso) {
        setMessage('Transportador aprovado com sucesso!');
        successMessage('Transportador aprovado com sucesso!');
        setSelectedCNPJs(selectedCNPJs.filter(item => item !== cnpj));
      } else {
        setMessage('Falha ao aprovar transportador.');
        errorMessage('Falha ao aprovar transportador.');
      }
    } catch (error) {
      setMessage('Erro ao aprovar transportador.');
      errorMessage('Erro ao aprovar transportador.');
    }
    await carregarTransportadoras();
    setLoading(false);
  };

  const handleReprovar = async (cnpj) => {
    const confirmed = await confirmMessage('Confirma reprovação deste transportador?');
    if (!confirmed.isConfirmed) return;
    setLoading(true);
    setMessage('');
    try {
      const resposta = await TransportadorServico.ReprovarTransportadorLista([cnpj]);
      if (resposta?.sucesso) {
        setMessage('Transportador reprovado com sucesso!');
        successMessage('Transportador reprovado com sucesso!');
        setSelectedCNPJs(selectedCNPJs.filter(item => item !== cnpj));
      } else {
        setMessage('Falha ao reprovar transportador.');
        errorMessage('Falha ao reprovar transportador.');
      }
    } catch (error) {
      setMessage('Erro ao reprovar transportador.');
      errorMessage('Erro ao reprovar transportador.');
    }
    await carregarTransportadoras();
    setLoading(false);
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedCNPJs(transportadoras.map(t => t.cnpj));
    } else {
      setSelectedCNPJs([]);
    }
  };

  const handleSelectOne = (cnpj) => {
    setSelectedCNPJs(prev =>
      prev.includes(cnpj)
        ? prev.filter(item => item !== cnpj)
        : [...prev, cnpj]
    );
  };

  const aprovarSelecionados = async () => {
    if (selectedCNPJs.length === 0) {
      errorMessage("Selecione ao menos um transportador para aprovar.");
      return;
    }
    const confirm = await confirmMessage(`Confirma a aprovação dos ${selectedCNPJs.length} transportadores selecionados?`);
    if (!confirm.isConfirmed) return;

    setLoading(true);
    setMessage('');
    try {
      const resposta = await TransportadorServico.AprovarTransportadorLista(selectedCNPJs);
      if (resposta?.sucesso) {
        setMessage('Transportadores aprovados com sucesso!');
        successMessage('Transportadores aprovados com sucesso!');
        setTransportadoras(transportadoras.filter(t => !selectedCNPJs.includes(t.cnpj)));
        setSelectedCNPJs([]);
      } else {
        setMessage('Falha ao aprovar transportadores.');
        errorMessage('Falha ao aprovar transportadores.');
      }
    } catch (error) {
      setMessage('Erro ao aprovar transportadores.');
      errorMessage('Erro ao aprovar transportadores.');
    }
    await carregarTransportadoras();
    setLoading(false);
  };

  return (
    <main className="flex-1 p-6 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold mb-6 text-left">Aprovação de Transportadoras</h1>
      {message && (
        <div className="mb-4 text-center text-blue-600 font-semibold">{message}</div>
      )}
      <div className="bg-white p-6 rounded shadow mb-6 overflow-auto">
        {selectedCNPJs.length > 0 && (
          <button
            className="mb-4 px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700"
            onClick={aprovarSelecionados}
          >
            Aprovar Selecionados
          </button>
        )}
        {loading ? (
          <div className="text-center py-8">Carregando...</div>
        ) : (
          <table className="w-full text-sm border-collapse">
            <thead>
              <tr>
                <th className="p-2 border text-center">
                  <input
                    type="checkbox"
                    checked={selectedCNPJs.length === transportadoras.length && transportadoras.length > 0}
                    onChange={handleSelectAll}
                    title="Selecionar todos"
                  />
                </th>
                <th className="p-2 border">CNPJ</th>
                <th className="p-2 border">Razão Social</th>
                <th className="p-2 border">IE</th>
                <th className="p-2 border">CEP</th>
                {/* <th className="p-2 border">Endereço</th>
                <th className="p-2 border">Número</th>
                <th className="p-2 border">Bairro</th> */}
                <th className="p-2 border">Cidade</th>
                <th className="p-2 border">UF</th>
                {/* <th className="p-2 border">Telefone</th> */}
                <th className="p-2 border">Email</th>
                <th className="p-2 border">Data Cadastro</th>
                <th className="p-2 border">Status Aprovação</th>
                {/* <th className="p-2 border">CD Filial</th> */}
                <th className="p-2 border text-center">Ações</th>
              </tr>
            </thead>
            <tbody>
              {transportadoras.map((t, idx) => (
                <tr key={idx} className="hover:bg-gray-50">
                  <td className="p-2 border text-center">
                    <input
                      type="checkbox"
                      checked={selectedCNPJs.includes(t.cnpj)}
                      onChange={() => handleSelectOne(t.cnpj)}
                    />
                  </td>
                  <td className="p-2 border">{t.cnpj}</td>
                  <td className="p-2 border">{t.razao_Social}</td>
                  <td className="p-2 border">{t.ie}</td>
                  <td className="p-2 border">{t.cep}</td>
                  {/* <td className="p-2 border">{t.endereco}</td>
                  <td className="p-2 border">{t.numero}</td>
                  <td className="p-2 border">{t.bairro}</td> */}
                  <td className="p-2 border">{t.cidade}</td>
                  <td className="p-2 border">{t.uf}</td>
                  {/* <td className="p-2 border">{t.telefone}</td> */}
                  <td className="p-2 border">{t.email}</td>
                  <td className="p-2 border">{t.data_Cadastro}</td>
                  <td className="p-2 border">{t.status_Aprovacao}</td>
                  {/* <td className="p-2 border">{t.cD_Filial}</td> */}
                  <td className="p-2 border text-center">
                    <button
                      className="mr-2 text-green-600 hover:text-green-800"
                      title="Aprovar"
                      style={{ height: '50px' }}
                      onClick={() => handleAprovar(t.cnpj)}
                    >
                      <FaCheckCircle size={15} />
                    </button>
                    <button
                      className="text-red-600 hover:text-red-800"
                      title="Reprovar"
                      style={{ height: '50px' }}
                      onClick={() => handleReprovar(t.cnpj)}
                    >
                      <FaTimesCircle size={15} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </main>
  );
}